local config = {
  ui_story_5076_50760100_1_dialog_content = "Cepat... Bangun, Re...!",
  ui_story_5076_50760100_2_dialog_content = "Siapa di sana?",
  ui_story_5076_50760100_3_dialog_content = "Dia terjebak dalam mimpi buruk... kita harus... Colossus...",
  ui_story_5076_50760100_4_dialog_content = "Tunggu, bukankah kau...?",
  ui_story_5076_50760100_5_dialog_content = "<size=45>Kembali—</size>",
  ui_story_5076_50760100_6_dialog_content = "Oh, kamu akhirnya bangun. Kau membuatku khawatir selama satu menit.",
  ui_story_5076_50760100_7_dialog_content = "Apa dengan tatapan itu? Tidak ingat teman Caelestitemu? Itu aku, Ludweiss!",
  ui_story_5076_50760100_8_dialog_content = "Sepertinya kamu baru saja mengalami mimpi buruk yang sangat buruk. Kamu tidak bangun, jadi Marcela memanggilku.",
  ui_story_5076_50760100_9_dialog_content = "Marcela? Marcela...",
  ui_story_5076_50760100_10_dialog_content = "Komandan? Apakah Anda baik-baik saja? Lupa tentang pengembara seperti saya itu satu hal, tapi bagaimana bisa Anda lupa tentang tunangan Anda?",
  ui_story_5076_50760100_11_dialog_content = "Saya di sini, Adras... Apakah kamu merasa tidak enak badan? Kamu terlihat sangat pucat.",
  ui_story_5076_50760100_12_dialog_content = "Marcela... Pakaianmu...",
  ui_story_5076_50760100_13_dialog_content = "... J-Jangan menatapku seperti itu. Ludweiss masih di sini, tahu.",
  ui_story_5076_50760100_14_dialog_content = "Masih menikmati pemandangan meski sudah beberapa hari berlalu, ya, Komandan? Masuk akal, karena pakaian Marcela jauh lebih imut dari sebelumnya.",
  ui_story_5076_50760100_15_dialog_content = "Tolong jangan menggodaku seperti itu...",
  ui_story_5076_50760100_16_dialog_content = "Dan pakaianku...",
  ui_story_5076_50760100_17_dialog_content = "Apakah kamu yakin sudah bangun? Jangan bilang kamu lupa tentang pernikahan.",
  ui_story_5076_50760100_18_dialog_content = "Pernikahan... Benar, aku baru saja bermimpi.",
  ui_story_5076_50760100_19_dialog_content = "Aku berdiri dalam kegelapan, dan yang bisa aku lihat hanyalah sebuah mural di dinding... Gambarannya samar, tapi aku rasa itu tentang pernikahan.",
  ui_story_5076_50760100_20_dialog_content = "Aku terjebak di sana begitu lama, dan aku tidak bisa mengingat apa-apa. Itu adalah mimpi buruk... Satu yang berlangsung selama seribu tahun.",
  ui_story_5076_50760100_21_dialog_content = "Aku tidak berpikir Adras hanya mimpi buruk, Ludweiss. Apakah kamu berpikir dia mungkin sakit?",
  ui_story_5076_50760100_22_dialog_content = "Saya tidak bisa memastikan, tapi biarkan saya mencoba menggunakan kekuatan psikis saya padanya.",
  ui_story_5076_50760100_23_dialog_content = "Adras, sudah bangun?",
  ui_story_5076_50760100_24_dialog_content = "...",
  ui_story_5076_50760100_25_dialog_content = "Ini—!",
  ui_story_5076_50760100_26_dialog_content = "Kenapa... Kenapa kau menangis?",
  ui_story_5076_50760100_27_dialog_content = "Apakah kamu bermimpi tentang masa depan yang jauh, Adras? Atau apakah kamu memimpikan aku setelah semua tahun itu?",
  ui_story_5076_50760100_28_dialog_content = "Apa yang kamu bicarakan, Ludweiss?",
  ui_story_5076_50760100_29_dialog_content = "Ah?",
  ui_story_5076_50760100_30_dialog_content = "Maaf, aku terjebak dalam mimpi buruk Adras dan sempat lupa diri sebentar...",
  ui_story_5076_50760100_31_dialog_content = "Jadi, bahkan Caelestites bisa terganggu oleh mimpi, ya?",
  ui_story_5076_50760100_32_dialog_content = "A-Akhirnya kamu bangun... Hei, berhenti tertawa! Bersyukurlah aku menarikmu keluar dari mimpi buruk itu!",
  ui_story_5076_50760100_33_dialog_content = "Terima kasih, Ludweiss. Aku mulai merasa sangat khawatir.",
  ui_story_5076_50760100_34_dialog_content = "Terima kasih... Tapi apa yang kamu katakan tentang mimpiku barusan—",
  ui_story_5076_50760100_35_dialog_content = "Komandan, saya minta maaf atas gangguannya, tetapi ada pesan mendesak!",
  ui_story_5076_50760100_36_dialog_content = "Jenderal Achilles memerintahkan legiun untuk berkumpul.",
  ui_story_5076_50760100_37_dialog_content = "Mengerti. Aku akan segera ke sana.",
  ui_story_5076_50760100_38_dialog_content = "Maafkan aku telah membuat kalian berdua khawatir. Aku berjanji akan segera kembali.",
  ui_story_5076_50760100_39_dialog_content = "Heh, coba saja jangan membuat Marcela menunggu.",
  ui_story_5076_50760100_40_dialog_content = "Lagi pula, kamu terus membicarakan tentang pernikahan dalam tidurmu, jadi mungkin kamu tidak perlu aku untuk mengingatkanmu.",
  ui_story_5076_50760100_41_dialog_content = "J-Jangan dengarkan dia. Misi adalah yang utama, dan Jenderal Achilles sedang menunggumu.",
  ui_story_5076_50760100_42_dialog_content = "Aku akan kembali sesegera mungkin.",
  ui_story_5076_50760100_43_dialog_content = "... Eclipsite yang jahat telah muncul kembali di utara, mengancam untuk menyerbu perbatasan kita.",
  ui_story_5076_50760100_44_dialog_content = "Raja telah memerintahkan kita untuk membasmi monster-monster itu!",
  ui_story_5076_50760100_45_dialog_content = "Setelah kamu diberhentikan, kumpulkan perlengkapanmu dan ucapkan selamat tinggal pada orang-orang yang kamu cintai.",
  ui_story_5076_50760100_46_dialog_content = "Paham!",
  ui_story_5076_50760100_47_dialog_content = "Bagaimana kehidupan normalmu, Adras?",
  ui_story_5076_50760100_48_dialog_content = "Damai. Aku masih belum sepenuhnya terbiasa dengan ini.",
  ui_story_5076_50760100_49_dialog_content = "Komandan, saatnya meninggalkan pertempuran dan menerima kehidupan yang damai ini.",
  ui_story_5076_50760100_50_dialog_content = "Kamu akan segera menikah, tapi kamu masih... Itu cukup mengkhawatirkan.",
  ui_story_5076_50760100_51_dialog_content = "Kami akan segera pergi, Adras, tapi selamat atas pernikahanmu.",
  ui_story_5076_50760100_52_dialog_content = "Apa yang kamu bicarakan? Hampir terdengar seperti kamu tidak berniat membiarkanku pergi dalam misi ini.",
  ui_story_5076_50760100_53_dialog_content = "Benar. Laporan tentang Eclipsites di utara tidak memerlukan seluruh kekuatan pasukan kita.",
  ui_story_5076_50760100_54_dialog_content = "Misi Anda adalah tinggal di sini dan menikmati hidup yang telah Anda ciptakan untuk diri sendiri.",
  ui_story_5076_50760100_55_dialog_content = "Kamu telah mengorbankan bertahun-tahun hidupmu demi orang lain, dan sekarang saatnya bagi kamu untuk mengejar kebahagiaanmu sendiri. Setidaknya, kamu bisa melihat semua yang telah kamu lindungi dengan Marcela di sisimu.",
  ui_story_5076_50760100_56_dialog_content = "Jenderal, saya...",
  ui_story_5076_50760100_57_dialog_content = "Komandan Adras, sesuai dengan hukum dan kebijakan kerajaan, Anda sekarang diberikan cuti pernikahan agar Anda dapat menikmati pernikahan Anda!",
  ui_story_5076_50760100_58_dialog_content = "Tenangkan pikiranmu dan nikmati waktu luangmu.",
  ui_story_5076_50760100_59_dialog_content = "Selamat, Komandan Adras!",
  ui_story_5076_50760100_60_dialog_content = "Kamu...",
  ui_story_5076_50760100_61_dialog_content = "Mungkin kamu sudah punya si kecil saat kami kembali!",
  ui_story_5076_50760100_62_dialog_content = "Komandan mungkin bukan yang terbaik dalam berurusan dengan anak-anak. Semoga anaknya lebih mirip dengan ibunya.",
  ui_story_5076_50760100_63_dialog_content = "Baiklah, semua orang, tinggalkan hadiah-hadiah kalian dan lakukan urusan kalian. Adras, kamu tinggal di sini.",
  ui_story_5076_50760100_64_dialog_content = "Apakah kamu mendengar tentang <color=#FFB400>High Priest Lucius</color> yang kembali ke ibu kota kerajaan?",
  ui_story_5076_50760100_65_dialog_content = "Lucius? Maksudmu dia...",
  ui_story_5076_50760100_66_dialog_content = "Komandan Adras, semua pemberontak ada di sini.",
  ui_story_5076_50760100_67_dialog_content = "Lepaskan aku, lepaskan aku! Apakah kamu tahu siapa aku?",
  ui_story_5076_50760100_68_dialog_content = "Aku Lucius, Pendeta Agung yang seharusnya kalian hormati! Tunjukkan rasa hormatmu padaku!",
  ui_story_5076_50760100_69_dialog_content = "Yang saya lihat hanyalah seorang pengkhianat, dan tidak lebih dari itu.",
  ui_story_5076_50760100_70_dialog_content = "Oh? Jadi pahlawan kita yang perkasa ini yang mengatur semuanya? Tidak heran mereka berani menyerbu dengan pasukan yang begitu sedikit.",
  ui_story_5076_50760100_71_dialog_content = "Beraninya kamu berlagak sombong padahal kau hanyalah seorang rakyat jelata!",
  ui_story_5076_50760100_72_dialog_content = "Anda membahayakan kedamaian kerajaan, dan dengan ini Anda ditangkap!",
  ui_story_5076_50760100_73_dialog_content = "Bertobatlah atas kerugian yang telah kamu berikan kepada orang-orang.",
  ui_story_5076_50760100_74_dialog_content = "Lepaskan aku! Kamu pikir kamu siapa?! Kamu tidak lebih dari pion dari Penatua Utama!",
  ui_story_5076_50760100_75_dialog_content = "Kamu akan menyesal telah melakukan ini! Ingat kata-kataku, aku akan membuatmu membayar—",
  ui_story_5076_50760100_76_dialog_content = "Bukankah dia ditemukan bersalah karena pengkhianatan?",
  ui_story_5076_50760100_77_dialog_content = "Ya, tetapi Lucius masih seorang bangsawan. Meskipun memiliki kontak dengan para pemberontak, dia hanya dinyatakan bersalah karena asosiasinya.",
  ui_story_5076_50760100_78_dialog_content = "Ketika dia jatuh dari kekuasaan, pengaruh Dewan Penatua tumbuh secara tak terduga. Kembalinya dia ke relevansi politik hanya agar raja bisa menjaga Prime Elder tetap terkendali.",
  ui_story_5076_50760100_79_dialog_content = "Raja dan aku telah berteman selama bertahun-tahun, namun akhir-akhir ini dia semakin asing bagiku. Sepertinya dia telah menjadi sangat mahir dalam menggunakan metode seperti ini.",
  ui_story_5076_50760100_80_dialog_content = "Hati-hati, Adras.",
  ui_story_5076_50760100_81_dialog_content = "Saya hanya menjalankan perintah saya. Dia tidak seharusnya menyalahkanku.",
  ui_story_5076_50760100_82_dialog_content = "Tidak semua orang mematuhi aturan dan berpikir sejernih kamu.",
  ui_story_5076_50760100_83_dialog_content = "Dalam hal apapun, ingatlah untuk tetap waspada bahkan dalam kehidupan baru yang damai. Kesialan selalu mengintai dalam bayangan.",
  ui_story_5076_50760100_84_dialog_content = "Saat pasukan pemberontak menduduki kota itu... Itulah saat saya bertemu dengannya.",
  ui_story_5076_50760100_85_dialog_content = "Ada lebih banyak hal di dunia ini daripada hanya kemalangan.",
  ui_story_5076_50760100_86_dialog_content = "Anda telah berubah, Adras.",
  ui_story_5076_50760100_87_dialog_content = "Saya senang untukmu. Sepertinya kau akhirnya menemukan jawaban yang selama ini kau cari dalam hidup.",
  ui_story_5076_50760100_88_dialog_content = "Baiklah, itu saja dari saya, semua hadiah juga sudah ada di sini. Nikmati waktu-waktu baik yang akan datang!",
  ui_story_5076_50760100_89_dialog_content = "Aku akan berdoa untuk kepulanganmu yang selamat, Jenderal Achilles.",
  ui_story_5076_50760100_90_dialog_content = "Terima kasih, sekarang pergi. Sudah hampir waktunya untuk pernikahan, jadi jangan biarkan Marcela menunggu.",
  ui_story_5076_50760200_1_dialog_content = "Lihat di sana! Itu pahlawan legendaris, Adras, yang berjalan menuju kita!",
  ui_story_5076_50760200_2_dialog_content = "Adras? Pahlawan yang meredam pemberontakan di masa lalu?",
  ui_story_5076_50760200_3_dialog_content = "Dulu? Saya agak baru di sini; apa yang terjadi saat itu?",
  ui_story_5076_50760200_4_dialog_content = "Biarkan saya ceritakan, selama tahun-tahun itu...",
  ui_story_5076_50760200_5_dialog_content = "Pemberontak! Saya, atas nama Legiun Northwind, di sini untuk memberi Anda kesempatan: bala bantuan Anda telah dipotong; MENYERAH SEKARANG!",
  ui_story_5076_50760200_6_dialog_content = "Tetap bermimpi! Selama kota ini berdiri, kami tidak akan kalah...",
  ui_story_5076_50760200_7_dialog_content = "Pemanah! Tembak! Seseorang, bawa orang-orang itu ke sini! Biarkan mereka melindungi serangan!",
  ui_story_5076_50760200_8_dialog_content = "Legiun pertama? Jadi apa? Dengan semua sandera yang kita miliki di kota ini...",
  ui_story_5076_50760200_9_dialog_content = "Kapten, lihat! Mereka menyerang kita dengan perisai yang diangkat tinggi!",
  ui_story_5076_50760200_10_dialog_content = "Apa? Mereka pikir mereka tak terkalahkan? Terus tembak! Jangan biarkan mereka mendekati tembok kota!",
  ui_story_5076_50760200_11_dialog_content = "Urgh—!",
  ui_story_5076_50760200_12_dialog_content = "Apa yang terjadi di bawah sana?",
  ui_story_5076_50760200_13_dialog_content = "Sebuah skuad menyelinap masuk dari belakang selama kekacauan! Mereka sudah berada di kota!",
  ui_story_5076_50760200_14_dialog_content = "Ada berapa banyak?",
  ui_story_5076_50760200_15_dialog_content = "Hanya segelintir dari mereka, masing-masing hanya memegang sebuah pedang—mereka memanjat tembok dengan tangan kosong!",
  ui_story_5076_50760200_16_dialog_content = "Sekelompok orang yang tidak berguna! Haruskah aku menangani ini sendiri?!",
  ui_story_5076_50760200_17_dialog_content = "Tapi... pria yang memimpin mereka sangat kuat...",
  ui_story_5076_50760200_18_dialog_content = "Berhenti melawan! Saya tidak akan menyerang warga sipil yang tidak bersenjata!",
  ui_story_5076_50760200_19_dialog_content = "Kalian juga warga kerajaan ini, jadi berhentilah menyakiti rekan sebangsamu!",
  ui_story_5076_50760200_20_dialog_content = "Idiot bodoh, dikelilingi oleh kita namun masih berlagak keras... TANGKAP MEREKA!",
  ui_story_5076_50760200_21_dialog_content = "Kamu sudah punya kesempatan, penjahat—Semua pasukan, bunuh musuh yang terlihat!",
  ui_story_5076_50760200_22_dialog_content = "Kalahkan komandan mereka dan buat jalan bagi teman-teman kita yang menyerang kota! Ikuti saya!",
  ui_story_5076_50760200_23_dialog_content = "Hentikan mereka! Panggil pemanah ke sini!",
  ui_story_5076_50760200_24_dialog_content = "Kapten, kabar buruk! Seseorang telah merampok penjara tempat para penduduk ditahan, dan gudang kita sedang terbakar!",
  ui_story_5076_50760200_25_dialog_content = "Kapten! Gerbang barat telah dibuka; ada yang membantu warga sipil melarikan diri!",
  ui_story_5076_50760200_26_dialog_content = "Cap-Kapten! Di belakang kita!",
  ui_story_5076_50760200_27_dialog_content = "<size=40>Sialan!</size> Apa yang terjadi lagi—!",
  ui_story_5076_50760200_28_dialog_content = "<size=45>Mati!</size>",
  ui_story_5076_50760200_29_dialog_content = "Kapten!",
  ui_story_5076_50760200_30_dialog_content = "Pemberontak! Kaptenmu sudah mati! Letakkan senjatamu, semua kalian!",
  ui_story_5076_50760200_31_dialog_content = "Telah cukup banyak pembunuhan tak berarti di kota ini, tetapi sekarang adalah saatnya untuk mengakhiri ini! Tidak ada lagi yang harus mati selama kau membawakan aku pemimpinmu!",
  ui_story_5076_50760200_32_dialog_content = "Mengapa kami harus percaya padamu? Apa buktimu...",
  ui_story_5076_50760200_33_dialog_content = "Karena aku adalah Adras!",
  ui_story_5076_50760200_34_dialog_content = "Pria yang akan mengakhiri perang ini!",
  ui_story_5076_50760200_35_dialog_content = "Lihat betapa cepatnya dia berlari! Mungkin dia juga bergabung dalam ekspedisi?",
  ui_story_5076_50760200_36_dialog_content = "Jika pahlawan itu juga pergi ke sana, anak saya di tentara harusnya lebih aman, bukan...?",
  ui_story_5076_50760200_37_dialog_content = "Apakah kamu lupa? Pahlawan akan menikah; upacara sudah siap semua.",
  ui_story_5076_50760200_38_dialog_content = "Marcela!",
  ui_story_5076_50760200_39_dialog_content = "Wow! Jangan membuatku takut seperti itu! Apa masalahnya?",
  ui_story_5076_50760200_40_dialog_content = "Saya tidak membuatmu menunggu terlalu lama... Bukan?",
  ui_story_5076_50760200_41_dialog_content = "Aku baik-baik saja. Yang aku khawatirkan adalah kamu. Apa yang terjadi di Legiun?",
  ui_story_5076_50760200_42_dialog_content = "Eclipsite mulai berkumpul di utara. Jenderal telah memberikan perintah untuk membasmi mereka.",
  ui_story_5076_50760200_43_dialog_content = "Dan kau tidak pergi?",
  ui_story_5076_50760200_44_dialog_content = "Jenderal Achilles mengatakan bahwa jumlah mereka tidak memerlukan kehadiranku. Dia memberiku cuti agar kita bisa menghabiskan pernikahan kita dengan damai.",
  ui_story_5076_50760200_45_dialog_content = "Jika ini demi saya, Anda tidak perlu—",
  ui_story_5076_50760200_46_dialog_content = "Anda mengatakan atap panti asuhan perlu diperbaiki, bukan? Saya memiliki waktu untuk menanganinya sekarang.",
  ui_story_5076_50760200_47_dialog_content = "Aku ingin menghabiskan beberapa hari bersamamu di luar kota, jika itu tidak masalah?",
  ui_story_5076_50760200_48_dialog_content = "... Tentu. Dengan senang hati.",
  ui_story_5076_50760200_49_dialog_content = "<color=#e8d9bb>Beberapa hari kemudian</color>",
  ui_story_5076_50760200_50_dialog_content = "Pernikahan sudah di depan mata, dan kalian berdua tiba-tiba ingin melakukan perjalanan keluar kota?",
  ui_story_5076_50760200_51_dialog_content = "Hah? Saya hanya berpikir kita akan sibuk selama beberapa hari ke depan, jadi saya ingin menyiapkan cukup materi pengajaran untuk anak-anak.",
  ui_story_5076_50760200_52_dialog_content = "Dan kamu tidak bisa meninggalkan itu saja padaku?",
  ui_story_5076_50760200_53_dialog_content = "Bukankah kamu akan bepergian ke tempat baru segera? Selain itu, kamu sudah cukup banyak membantuku dengan mengkompilasinya. Aku tidak bisa terus mengandalkanmu.",
  ui_story_5076_50760200_54_dialog_content = "Berangkat di jalan lagi, ya? Jaga dirimu baik-baik, Ludweiss.",
  ui_story_5076_50760200_55_dialog_content = "Sama untuk kalian berdua... Panti asuhan tampak jauh lebih bagus kali ini. Kalian benar-benar telah memberikan yang terbaik, bukan, Adras?",
  ui_story_5076_50760200_56_dialog_content = "Saya tidak keberatan, asalkan itu untuk anak-anak.",
  ui_story_5076_50760200_57_dialog_content = "Jadi, apa yang sedang kamu lakukan sekarang?",
  ui_story_5076_50760200_58_dialog_content = "Membuat roti.",
  ui_story_5076_50760200_59_dialog_content = "Bentuk yang mewah sekali. Itu sama sekali tidak cocok untukmu, tahu.",
  ui_story_5076_50760200_60_dialog_content = "Anda bisa ambil beberapa, jika Anda mau.",
  ui_story_5076_50760200_61_dialog_content = "Adras cukup terampil membuat roti. Sebelum dia menjadi seorang prajurit, dia hampir menyembah tukang roti setempat dan bahkan pernah menjadi muridnya untuk sementara waktu.",
  ui_story_5076_50760200_62_dialog_content = "Itu karena dia selalu membagikan roti kepada anak-anak di jalanan.",
  ui_story_5076_50760200_63_dialog_content = "Adras, itu Adras!",
  ui_story_5076_50760200_64_dialog_content = "Jangan peluk aku. Aku terlumuri tepung.",
  ui_story_5076_50760200_65_dialog_content = "Kita belum lapar; ayo berlatih dulu.",
  ui_story_5076_50760200_66_dialog_content = "Tolong ajari kami beberapa keterampilan pedang; kami juga ingin melindungi Marcela!",
  ui_story_5076_50760200_67_dialog_content = "Kamu tidak akan bisa makan roti ini jika aku tidak memanggangnya sekarang juga.",
  ui_story_5076_50760200_68_dialog_content = "Keterampilan pedang dulu! Itu lebih penting, tahu!",
  ui_story_5076_50760200_69_dialog_content = "Marcela...",
  ui_story_5076_50760200_70_dialog_content = "Beri dia sedikit ruang. Dia akan bersamamu setelah dia selesai memasukkan roti ke dalam oven, oke?",
  ui_story_5076_50760200_71_dialog_content = "Baiklah…",
  ui_story_5076_50760200_72_dialog_content = "Adras tidak berdaya menghadapi anak-anak itu, dan namun Anda bisa membuat mereka mendengarkan hanya dengan beberapa kata.",
  ui_story_5076_50760200_73_dialog_content = "Yah, setelah semua, aku telah mengendalikan mereka sejak mereka masih kecil.",
  ui_story_5076_50760200_74_dialog_content = "Hampir saja aku lupa... Meski kau lebih muda dariku, kau telah mengelola panti asuhan ini selama bertahun-tahun. Kau benar-benar orang yang luar biasa.",
  ui_story_5076_50760200_75_dialog_content = "Saya telah melihat berbagai jenis perang dan pertikaian dalam perjalanan saya, tetapi jarang bertemu seseorang seperti kamu yang membantu anak-anak yang telah kehilangan segalanya.",
  ui_story_5076_50760200_76_dialog_content = "Mungkin karena... Saya juga tumbuh besar di panti asuhan.",
  ui_story_5076_50760200_77_dialog_content = "Dan meski aku kehilangan segalanya, selama ini banyak orang baik hati yang telah menjagaku. Ini adalah cara saya untuk mengungkapkan rasa terima kasih dan membalas kebaikan yang telah diberikan dunia kepada saya.",
  ui_story_5076_50760200_78_dialog_content = "... Itu harusnya cukup. Marcela, aku akan... pergi berlatih dengan anak-anak sekarang.",
  ui_story_5076_50760200_79_dialog_content = "Jangan terlalu keras pada mereka, ya?",
  ui_story_5076_50760200_80_dialog_content = "Ludweiss.",
  ui_story_5076_50760200_81_dialog_content = "Hmm?",
  ui_story_5076_50760200_82_dialog_content = "Saya yakin Anda telah melihat lebih banyak tragedi dalam perjalanan Anda daripada yang bisa Anda hitung... Tapi tolong jangan biarkan itu membuat Anda putus asa. Dunia ini masih penuh kebaikan.",
  ui_story_5076_50760200_83_dialog_content = "Tolong jangan berhenti percaya pada orang lain.",
  ui_story_5076_50760200_84_dialog_content = "Tentu saja aku tahu itu. Lagipula, bertemu dengan kalian berdua hanyalah satu hal baik lainnya tentang dunia ini.",
  ui_story_5076_50760200_85_dialog_content = "Sangat menakjubkan untuk berpikir bahwa saya tiba di kerajaan ini tepat ketika semua orang merayakan kembalinya Adras.",
  ui_story_5076_50760200_86_dialog_content = "Bahkan sekarang, saya masih dapat mengingat senyum dan sorak-sorai di setiap jalan ibu kota kerajaan.",
  ui_story_5076_50760200_87_dialog_content = "Aku tahu maksudmu! Pertemuan pertama kali dengan pahlawan Adras selalu memberikan efek yang mempesona pada orang-orang.",
  ui_story_5076_50760200_88_dialog_content = "Sepertinya banyak pameran dari Anda, calon Ibu Adras.",
  ui_story_5076_50760200_89_dialog_content = "I-Itu bukan maksudku!",
  ui_story_5076_50760200_90_dialog_content = "Aku juga sering mendengar kisah heroik Adras. Itulah mengapa aku mengerti kenapa orang-orang merasa begitu aman saat melihatnya.",
  ui_story_5076_50760200_91_dialog_content = "Semua anak-anak juga mengaguminya. Dia adalah pahlawan semua orang, tapi...",
  ui_story_5076_50760200_92_dialog_content = "Marcela?",
  ui_story_5076_50760200_93_dialog_content = "Hah? O-Oh, itu bukan apa-apa!",
  ui_story_5076_50760200_94_dialog_content = "Aku lupa bertanya tadi, tapi kamu mau pergi ke mana selanjutnya?",
  ui_story_5076_50760200_95_dialog_content = "Aku akan bepergian mengelilingi kerajaan bersama beberapa teman baru sebelum kembali ke sini. Mereka orang-orang yang cukup menarik, sama seperti Adras.",
  ui_story_5076_50760200_96_dialog_content = "Sayangnya, sekarang bukan waktunya untuk membicarakan hal ini. Saya akan pastikan untuk memperkenalkan Anda kepada mereka ketika ada kesempatan.",
  ui_story_5076_50760200_97_dialog_content = "Kamu akan tetap tinggal untuk pernikahan kami setidaknya, kan...?",
  ui_story_5076_50760200_98_dialog_content = "Tentu saja aku. Jangan khawatir tentang itu.",
  ui_story_5076_50760300_1_dialog_content = "Mencari sesuatu, Adras? Kenapa kamu tampak begitu khawatir?",
  ui_story_5076_50760300_2_dialog_content = "Ludweiss, apakah kamu telah melihat Marcela? Dia menghilang begitu saja pagi ini tanpa mengucapkan sepatah kata pun...",
  ui_story_5076_50760300_3_dialog_content = "Jangan terlalu khawatir. Ini hanya satu pagi.",
  ui_story_5076_50760300_4_dialog_content = "... Dengan semakin dekatnya pernikahan, rasanya ada sesuatu yang membebani hatinya, tapi dia tidak mau memberitahuku apa itu.",
  ui_story_5076_50760300_5_dialog_content = "Bisakah kamu membantuku mencarinya, Ludweiss?",
  ui_story_5076_50760300_6_dialog_content = "Saya mengerti. Jangan khawatir. Saya akan menggunakan kekuatan psikis saya untuk membantu Anda menemukannya.",
  ui_story_5076_50760300_7_dialog_content = "Tenang saja dan ikuti aku.",
  ui_story_5076_50760300_8_dialog_content = "Di sana! Dia di depan kuil!",
  ui_story_5076_50760300_9_dialog_content = "Hah? Dia... memberi makan kucing?",
  ui_story_5076_50760300_10_dialog_content = "Tidak, dia tampak seperti sedang linglung. Kucing itu hampir selesai memakan makanan yang dia bawakan—Pasti ada sesuatu yang mengganggunya setelah semua ini.",
  ui_story_5076_50760300_11_dialog_content = "Ludweiss... Bisakah kamu pergi bicara dengannya?",
  ui_story_5076_50760300_12_dialog_content = "Apa masalahnya? Apakah komandan kita yang tak kenal takut ini khawatir bahwa tunangannya sendiri tidak ingin berbicara dengannya?",
  ui_story_5076_50760300_13_dialog_content = "Tidak... Aku takut dia tidak akan memberitahukan yang sebenarnya padaku.",
  ui_story_5076_50760300_14_dialog_content = "Tapi jika dia berbicara dengan Caelestite pembaca pikiran, dia kemungkinan besar akan memberi tahu kamu apa yang ada di pikirannya... Aku tidak ingin dia menyembunyikan masalahnya dari aku demi kebaikanku.",
  ui_story_5076_50760300_15_dialog_content = "Baik, baik. Jujur saja, kalian berdua bertingkah seperti remaja yang canggung padahal kalian akan menikah besok.",
  ui_story_5076_50760300_16_dialog_content = "A-Ahem! Senang bertemu denganmu di sini, Marcela! Sedang memberi makan salah satu babi liar, huh?",
  ui_story_5076_50760300_17_dialog_content = "L-Ludweiss?",
  ui_story_5076_50760300_18_dialog_content = "Seorang komandan pasti akan khawatir melihat kamu di sini sendirian.",
  ui_story_5076_50760300_19_dialog_content = "Hah? Ah!",
  ui_story_5076_50760300_20_dialog_content = "Kamu benar, Adras mungkin khawatir padaku! Aku harus kembali—",
  ui_story_5076_50760300_21_dialog_content = "Kenapa terburu-buru? Apa kamu tidak ingin menceritakan apa yang ada di pikiranmu terlebih dahulu?",
  ui_story_5076_50760300_22_dialog_content = "Tidak ada gunanya menyembunyikannya dariku. Lagipula, kami Caelestites dikenal dengan kemampuan kami untuk memahami emosi. Bahkan, Anda bisa bilang kami adalah orang-orang cinta!",
  ui_story_5076_50760300_23_dialog_content = "Ada sesuatu yang mengganggumu selama beberapa hari terakhir, bukan?",
  ui_story_5076_50760300_24_dialog_content = "Begitu ya... Memang tidak ada yang bisa disembunyikan darimu.",
  ui_story_5076_50760300_25_dialog_content = "Jadi, apa yang mengganggumu belakangan ini?",
  ui_story_5076_50760300_26_dialog_content = "Ini bukan apa-apa sebenarnya, aku hanya... Mungkin karena pernikahan sudah sangat dekat, tapi aku merasa sedikit takut.",
  ui_story_5076_50760300_27_dialog_content = "Takut?",
  ui_story_5076_50760300_28_dialog_content = "Dahulu kala, saya sama seperti semua orang yang telah mendengar cerita tentang Adras, pahlawan rakyat.",
  ui_story_5076_50760300_29_dialog_content = "Selalu berpikir bahwa bertemu dengan legenda seperti dia adalah hal yang mustahil, tetapi dalam kekacauan hari itu... aku melihatnya.",
  ui_story_5076_50760300_30_dialog_content = "Meski terluka, dia mengalahkan orang-orang itu begitu mudah dan menyatakan bahwa kota itu aman.",
  ui_story_5076_50760300_31_dialog_content = "Sebuah kisah klasik tentang seorang gadis muda yang jatuh cinta pada seorang kesatria berbaju besi bersinar. Apakah itu saat kamu jatuh cinta berat padanya?",
  ui_story_5076_50760300_32_dialog_content = "Sebaliknya, sebenarnya—Hatiku merasa tak tertahankan muram karena aku tidak bisa menerima bahwa pahlawan kita tidak sepenuhnya jujur.",
  ui_story_5076_50760300_33_dialog_content = "Pahlawan dalam legenda kami seharusnya tak terkalahkan, namun dia penuh dengan luka yang tak terhitung jumlahnya. Itu membuat saya bertanya-tanya berapa kali hal ini terjadi padanya, dan apakah ada orang yang pernah peduli padanya.",
  ui_story_5076_50760300_34_dialog_content = "Tak lama kemudian, saya menemukan diri saya melakukan hal yang sama. Merawatnya, memahaminya...",
  ui_story_5076_50760300_35_dialog_content = "Tapi bukankah itu hal yang baik? Memperlakukannya seperti manusia yang hidup dan bernafas?",
  ui_story_5076_50760300_36_dialog_content = "Tapi... tidakkah kamu pikir saya telah terlalu banyak mencampuri hidupnya?",
  ui_story_5076_50760300_37_dialog_content = "Karena aku, dia tidak bisa pergi dalam misi penting bersama prajurit-prajuritnya... Apakah dia benar-benar bersedia meninggalkan tugasnya seperti ini?",
  ui_story_5076_50760300_38_dialog_content = "Adras tampak sangat bahagia menurutku, bagaimana menurutmu?",
  ui_story_5076_50760300_39_dialog_content = "Dia pernah memberitahuku bahwa bahkan saat masih kecil, dia tidak pernah jauh dari medan perang. Karena itu, dia tidak tahu apa itu kebahagiaan. Itulah sebabnya hatiku sangat gembira melihatnya bermain dengan riang bersama anak-anak...",
  ui_story_5076_50760300_40_dialog_content = "Tapi, saya bisa merasakan dia tidak terbiasa hidup seperti ini, dan sepertinya dia hanya melakukannya karena saya.",
  ui_story_5076_50760300_41_dialog_content = "Memberinya rumah untuk kembali adalah hal yang indah—",
  ui_story_5076_50760300_42_dialog_content = "Namun kehidupan normal inilah yang menjadi alasan dia mulai mengalami mimpi buruk yang sangat mengerikan.",
  ui_story_5076_50760300_43_dialog_content = "Adras adalah... seorang pahlawan bagi rakyat. Aku hanya khawatir bahwa aku sedang mengekangnya.",
  ui_story_5076_50760300_44_dialog_content = "Ah, tapi jangan terlalu khawatir tentang itu. Saya yakin itu hanya gugup sebelum pernikahan yang sedang menghampiri saya...",
  ui_story_5076_50760300_45_dialog_content = "Apakah kamu sudah menyebutkan semua ini kepada Adras? Tidak, kan?",
  ui_story_5076_50760300_46_dialog_content = "... Pada Hari Kemenangan, sang raja secara pribadi mengunjunginya. Beberapa orang bahkan menyarankan untuk mendirikan patungnya di alun-alun kota.",
  ui_story_5076_50760300_47_dialog_content = "Tapi setelah itu, petualangan heroik Adras berakhir. Orang-orang perlahan mulai melupakan dia, dan masalah itu dibiarkan tidak terselesaikan.",
  ui_story_5076_50760300_48_dialog_content = "Aku tahu dia tidak peduli tentang ketenaran atau kemuliaan, tapi aku tidak bisa tidak merasa bahwa dia telah menyerahkan begitu banyak karena aku.",
  ui_story_5076_50760300_49_dialog_content = "Saya sangat berterima kasih kepadanya karena telah membantu saya menjalankan panti asuhan ini, tetapi dia masih Adras, pahlawan rakyat.",
  ui_story_5076_50760300_50_dialog_content = "Dia masih menjadi bintang yang bersinar, satu yang membakar dengan ambisi yang besar.",
  ui_story_5076_50760300_51_dialog_content = "Sama seperti saya memiliki hal-hal yang hanya bisa saya lakukan, Adras memiliki hal-hal yang hanya bisa dia capai.",
  ui_story_5076_50760300_52_dialog_content = "Kamu tidak mengatakan hal-hal ini karena kamu ingin meninggalkannya, 'kan...?",
  ui_story_5076_50760300_53_dialog_content = "Apa kamu bercanda? Aku hanya akan menyakitinya dengan melakukan hal seperti itu... serta menyakiti diriku sendiri.",
  ui_story_5076_50760300_54_dialog_content = "Saya hanya berharap dia bisa bebas.",
  ui_story_5076_50760300_55_dialog_content = "Jika hatinya menyuruhnya untuk berjuang demi rumah dan negeri, maka itulah yang saya inginkan dia lakukan. Saya tidak ingin dia tinggal di sini hanya karena saya...",
  ui_story_5076_50760300_56_dialog_content = "Apakah itu pendapatmu? Karena sejauh yang bisa saya lihat, Adras masih pahlawan yang sama seperti dia di hari itu.",
  ui_story_5076_50760300_57_dialog_content = "Dia membantu orang tua memotong kayu bakar, memperbaiki atap kuil, melatih milisi, dan menemukan waktu untuk bermain dengan anak-anak...",
  ui_story_5076_50760300_58_dialog_content = "Dia menggunakan setiap ons kekuatannya untuk berbuat baik, dan itulah sebabnya semua orang di kota ini mencintainya.",
  ui_story_5076_50760300_59_dialog_content = "Bukankah itu yang seharusnya dilakukan oleh seorang pahlawan?",
  ui_story_5076_50760300_60_dialog_content = "Tapi... Ancaman dari Eclipsites masih sangat nyata di dunia ini.",
  ui_story_5076_50760300_61_dialog_content = "Perang ini telah merenggut rumah dari begitu banyak orang, bahkan keluarga mereka. Adras dan aku tidak terkecuali...",
  ui_story_5076_50760300_62_dialog_content = "Aku khawatir jika Adras tidak memanfaatkan bakatnya, dia akan menyesal suatu hari nanti.",
  ui_story_5076_50760300_63_dialog_content = "Kamu harus memberitahunya jika ini benar-benar membuatmu khawatir.",
  ui_story_5076_50760300_64_dialog_content = "Kamu tidak akan mengetahui pikiran satu sama lain tentang masalah ini jika kamu terus memendam perasaanmu.",
  ui_story_5076_50760300_65_dialog_content = "Orang luar seperti kita hanya akan mengenalnya sebagai komandan yang tak terkalahkan.",
  ui_story_5076_50760300_66_dialog_content = "Kamu, di sisi lain, adalah satu-satunya yang bisa melihat luka di bawah baju besinya dan khawatir tentang kematian ambisinya.",
  ui_story_5076_50760300_67_dialog_content = "Aku yakin dia akan mengerti jika kamu membagikan perasaanmu dengannya.",
  ui_story_5076_50760300_68_dialog_content = "Tapi, aku takut dia akan mengubur mimpinya hanya untuk memenuhi keinginanku.",
  ui_story_5076_50760300_69_dialog_content = "Apakah itu yang telah mengganggumu sepanjang waktu?",
  ui_story_5076_50760300_70_dialog_content = "Ini salahku yang membuatmu terganggu seperti ini.",
  ui_story_5076_50760300_71_dialog_content = "Adras?!",
  ui_story_5076_50760300_72_dialog_content = "T-Tidak, aku yang seharusnya minta maaf karena telah membuatmu khawatir!",
  ui_story_5076_50760300_73_dialog_content = "Oh, Adras. Apakah ini pertama kalinya kamu gagal membuat seseorang merasa aman?",
  ui_story_5076_50760300_74_dialog_content = "Aku kehilangan rumahku kepada Eclipsite sudah lama sekali. Sejak aku masih anak kecil, aku tidak merasakan apa-apa selain kebencian kepada mereka, dan oleh karena itu aku mendaftar di militer secepatnya.",
  ui_story_5076_50760300_75_dialog_content = "Mungkin karena itu, aku tidak pernah bisa memahami apa artinya hidup dalam damai. Meski begitu, hal itu memberiku tekad untuk melindungi semua yang aku sayangi.",
  ui_story_5076_50760300_76_dialog_content = "Setiap kali saya tidur di tenda saya, mimpi-mimpi saya dipenuhi dengan bau darah.",
  ui_story_5076_50760300_77_dialog_content = "Kebencian, kemarahan, dan persaudaraan membuatku terus menyerang musuh.",
  ui_story_5076_50760300_78_dialog_content = "Tidak ada akhir yang terlihat, tetapi saya bersedia untuk terus berjuang demi mereka yang berdiri di belakang saya.",
  ui_story_5076_50760300_79_dialog_content = "Aku tidak hidup dan berjuang untuk mereka karena aku harus, tetapi karena aku ingin. Selama masih ada seseorang di belakangku, aku menolak untuk jatuh.",
  ui_story_5076_50760300_80_dialog_content = "Adras...",
  ui_story_5076_50760300_81_dialog_content = "Tapi hari itu, saat aku mengakhiri pemberontakan dan memasuki kota—",
  ui_story_5076_50760300_82_dialog_content = "Itulah saat kamu masuk ke dalam dunia saya. Kamu hanyalah orang lain di kerumunan, menjaga sekelompok anak yatim agar tetap aman.",
  ui_story_5076_50760300_83_dialog_content = "Tapi kemudian kamu tiba-tiba berlari mendekatiku, memarahiku saat kamu membersihkan dan membalut lukaku.",
  ui_story_5076_50760300_84_dialog_content = "Pada saat itu, ketika kamu menyuruhku untuk tetap diam dan berhenti memaksakan diri—",
  ui_story_5076_50760300_85_dialog_content = "Aku tahu bahwa aku akhirnya menemukan keselamatan dari kehidupan penuh kematian dan kehancuran.",
  ui_story_5076_50760300_86_dialog_content = "Apa kamu masih ingat mimpi yang kamu berikan padaku hari itu?",
  ui_story_5076_50760300_87_dialog_content = "Jika dunia kembali damai lagi, apa yang akan dilakukan oleh Adras yang hebat itu?",
  ui_story_5076_50760300_88_dialog_content = "Apa lagi yang bisa kulakukan?",
  ui_story_5076_50760300_89_dialog_content = "Yang saya tahu hanyalah perang—Tapi mungkin saya bisa menjadi penyanyi pengembara? Di masa lalu, orang-orang hampir selalu kembali bekerja setiap kali mereka mendengar saya bernyanyi.",
  ui_story_5076_50760300_90_dialog_content = "Pasti suaramu cukup unik ya!",
  ui_story_5076_50760300_91_dialog_content = "Aku belum pernah memikirkan tentang kehidupan setelah perang, jadi aku benar-benar tidak memiliki ide apa-apa.",
  ui_story_5076_50760300_92_dialog_content = "Sepertinya merencanakan bukanlah keahlianmu, tapi jangan khawatir. Aku akan membantumu memikirkan sesuatu.",
  ui_story_5076_50760300_93_dialog_content = "Dengan posturmu yang mengesankan, kamu mungkin akan sukses dalam penjualan atau negosiasi.",
  ui_story_5076_50760300_94_dialog_content = "Kamu juga sangat kuat, jadi membangun dan memperbaiki struktur layak dipertimbangkan.",
  ui_story_5076_50760300_95_dialog_content = "Saya yakin kamu bisa menjadi tukang roti kelas atas dengan keterampilan membuat roti kamu juga.",
  ui_story_5076_50760300_96_dialog_content = "Saya tidak yakin bisa menyebutkan semua sifat positif Anda sekaligus, tetapi satu hal yang pasti: masa depan Anda akan cerah.",
  ui_story_5076_50760300_97_dialog_content = "Masa depanku... tidak akan cerah kecuali kamu ada di dalamnya.",
  ui_story_5076_50760300_98_dialog_content = "Apa yang akan kamu lakukan jika damai benar-benar kembali, Marcela?",
  ui_story_5076_50760300_99_dialog_content = "Saya? Yah... Sejujurnya, saya tidak memiliki aspirasi yang tinggi untuk dibicarakan.",
  ui_story_5076_50760300_100_dialog_content = "Tapi di dunia yang damai, aku ingin membangun sebuah pondok kecil di pedesaan dan menjadi petani gandum... Dan mungkin juga mengadopsi beberapa anak.",
  ui_story_5076_50760300_101_dialog_content = "Dan jika kamu bersamaku, aku akan membawa kamu dan anak-anak untuk panen di ladang bersamaku di musim gugur.",
  ui_story_5076_50760300_102_dialog_content = "Aku akan senang menghabiskan hari-hari damai bersamamu, menatap ladang gandum emas dalam hangatnya sinar matahari—",
  ui_story_5076_50760300_103_dialog_content = "Maka itu juga mimpiku.",
  ui_story_5076_50760300_104_dialog_content = "Marcela, masa laluku jauh dari bahagia, jadi aku memiliki sedikit sekali kepercayaan pada dewa manapun. Meski begitu, aku bersumpah padamu—",
  ui_story_5076_50760300_105_dialog_content = "Bahwa aku, Adras, tidak akan pernah berhenti berjuang demi mimpi emas kita. Dan aku juga tidak akan pernah meninggalkan sisimu.",
  ui_story_5076_50760300_106_dialog_content = "Kami membuat janji itu bersama, tapi kamu telah menderita begitu banyak karena itu.",
  ui_story_5076_50760300_107_dialog_content = "Di masa lalu, saya tidak peduli apakah saya hidup atau mati di medan perang. Saya berjuang untuk orang-orang yang ingin saya lindungi dengan hampir tidak memperhatikan keselamatan saya sendiri.",
  ui_story_5076_50760300_108_dialog_content = "Tapi setelah aku jatuh cinta padamu, aku mulai mengingat wajahmu bahkan di tengah pertempuran. Setiap pertemuan dengan Eclipsite membuatku khawatir bahwa aku tidak akan bisa kembali padamu.",
  ui_story_5076_50760300_109_dialog_content = "Setelah aku memiliki seseorang yang aku pedulikan, tampaknya aku kehilangan kemampuan untuk bertarung seperti setan. Pada satu titik, aku bertanya-tanya apakah itu membuatku lemah—",
  ui_story_5076_50760300_110_dialog_content = "Tapi kemudian saya pulang kepadamu dan anak-anak. Mereka menggangguku dengan pertanyaan dan memohon untuk bermain bersama mereka, semua tanpa sedikit pun rasa sakit atau kebencian di mata mereka.",
  ui_story_5076_50760300_111_dialog_content = "Apa yang selama ini aku lindungi... Itulah saat pertama kali menjadi jelas bagiku.",
  ui_story_5076_50760300_112_dialog_content = "Adras...",
  ui_story_5076_50760300_113_dialog_content = "Aku tidak menjadi lebih lemah karena kamu, Marcela. Aku menjadi lebih kuat.",
  ui_story_5076_50760300_114_dialog_content = "Akhirnya aku takut akan kematian, dan rasa takut itu membuatku ingin terus hidup agar bisa tetap berada di sisimu.",
  ui_story_5076_50760300_115_dialog_content = "Setelah hidup panjang dan penuh penderitaan, akhirnya saya mengerti apa artinya hidup.",
  ui_story_5076_50760300_116_dialog_content = "Saya tidak membutuhkan patung atau kemuliaan abadi. Bahkan, saya akan sangat senang jika semua orang benar-benar melupakan saya!",
  ui_story_5076_50760300_117_dialog_content = "Jika hari itu tiba, maka dunia pasti akan damai.",
  ui_story_5076_50760300_118_dialog_content = "Yang aku inginkan hanyalah terus membuat kenangan bersamamu, tidak peduli seberapa biasa pun itu.",
  ui_story_5076_50760300_119_dialog_content = "Adras... Aku sangat minta maaf! Aku tidak tahu apa yang kupikirkan.",
  ui_story_5076_50760300_120_dialog_content = "Aku tidak pernah berhenti untuk mempertimbangkan perasaanmu.",
  ui_story_5076_50760300_121_dialog_content = "Kamu tidak perlu khawatir tentang itu, Marcela. Untuk impian dan kenangan yang akan datang, aku tidak akan pernah menyerah pada diriku sendiri.",
  ui_story_5076_50760300_122_dialog_content = "Jika suatu hari nanti dunia membutuhkan saya, maka saya akan melangkah ke medan perang sekali lagi.",
  ui_story_5076_50760300_123_dialog_content = "Karena aku tahu bahwa dunia yang seindah ini layak untuk dilindungi—",
  ui_story_5076_50760300_124_dialog_content = "Jadi, tolong jangan khawatir, Marcela.",
  ui_story_5076_50760300_125_dialog_content = "Dengan dewa-dewa dan Ludweiss sebagai saksi kami, lepaskanlah ketakutanmu dan menikahlah denganku!",
  ui_story_5076_50760300_126_dialog_content = "Aku… aku mau!",
  ui_story_5076_50760300_127_dialog_content = "<color=#e8d9bb>Keesokan harinya, kota tersebut mengadakan pernikahan besar-besaran untuk sang pahlawan, dan semua orang memberikan berkah tulus kepada pasangan tersebut.</color>",
  ui_story_5076_50760300_128_dialog_content = "Saat kita bekerja menuju impian kita, mari terus membuat kenangan indah bersama.",
  ui_story_5076_50760300_129_dialog_content = "Saya berjanji untuk menghargai setiap momen indah dalam hidup kita—",
  ui_story_5076_50760300_130_dialog_content = "Aku mencintaimu, Marcela.",
  ui_story_5076_50760300_131_dialog_content = "Seperti halnya saya, sayangku Adras—",
  ui_story_5076_50760300_132_dialog_content = "Aku mencintaimu.",
  ui_story_5076_50760400_1_dialog_content = "... Itulah kurang lebih situasi di garis depan; pasukan ekspedisi menghadapi masa-masa sulit dan akan kembali ke ibu kota dalam waktu dekat.",
  ui_story_5076_50760400_2_dialog_content = "Saat Jenderal Achilles kembali, aku akan segera mengajukan untuk kembali bertugas.",
  ui_story_5076_50760400_3_dialog_content = "Aku akan bertarung di sisi semua orang dalam pertempuran berikutnya.",
  ui_story_5076_50760400_4_dialog_content = "Tapi, Komandan, sesuai perintah Jenderal, liburan Anda belum berakhir.",
  ui_story_5076_50760400_5_dialog_content = "Dan kau belum memiliki pewaris, dan Jenderal Achilles tidak akan menyetujui kau pergi ke garis depan.",
  ui_story_5076_50760400_6_dialog_content = "Kesehatan Marcela tidak memungkinkan kami untuk memiliki anak sendiri... Plus, anak-anak di panti asuhan juga merupakan keluarga bagi kami—",
  ui_story_5076_50760400_7_dialog_content = "Oh? Apakah kita memiliki pengunjung?",
  ui_story_5076_50760400_8_dialog_content = "Augustine! Kabar baik apa yang kamu bawa untuk kita hari ini?",
  ui_story_5076_50760400_9_dialog_content = "Sudah lama, nyonya, dan Anda menjadi semakin cantik.",
  ui_story_5076_50760400_10_dialog_content = "Saya baru saja membawa beberapa berita dari ibu kota. Sudah lama kami tidak melihat Commander, dan kami semua merindukannya.",
  ui_story_5076_50760400_11_dialog_content = "Saya yakin Adras juga merindukan kalian semua. Apakah kalian membutuhkannya untuk kembali lebih cepat dari yang diharapkan?",
  ui_story_5076_50760400_12_dialog_content = "Semua orang pasti akan sangat senang—tetapi, Nyonya, kami tidak berani mencuri Komandan dari Anda begitu saja.",
  ui_story_5076_50760400_13_dialog_content = "Sudah larut, Komandan Adras. Saya juga harus kembali ke ibukota sekarang.",
  ui_story_5076_50760400_14_dialog_content = "Jaga dirimu. Aku akan segera datang.",
  ui_story_5076_50760400_15_dialog_content = "Jaga diri baik-baik juga, kalian berdua.",
  ui_story_5076_50760400_16_dialog_content = "Adras, apakah ini pasukan ekspedisi...",
  ui_story_5076_50760400_17_dialog_content = "Mereka baik-baik saja, Marcela. Jangan dengarkan rumor-rumor itu.",
  ui_story_5076_50760400_18_dialog_content = "Kamu ingin kembali, bukan?",
  ui_story_5076_50760400_19_dialog_content = "... Coba ini. Saya telah mencoba teknik penyeduhan baru.",
  ui_story_5076_50760400_20_dialog_content = "Dan dari mana tepatnya kau belajar—Mmm! Ini sangat manis!",
  ui_story_5076_50760400_21_dialog_content = "Dan sama sekali tidak gosong! Saya suka!",
  ui_story_5076_50760400_22_dialog_content = "Aku mempelajarinya dari para pendeta.",
  ui_story_5076_50760400_23_dialog_content = "Jadi kamu telah membantu memperbaiki kuil untuk mencuri teknik pembuatan anggur mereka?",
  ui_story_5076_50760400_24_dialog_content = "Itu... sama sekali tidak terdengar seperti dirimu, wahai pahlawan perkasa.",
  ui_story_5076_50760400_25_dialog_content = "Mereka dengan senang hati berbagi pengetahuan mereka denganku untuk informasimu. Mereka juga bilang ini bagus untuk tubuh, jadi aku membuat dua barel hanya untukmu.",
  ui_story_5076_50760400_26_dialog_content = "Bahan-bahan yang saya gunakan juga merupakan hadiah dari orang lain, sebagai tanda penghargaan atas segala yang telah Anda lakukan untuk mereka.",
  ui_story_5076_50760400_27_dialog_content = "Kamu telah menerima hadiah untukku ketika saya tidak ada di sekitar? Satu hal bagi mereka untuk berterima kasih kepadamu karena telah membantu di sekitar kota, tapi apa yang telah saya lakukan?",
  ui_story_5076_50760400_28_dialog_content = "Kamu seharusnya hanya menerima hadiah mereka. Mengembalikannya hanya akan membuat semua orang merasa malu.",
  ui_story_5076_50760400_29_dialog_content = "Nah, berkat karisma Anda, rumah kita penuh sesak dengan hadiah.",
  ui_story_5076_50760400_30_dialog_content = "Kamu pikir aku punya karisma?",
  ui_story_5076_50760400_31_dialog_content = "Benar sekali!",
  ui_story_5076_50760400_32_dialog_content = "Tidak, saya pikir orang-orang itu hanya sangat baik hati. Anak-anak juga sangat membantu sekarang. Baru saja sore ini, mereka pergi bersama saya untuk panen di ladang dekat panti asuhan.",
  ui_story_5076_50760400_33_dialog_content = "... Jadi aku tahu kamu akan tetap terjaga meski aku tidak ada untuk beberapa saat.",
  ui_story_5076_50760400_34_dialog_content = "Aku selalu baik dengan orang lain, Adras. Atau kau lupa?",
  ui_story_5076_50760400_35_dialog_content = "Saya tahu bahwa ada banyak orang lain yang membutuhkan Anda selain kami. Tetangga kami juga tahu itu, itulah sebabnya mereka sangat baik akhir-akhir ini.",
  ui_story_5076_50760400_36_dialog_content = "Mereka tidak ingin memonopoli kamu di sini, karena mereka tahu kamu memiliki hal-hal yang lebih penting untuk dikerjakan.",
  ui_story_5076_50760400_37_dialog_content = "Api perang telah merenggut rumah dari begitu banyak orang. Paling tidak, saya ingin melindungi sudut damai dari dunia kita ini.",
  ui_story_5076_50760400_38_dialog_content = "Aku berjanji akan kembali secepat mungkin, Marcela.",
  ui_story_5076_50760400_39_dialog_content = "Jangan khawatir. Kami akan menunggu di sini untukmu.",
  ui_story_5076_50760400_40_dialog_content = "Kami akan menjaga rumah kita selama kamu tidak ada... Sehingga pahlawan kita selalu memiliki tempat untuk kembali.",
  ui_story_5076_50760400_41_dialog_content = "Aku akan kembali dengan selamat kepadamu, sayangku Marcela—",
  ui_story_5076_50760400_42_dialog_content = "Demi kamu dan orang-orang baik ini, aku akan membasmi kejahatan yang mengancam dunia kita.",
  ui_story_5076_50760400_43_dialog_content = "Dan ketika aku kembali, kita akan bertemu lagi di lautan gandum emas.",
  ui_story_5076_50760400_44_dialog_content = "Maka itu janji.",
  ui_story_5076_50760400_45_dialog_content = "Adras?",
  ui_story_5076_50760400_46_dialog_content = "Ludweiss? Apa yang kamu lakukan di sini? Apakah kamu datang ke sini bersama pasukan ekspedisi?",
  ui_story_5076_50760400_47_dialog_content = "Ini rumit, dan saya tidak yakin harus mulai dari mana... Meski begitu, saya senang bisa bertemu dengan Anda lagi.",
  ui_story_5076_50760400_48_dialog_content = "Aku yakin Achilles juga akan senang melihatmu. Ikutlah denganku.",
  ui_story_5076_50760400_49_dialog_content = "Apakah itu... Komandan Adras?",
  ui_story_5076_50760400_50_dialog_content = "Commander Adras sudah kembali?",
  ui_story_5076_50760400_51_dialog_content = "Komandan Adras!",
  ui_story_5076_50760400_52_dialog_content = "Komandan Adras, apakah Anda akan kembali bertugas?",
  ui_story_5076_50760400_53_dialog_content = "Bagaimana... Bagaimana semua orang bisa terluka begitu parah?",
  ui_story_5076_50760400_54_dialog_content = "Kita...",
  ui_story_5076_50760400_55_dialog_content = "Dominic! Bruno! Di mana kalian?",
  ui_story_5076_50760400_56_dialog_content = "Komandan, sangat senang bisa bertemu denganmu.",
  ui_story_5076_50760400_57_dialog_content = "Anthony... Ada apa dengan matamu?",
  ui_story_5076_50760400_58_dialog_content = "Sepertinya saya memang sudah semakin tua. Ada kegagalan sejenak, dan Eclipsite yang licik berhasil mengambil salah satu dari mereka dariku.",
  ui_story_5076_50760400_59_dialog_content = "Maaf, Komandan, saya telah mengecewakan Dominick. Semua ini karena saya kehilangan perisai saya, dan untuk menyelamatkan saya, dia...",
  ui_story_5076_50760400_60_dialog_content = "Apa sebenarnya yang terjadi selama ekspedisi itu?",
  ui_story_5076_50760400_61_dialog_content = "Adras? Apakah itu kamu?",
  ui_story_5076_50760400_62_dialog_content = "Rupanya memang kau... Semua orang pasti lega melihatmu, Adras.",
  ui_story_5076_50760400_63_dialog_content = "Jenderal? Anda terlihat benar-benar lelah. Apa yang terjadi pada...",
  ui_story_5076_50760400_64_dialog_content = "Kami menemukan jurang yang gelap di utara jauh.",
  ui_story_5076_50760400_65_dialog_content = "Eclipsite yang tak terhitung jumlahnya dan sangat kuat terus muncul... Dalam hal kekuatan dan jumlah, mereka seperti tidak ada yang pernah kita lihat sebelumnya.",
  ui_story_5076_50760400_66_dialog_content = "Aku gagal memimpin pasukan kita dengan baik, dan akibatnya kami mengalami kerugian yang sangat besar.",
  ui_story_5076_50760400_67_dialog_content = "Selama kami mundur, Ludweiss juga terluka oleh kekuatan Eclipsite.",
  ui_story_5076_50760400_68_dialog_content = "Jangan tampak begitu khawatir, Adras. Syukurlah, Silent Saintess ada di sana untuk menyelamatkanku dan membuatku sehat seperti sedia kala!",
  ui_story_5076_50760400_69_dialog_content = "Aku belum pernah melihat Eclipsite seperti itu. Mereka bukan sesuatu yang bisa kita hadapi sekarang.",
  ui_story_5076_50760400_70_dialog_content = "Dan beberapa dari mereka... Jauh melampaui pemahaman kita. Saya bahkan tidak bisa membayangkan cara untuk mengalahkan monster-monster itu.",
  ui_story_5076_50760400_71_dialog_content = "Kita tidak bisa membasmi mereka di utara, dan sekarang mereka bergerak menuju ibu kota kerajaan... Kutuk mereka semua!",
  ui_story_5076_50760400_72_dialog_content = "Tenangkan pikiran Anda untuk saat ini, Jenderal Achilles. Saya siap kembali ke garis depan dan berjuang di sisi semua orang.",
  ui_story_5076_50760400_73_dialog_content = "Kita hanya terkejut waktu itu. Dengan persiapan yang tepat, saya yakin kita bisa menghentikan kejahatan mereka.",
  ui_story_5076_50760400_74_dialog_content = "Adras benar. Kita tidak bisa sampai kalah dari hal-hal itu.",
  ui_story_5076_50760400_75_dialog_content = "Untuk menghalau horde Eclipsite yang menyerang, saya percaya sebaiknya membiarkan saya kembali ke pasukan dan mulai persiapan bertempur bersama-sama.",
  ui_story_5076_50760400_76_dialog_content = "Dengan begitu, kita bisa menghentikan langkah mereka sebelum mereka mencapai rumah kita.",
  ui_story_5076_50760400_77_dialog_content = "Adras... Kamu benar-benar telah berubah.",
  ui_story_5076_50760400_78_dialog_content = "Bagaimana keadaan akhir-akhir ini?",
  ui_story_5076_50760400_79_dialog_content = "Saya baik-baik saja. Tetangga kami telah menjaga kami dengan baik di luar sana.",
  ui_story_5076_50760400_80_dialog_content = "Akhirnya saya mengerti apa yang kamu maksud ketika kamu memberi tahu saya tentang \"keindahan kedamaian.\"",
  ui_story_5076_50760400_81_dialog_content = "Takutkah kamu mati jika saya kirimkan kamu ke garis depan lagi?",
  ui_story_5076_50760400_82_dialog_content = "Kamu bukan lagi orang yang sama. Bisakah kamu benar-benar meninggalkan rasa ingin bertahan hidupmu seperti dulu?",
  ui_story_5076_50760400_83_dialog_content = "Aku tidak bisa, dan itu karena... Sekarang aku paham arti dari rasa takut.",
  ui_story_5076_50760400_84_dialog_content = "Tapi meski begitu, saya harus melindungi ladang gandum emas itu dan orang-orang yang menyebut tempat itu sebagai rumah mereka.",
  ui_story_5076_50760400_85_dialog_content = "Itulah mengapa aku harus bertahan hidup.",
  ui_story_5076_50760400_86_dialog_content = "Aku akan bertahan bersama rekan-rekan seperjuanganku, dan kita akan kembali ke orang-orang yang kita cintai bersama-sama.",
  ui_story_5076_50760400_87_dialog_content = "Oh, begitu... Syukurlah.",
  ui_story_5076_50760400_88_dialog_content = "Sekarang kamu jauh lebih kuat dibandingkan di masa lalu.",
  ui_story_5076_50760400_89_dialog_content = "Saya yakin saya bisa mempercayai perisai Anda dengan hidup saya, sama seperti sebelumnya.",
  ui_story_5076_50760400_90_dialog_content = "Demi kejayaan kerajaan kita, kita akan berperang sekali lagi.",
  ui_story_5076_50760400_91_dialog_content = "Sepertinya kamu merasa jauh lebih baik sekarang. Saya tidak menyadari bahwa Adras adalah pembicara yang begitu kuat!",
  ui_story_5076_50760400_92_dialog_content = "Tebak Adras memang benar-benar pahlawan bagi semua orang.",
  ui_story_5076_50760400_93_dialog_content = "Setuju. Jika semua orang di tentara kita seperti Adras... Bahkan Eclipsite terkuat sekalipun tidak akan berpeluang melawan kita.",
  ui_story_5076_50760400_94_dialog_content = "Aku tidak keberatan menjadi bagian dari tentara itu!",
  ui_story_5076_50760400_95_dialog_content = "Aku harus segera memulai persiapan. Kalau kamu memaafkan aku.",
  ui_story_5076_50760400_96_dialog_content = "Adras.",
  ui_story_5076_50760400_97_dialog_content = "Ya?",
  ui_story_5076_50760400_98_dialog_content = "Hargai segala yang Anda miliki dalam hidup.",
  ui_story_5076_50760400_99_dialog_content = "Saya tidak berniat melakukan sebaliknya, Pak.",
  ui_story_5076_50760400_100_dialog_content = "Lagipula, aku telah berjanji padanya.",
  ui_story_5076_50760501_1_dialog_content = "Ini seharusnya yang terakhir. Saya tidak pikir masih ada yang perlu dipindahkan dari panti asuhan.",
  ui_story_5076_50760501_2_dialog_content = "Apakah ini... pedang latihan kayu Adras'?",
  ui_story_5076_50760501_3_dialog_content = "Anak-anak terus meminta untuk belajar ilmu pedang agar mereka dapat melindungi kota. Membawa ini kembali mungkin bisa membuat mereka tenang.",
  ui_story_5076_50760501_4_dialog_content = "Ah, jika saja aku bisa membawa mural hari pernikahan kita ini. Itu adalah momen yang sangat berharga...",
  ui_story_5076_50760501_5_dialog_content = "Saya tidak pernah berpikir bahwa Eclipsites akan mencapai tempat ini.",
  ui_story_5076_50760501_6_dialog_content = "Berapa lama lagi panti asuhan ini akan tetap tutup? Saya berharap bisa melihat anak-anak yang bahagia itu berlari di ladang gandum sekali lagi.",
  ui_story_5076_50760501_7_dialog_content = "Semuanya akan baik-baik saja. Sementara Adras dan yang lainnya berjuang di garis depan, kita akan berjuang untuk menjaga kota ini tetap aman.",
  ui_story_5076_50760501_8_dialog_content = "Maaf, saya masih belum pulih sepenuhnya... Jika tidak, saya juga akan berada di luar sana membantu semua orang.",
  ui_story_5076_50760501_9_dialog_content = "Kamu tidak perlu minta maaf, Ludweiss. Kamu sudah berbuat sangat banyak untuk kami.",
  ui_story_5076_50760501_10_dialog_content = "Peringatan tepat waktu Anda telah menjaga keselamatan kami beberapa hari terakhir ini.",
  ui_story_5076_50760501_11_dialog_content = "Apakah pertahanan kota sedang diperbaiki sekarang?",
  ui_story_5076_50760501_12_dialog_content = "Ya. Kami juga sedang membangun tempat perlindungan di bawah kuil dan terowongan pelarian.",
  ui_story_5076_50760501_13_dialog_content = "Semua orang bekerja keras bersama, dan saling mendorong sepanjang jalan.",
  ui_story_5076_50760501_14_dialog_content = "Orang-orang yang Adras latih juga telah membentuk milisi kecil. Saya bisa melihat bahwa mereka semua penuh harapan.",
  ui_story_5076_50760501_15_dialog_content = "Ini semua berkatmu, Marcela... Sebelum bala bantuan tiba, kamu adalah orang yang memberi mereka harapan dan mendorong mereka untuk bertindak.",
  ui_story_5076_50760501_16_dialog_content = "Saya hanya melakukan bagian kecil saya. Mereka lah yang melakukan semua pekerjaan—",
  ui_story_5076_50760501_17_dialog_content = "Ayo, mari kita bawa pulang benda-benda ini untuk anak-anak.",
  ui_story_5076_50760501_18_dialog_content = "Apa Achilles yang menyuruhmu mengantarkan surat ini? Bagaimana situasi di garis depan?",
  ui_story_5076_50760501_19_dialog_content = "Komandan Adras, bersama legiunnya, sedang memukul mundur serangan besar-besaran di ibu kota dan telah meraih serangkaian kemenangan.",
  ui_story_5076_50760501_20_dialog_content = "Sang Majestatis memerintahkannya untuk membantu Jenderal Achilles dalam memimpin pasukan untuk mengejar dan membasmi para Eclipsite.",
  ui_story_5076_50760501_21_dialog_content = "Komandan yang ditugaskan di sini untuk mempertahankan kota ini adalah pengikut dari Imam Besar Lucius. Itu semua pesan yang seharusnya saya sampaikan.",
  ui_story_5076_50760501_22_dialog_content = "Tapi selain itu, Nyonya Ludweiss, aku punya beberapa informasi intel...",
  ui_story_5076_50760501_23_dialog_content = "Sepertinya High Priest Lucius berusaha untuk mendapatkan jasa, dengan niat untuk mengkonsentrasikan pasukan untuk menyerang sisi Eclipsite. Dia sudah pergi dan menempatkan kembali pasukan pertahanan di sepanjang jalan!",
  ui_story_5076_50760501_24_dialog_content = "Dengan kata lain, kemungkinan kecil kota ini akan menerima dukungan militer. Begitu kah?",
  ui_story_5076_50760501_25_dialog_content = "... Aku akan tetap tinggal, meskipun itu berarti mengorbankan hidupku untuk melindungi warga sipil di kota.",
  ui_story_5076_50760501_26_dialog_content = "Jangan katakan itu!",
  ui_story_5076_50760501_27_dialog_content = "Hidup adalah hal paling berharga di dunia ini! Jangan bicara tentang itu seolah-olah itu kurang dari itu!",
  ui_story_5076_50760501_28_dialog_content = "Y-Ya! Saya minta maaf untuk itu!",
  ui_story_5076_50760501_29_dialog_content = "Kamu memiliki pengalaman militer. Aku akan meninggalkan komando milisi di tanganmu.",
  ui_story_5076_50760501_30_dialog_content = "Saya harus...",
  ui_story_5076_50760501_31_dialog_content = "Harus melakukan apa, Ludweiss?",
  ui_story_5076_50760501_32_dialog_content = "Marcela...?",
  ui_story_5076_50760501_33_dialog_content = "Aku akan membantu mempertahankan dinding kota.",
  ui_story_5076_50760501_34_dialog_content = "Jadi, kamu dengar semuanya?",
  ui_story_5076_50760501_35_dialog_content = "Ya, tapi aku tidak akan memberitahu siapa-siapa tentang ini untuk saat ini. Kalian berdua juga harus melakukan hal yang sama.",
  ui_story_5076_50760501_36_dialog_content = "Aku akan mempertahankan tempat ini bersama semua orang. Ini adalah rumah kita, serta rumah dari pahlawan besar Adras.",
  ui_story_5076_50760501_37_dialog_content = "Aku harus pergi sebentar, Marcela.",
  ui_story_5076_50760501_38_dialog_content = "Lalu tolong berhati-hati... Dan jangan terlalu memaksakan diri.",
  ui_story_5076_50760501_39_dialog_content = "Ke mana tepatnya kamu pergi?",
  ui_story_5076_50760501_40_dialog_content = "Gerombolan Eclipsite akan segera tiba. Aku harus melakukan sesuatu yang hanya kami Caelestites yang bisa melakukannya...",
  ui_story_5076_50760501_41_dialog_content = "Saya akan menggunakan kekuatan saya untuk menyelinap melalui barisan mereka dan menyampaikan pesan kepada Adras.",
  ui_story_5076_50760501_42_dialog_content = "Tapi itu jauh terlalu berbahaya!",
  ui_story_5076_50760501_43_dialog_content = "Adras perlu tahu. Demi kebaikanmu, dan demi seluruh kota ini.",
  ui_story_5076_50760501_44_dialog_content = "Kami tidak akan pernah bisa membalas semua yang telah Anda lakukan untuk kami, Ludweiss...",
  ui_story_5076_50760501_45_dialog_content = "Tolong hati-hati.",
  ui_story_5076_50760501_46_dialog_content = "Aku hanya seorang pengembara yang tersesat. Hanya berkat semua orang di sini, aku ingat kembali keindahan Eraveil, rumahku.",
  ui_story_5076_50760501_47_dialog_content = "Aku akan memastikan untuk membawa Adras ke sini. Sampai saat itu, tetap waspada dan jangan menyerah pada harapan.",
  ui_story_5076_50760501_48_dialog_content = "(Aku pasti bisa melakukannya—)",
  ui_story_5076_50760501_49_dialog_content = "(Tidak peduli seberapa jauh atau seberapa sulit jalannya mungkin—)",
  ui_story_5076_50760501_50_dialog_content = "<color=#e8d9bb>Eclipsite dari utara jauh telah menginfestasi seluruh benua, bahkan membakar hutan belantara.</color>",
  ui_story_5076_50760501_51_dialog_content = "<color=#e8d9bb>Api menghancurkan rumah-rumah penduduk sipil, dan ladang gandum yang dulunya tenang hampir seluruhnya terbakar.</color>",
  ui_story_5076_50760501_52_dialog_content = "Adras!",
  ui_story_5076_50760501_53_dialog_content = "Hah? Ada apa dengan semua teriakan itu?",
  ui_story_5076_50760501_54_dialog_content = "Adras! Aku... Akhirnya aku menemukanmu...",
  ui_story_5076_50760501_55_dialog_content = "Ludweiss? Apa yang kamu lakukan di sini? Luka bakar itu... Kamu benar-benar terluka!",
  ui_story_5076_50760501_56_dialog_content = "Panggil medis, Anthony!",
  ui_story_5076_50760501_57_dialog_content = "Lupakan itu! K-Kamu harus ikut denganku!",
  ui_story_5076_50760501_58_dialog_content = "Lucius memindahkan semua pasukannya keluar dari kota! Dia meninggalkan Marcela dan yang lainnya untuk membela diri sendiri!",
  ui_story_5076_50760501_59_dialog_content = "Apa katamu?",
  ui_story_5076_50760501_60_dialog_content = "Marcela, aku...",
  ui_story_5076_50760501_61_dialog_content = "Sial! Kami baru saja akan melancarkan serangan balasan yang menentukan!",
  ui_story_5076_50760501_62_dialog_content = "Sebagai komandan yang bertindak, saya tidak bisa begitu saja meninggalkan prajurit saya.",
  ui_story_5076_50760501_63_dialog_content = "Ayo, Adras.",
  ui_story_5076_50760501_64_dialog_content = "Tapi Jenderal—",
  ui_story_5076_50760501_65_dialog_content = "Musuh sudah seolah-olah mati. Kamu dan Legiun Northwind sudah melakukan cukup banyak untuk kerajaan.",
  ui_story_5076_50760501_66_dialog_content = "Pasukan utama kami seharusnya yang melindungi rumahmu, tetapi sayangnya... Kamu dan pasukanmu harus melakukan perjalanan ini sendirian.",
  ui_story_5076_50760501_67_dialog_content = "Itu perintah.",
  ui_story_5076_50760501_68_dialog_content = "Jenderal Achilles... mengerti.",
  ui_story_5076_50760501_69_dialog_content = "Apakah kamu yakin ingin ikut denganku, Ludweiss? Pasukan kita memiliki sejumlah petugas medis yang mampu.",
  ui_story_5076_50760501_70_dialog_content = "Jika Anda tidak mampu melakukan perjalanan, Anda selalu bisa tinggal di sini dan beristirahat.",
  ui_story_5076_50760501_71_dialog_content = "Tidak, aku harus kembali bersamamu dan memastikan Marcela baik-baik saja.",
  ui_story_5076_50760501_72_dialog_content = "Aku berjanji akan membawamu kembali padanya.",
  ui_story_5076_50760501_73_dialog_content = "Kalau begitu, mari kita pergi.",
  ui_story_5076_50760501_74_dialog_content = "Prajurit dari Legiun Northwind! Jawab panggilanku—",
  ui_story_5076_50760501_75_dialog_content = "<color=#e8d9bb>Suaranya yang menggema menembus tenda-tenda, dan para prajurit merespon secara serentak.</color>",
  ui_story_5076_50760501_76_dialog_content = "<color=#e8d9bb>Prajurit, yang tanah airnya telah dilindungi oleh komandannya berkali-kali, akhirnya mendapatkan kesempatan untuk mempertahankan rumah komandannya.</color>",
  ui_story_5076_50760501_77_dialog_content = "Tidak ada habisnya mereka—keluar dari jalanku!!!",
  ui_story_5076_50760501_78_dialog_content = "Mengapa ada begitu banyak Eclipsite di bawah kota?",
  ui_story_5076_50760501_79_dialog_content = "Apakah mereka semua berkumpul di sini?",
  ui_story_5076_50760501_80_dialog_content = "Berapa banyak prajurit yang telah Lucius tarik dari pertempuran? Berapa banyak nyawa yang telah hilang karena dia?!",
  ui_story_5076_50760501_81_dialog_content = "Tetap tenang, Adras. Kita dekat dengan kota—",
  ui_story_5076_50760501_82_dialog_content = "Kamu telah meninggalkan pasukan di setiap kota yang kita lewati. Itulah sebabnya sekarang terasa seperti ada lebih banyak musuh untuk kita lawan.",
  ui_story_5076_50760501_83_dialog_content = "Kita tidak bergerak cukup cepat... Saya berjanji akan melindungi mereka semua! Saya telah memberi mereka janji saya!",
  ui_story_5076_50760501_84_dialog_content = "Aku melihatnya! Komandan Adras, tembok kota masih utuh, dan sepertinya gerbang kota baru saja ditembus.",
  ui_story_5076_50760501_85_dialog_content = "Orang-orang berlindung di dalam kuil, Adras.",
  ui_story_5076_50760501_86_dialog_content = "Ada terowongan darurat di bawahnya. Jika mereka tidak dapat mempertahankan gerbang kuil, mereka dapat menggunakan terowongan itu untuk melarikan diri ke belakang kota.",
  ui_story_5076_50760501_87_dialog_content = "Dieter, Vivia, bawa tim ksatria dan menuju pinggiran kota. Cari para penyintas dan hapus semua Eclipsites yang berkeliaran di area tersebut.",
  ui_story_5076_50760501_88_dialog_content = "Quintas, bentuklah falanks dan serang musuh dari kedua sisi. Jangan biarkan satu pun Eclipsite lolos.",
  ui_story_5076_50760501_89_dialog_content = "Yang lainnya, ikutlah dengan saya. Kita akan menyerang dari belakang dan memaksa masuk ke kota!",
  ui_story_5076_50760501_90_dialog_content = "Tetap dekat, Ludweiss.",
  ui_story_5076_50760501_91_dialog_content = "<color=#FFB400>Menuju pertempuran—!!!</color>",
  ui_story_5076_50760501_92_dialog_content = "<color=#FFB400>Hapuslah setiap Eclipsite kotor ini sampai yang terakhir sekalipun!</color>",
  ui_story_5076_50760501_93_dialog_content = "Komandan, Kuil belum jatuh, dan anggota milisi masih bertahan di dalam aula utama!",
  ui_story_5076_50760501_94_dialog_content = "Sedikit lebih cepat—",
  ui_story_5076_50760501_95_dialog_content = "Tunggu aku, Adras!",
  ui_story_5076_50760501_96_dialog_content = "Aduh, apakah ini luka lamaku? Kenapa malah kambuh sekarang...",
  ui_story_5076_50760501_97_dialog_content = "Tidak, ada yang salah... Sesuatu di kepala saya...",
  ui_story_5076_50760501_98_dialog_content = "Adras...",
  ui_story_5076_50760502_1_dialog_content = "Itu Adras!",
  ui_story_5076_50760502_2_dialog_content = "Adras telah datang untuk menyelamatkan kita!",
  ui_story_5076_50760502_3_dialog_content = "Hai, Adras!",
  ui_story_5076_50760502_4_dialog_content = "Kalian semua sudah aman sekarang, jadi tolong tetap tenang. Kami telah berhasil mengamankan rute pelarian.",
  ui_story_5076_50760502_5_dialog_content = "Apakah semua orang baik-baik saja? Ada korban?",
  ui_story_5076_50760502_6_dialog_content = "Apakah ada area lain yang membutuhkan bantuan?",
  ui_story_5076_50760502_7_dialog_content = "Tidak, Komandan Adras, kita adalah penjaga belakang; yang lain sudah melarikan diri melalui lorong.",
  ui_story_5076_50760502_8_dialog_content = "Semua berkat Marcela; dia memotivasi kita untuk mempertahankan kota, dan itulah mengapa kita bisa bertahan selama ini.",
  ui_story_5076_50760502_9_dialog_content = "Jika kamu datang kemari lebih lambat, mungkin semua orang sudah...",
  ui_story_5076_50760502_10_dialog_content = "Marcela...? Di mana dia sekarang? Apakah dia sudah kabur?",
  ui_story_5076_50760502_11_dialog_content = "Hah? Kamu tidak bertemu dengan Marcela di tengah jalan menuju sini?",
  ui_story_5076_50760502_12_dialog_content = "Untuk membeli waktu bagi mundurnya semua orang, dia memimpin pasukan terdepan di dekat Kuil untuk mengalihkan perhatian Eclipsite...",
  ui_story_5076_50760502_13_dialog_content = "Tidak... Tidak...",
  ui_story_5076_50760502_14_dialog_content = "Jangan menakutiku seperti ini, sayangku—",
  ui_story_5076_50760502_15_dialog_content = "Tunggu, Adras! Biarkan saya mencoba merasakan lokasi dia!",
  ui_story_5076_50760502_16_dialog_content = "Tolong, Ludweiss...",
  ui_story_5076_50760502_17_dialog_content = "Tidak perlu kalian semua mengikutiku! Mundur dan lindungi warga sipil kota—",
  ui_story_5076_50760502_18_dialog_content = "Aku tidak bisa menyaring semua pikiran dan perasaan yang kacau. Yang bisa aku katakan adalah ada Eclipsite yang berkumpul di sebelah timur kuil.",
  ui_story_5076_50760502_19_dialog_content = "Minggir, monster busuk!",
  ui_story_5076_50760502_20_dialog_content = "Lebih cepat! Aku harus bergerak lebih cepat!!!",
  ui_story_5076_50760502_21_dialog_content = "Tempat ini—",
  ui_story_5076_50760502_22_dialog_content = "Orang-orang di tanah itu bersama milisi. Sungguh pemandangan yang mengerikan...",
  ui_story_5076_50760502_23_dialog_content = "Mereka juga berhasil membunuh banyak Eclipsite tepat di depan sana.",
  ui_story_5076_50760502_24_dialog_content = "Sayangnya, tempat ini sudah tidak bisa diselamatkan—",
  ui_story_5076_50760502_25_dialog_content = "Ah! Tidak... itu Augustine... Ini tidak mungkin.",
  ui_story_5076_50760502_26_dialog_content = "Prajurit yang berani dan terhormat... May roh kalian akhirnya menemukan kedamaian.",
  ui_story_5076_50760502_27_dialog_content = "... Eclipsite Busuk.",
  ui_story_5076_50760502_28_dialog_content = "Marcela! Bisakah kamu mendengarku?!",
  ui_story_5076_50760502_29_dialog_content = "Jangan khawatir, aku datang untukmu!",
  ui_story_5076_50760502_30_dialog_content = "(T-Tidak—)",
  ui_story_5076_50760502_31_dialog_content = "Siapa? Siapa itu?",
  ui_story_5076_50760502_32_dialog_content = "(Ada seseorang di kepala saya, berbicara padaku... Apakah ini karena luka yang pernah aku alami sebelumnya?)",
  ui_story_5076_50760502_33_dialog_content = "(Kamu harus bangun—)",
  ui_story_5076_50760502_34_dialog_content = "(Jangan menonton sampai akhir—)",
  ui_story_5076_50760502_35_dialog_content = "Apa?",
  ui_story_5076_50760502_36_dialog_content = "<size=40>Tidak... Tidakkk!!!</size>",
  ui_story_5076_50760502_37_dialog_content = "Adras???",
  ui_story_5076_50760502_38_dialog_content = "Argh, kepalaku... Rasanya seperti mau pecah.",
  ui_story_5076_50760502_39_dialog_content = "<size=40>Jangan menakutiku seperti ini, Marcela—</size>",
  ui_story_5076_50760502_40_dialog_content = "<color=#FFB400><size=45>Marcela!!!</size></color>",
  ui_story_5076_50760502_41_dialog_content = "Apa yang sedang terjadi...",
  ui_story_5076_50760502_42_dialog_content = "Adras, Marcela...",
  ui_story_5076_50760502_43_dialog_content = "Tunggu aku...",
  ui_story_5076_50760502_44_dialog_content = "!!!",
  ui_story_5076_50760502_45_dialog_content = "Terima kasih kepada para dewa—",
  ui_story_5076_50760502_46_dialog_content = "Karena tidak mencuri kekasihku dariku, Marcela manisku—",
  ui_story_5076_50760502_47_dialog_content = "Marcela! Ini aku, aku di sini! Aku kembali, seperti yang aku janjikan.",
  ui_story_5076_50760502_48_dialog_content = "Jangan khawatir, kita pulang sekarang...",
  ui_story_5076_50760502_49_dialog_content = "(Kenangan-kenangan adalah—)",
  ui_story_5076_50760502_50_dialog_content = "<color=#FFB400>(Sebuah kutukan.)</color>",
  ui_story_5076_50760502_51_dialog_content = "(Tapi untuk sekarang... Tolong jangan menghalangi reuni mereka.)",
  ui_story_5076_50760502_52_dialog_content = "Suara di kepala saya... Siapa kamu...?",
  ui_story_5076_50760502_53_dialog_content = "Akhirnya, kamu kembali, Adras.",
  ui_story_5076_50760502_54_dialog_content = "Aku menunggu begitu lama... untukmu.",
  ui_story_5076_50760502_55_dialog_content = "Hematlah tenagamu, sayangku. Aku akan memanggil penyembuh untuk merawat lukamu sebelum kita pulang.",
  ui_story_5076_50760502_56_dialog_content = "Dua barel anggur yang kamu tinggalkan untukku... Saya telah membagikannya kepada semua orang.",
  ui_story_5076_50760502_57_dialog_content = "Semua orang mengatakan itu sangat lezat, dan manisnya membuat mereka merasa sangat bahagia.",
  ui_story_5076_50760502_58_dialog_content = "Itulah mengapa kami tidak takut, bahkan tidak sejenak pun—",
  ui_story_5076_50760502_59_dialog_content = "Adras... setiap kali aku memikirkanmu, hatiku penuh dengan harapan.",
  ui_story_5076_50760502_60_dialog_content = "Terima kasih sudah menepati janjimu.",
  ui_story_5076_50760600_1_dialog_content = "<color=#e8d9bb>Kota yang pernah dilanda monster, kini menyambut hari-hari pembangunan kembali. Iman yang datang dari para pahlawan mengisi penduduknya dengan harapan.</color>",
  ui_story_5076_50760600_2_dialog_content = "<color=#e8d9bb>Namun, di tengah suasana yang berkembang ini, banyak yang masih merasa tidak memiliki rumah.</color>",
  ui_story_5076_50760600_3_dialog_content = "Berhati-hatilah saat memindahkan puing-puing, dan perhatikan pejalan kaki! Jika Anda membutuhkan bantuan, mintalah kepada prajurit Legion!",
  ui_story_5076_50760600_4_dialog_content = "Siap, Jenderal.",
  ui_story_5076_50760600_5_dialog_content = "Ayo.",
  ui_story_5076_50760600_6_dialog_content = "... Tentu.",
  ui_story_5076_50760600_7_dialog_content = "Adras, apa...?",
  ui_story_5076_50760600_8_dialog_content = "Ini tidak apa-apa. Kami hanya pergi jalan-jalan.",
  ui_story_5076_50760600_9_dialog_content = "\"Kami\"? Oh... Oh! Tolong jangan terlalu khawatir; kami akan segera menyelesaikan rekonstruksi.",
  ui_story_5076_50760600_10_dialog_content = "Marcela? Aku pikir kamu berteman dengan pria itu... Kenapa kamu tidak sekadar menyapa?",
  ui_story_5076_50760600_11_dialog_content = "... Tak apa-apa. Mari kita terus melanjutkan.",
  ui_story_5076_50760600_12_dialog_content = "Kamu mau pergi ke mana? Mungkin ke kuil?",
  ui_story_5076_50760600_13_dialog_content = "Tidak! Bukan ke kuil! Aku... masih takut dengan tempat itu.",
  ui_story_5076_50760600_14_dialog_content = "Tidak apa-apa, kita bisa pergi ke tempat lain. Bagaimana kalau kita mengunjungi anak-anak? Mereka sudah baik-baik saja, tapi saya yakin Anda masih khawatir tentang mereka.",
  ui_story_5076_50760600_15_dialog_content = "Aku menemukannya, Achilles. Dia di sini.",
  ui_story_5076_50760600_16_dialog_content = "...",
  ui_story_5076_50760600_17_dialog_content = "Adras... Apa kamu baik-baik saja?",
  ui_story_5076_50760600_18_dialog_content = "... Ludweiss?",
  ui_story_5076_50760600_19_dialog_content = "Pertempuran sudah berakhir, Adras. Kenapa kamu masih di sini?",
  ui_story_5076_50760600_20_dialog_content = "Tidak ada seorang pun yang tersisa untuk mempertahankan tempat ini. Aku harus melindungi orang-orang di sini.",
  ui_story_5076_50760600_21_dialog_content = "Ah! Jangan takut, Marcela! Itu hanya Jenderal Achilles.",
  ui_story_5076_50760600_22_dialog_content = "Maaf, tapi pertempuran benar-benar telah mempengaruhi Marcela. Mohon maafkan dia jika dia terlalu takut untuk menyapa.",
  ui_story_5076_50760600_23_dialog_content = "Adras, Marcela adalah—",
  ui_story_5076_50760600_24_dialog_content = "Achilles!",
  ui_story_5076_50760600_25_dialog_content = "Apa ini? Kalian berdua bertingkah sangat aneh, terutama kamu Ludweiss. Kenapa kamu tidak sering mengunjungi Marcela?",
  ui_story_5076_50760600_26_dialog_content = "... Lihatlah aku, Adras.",
  ui_story_5076_50760600_27_dialog_content = "Ya? Oh, sebelum saya lupa... Apakah Eclipsite di garis depan sudah ditangani? Akankah kita bisa menikmati kedamaian lagi?",
  ui_story_5076_50760600_28_dialog_content = "Kita berhasil mendorong Eclipsite kembali ke utara tetapi masih tidak bisa berbuat apa-apa tentang jurang yang kita temukan di sana.",
  ui_story_5076_50760600_29_dialog_content = "Apakah Anda bersedia kembali ke medan pertempuran, Adras?",
  ui_story_5076_50760600_30_dialog_content = "Tentu saja. Lagipula, tugasku adalah melindungi rumah dan negaraku.",
  ui_story_5076_50760600_31_dialog_content = "Kamu bersedia membiarkan saya kembali bertempur, kan Marcela? Jangan khawatir, aku akan selalu menepati janjiku padamu.",
  ui_story_5076_50760600_32_dialog_content = "...",
  ui_story_5076_50760600_33_dialog_content = "Ludweiss, kamu pernah bilang padaku bahwa cinta adalah sumber kekuatan seorang Caelestite. Didorong oleh kekuatan emosi, kamu dan orang-orangmu telah mencapai hal-hal luar biasa.",
  ui_story_5076_50760600_34_dialog_content = "Beritahu saya, apakah ada cara untuk mengekstrak emosi seorang Aurorian dan melestarikannya?",
  ui_story_5076_50760600_35_dialog_content = "Apa sebenarnya yang kamu usulkan?",
  ui_story_5076_50760600_36_dialog_content = "Saat ini, Adras perlu digerakkan oleh kebencian dan dendam. Namun, aku tidak ingin cinta di hatinya terserap olehnya.",
  ui_story_5076_50760600_37_dialog_content = "Apa gerangan yang kalian berdua bicarakan?",
  ui_story_5076_50760600_38_dialog_content = "Ludweiss, saya perlu tahu apakah ada cara untuk mengekstrak cinta itu dan menjaganya dengan aman.",
  ui_story_5076_50760600_39_dialog_content = "Aku mengerti... Aku akan memikirkan sesuatu.",
  ui_story_5076_50760600_40_dialog_content = "Apakah kamu bersedia meminjamkan perisai dan kekuatanmu lagi padaku, Adras?",
  ui_story_5076_50760600_41_dialog_content = "Jelas, dong!",
  ui_story_5076_50760600_42_dialog_content = "Seberapa besar Anda membenci Eclipsites? Apakah Anda bersedia mengabdikan hidup dan segala yang Anda miliki untuk pemusnahan mereka secara total?",
  ui_story_5076_50760600_43_dialog_content = "Eclipsites... Itu sudah jelas! Aku tidak memiliki apa-apa di hatiku selain kebencian untuk mereka...",
  ui_story_5076_50760600_44_dialog_content = "Bahkan dengan beban keabadian di pundakmu, apakah kamu bersumpah untuk melawan kejahatan ini dengan sepenuh hati sampai tidak ada yang tersisa?",
  ui_story_5076_50760600_45_dialog_content = "Aku... aku bersumpah.",
  ui_story_5076_50760600_46_dialog_content = "Maka, atas nama prajurit kami yang bangga dan diri saya sendiri, sekali lagi nyawa kami berada di tangan Anda yang mampu.",
  ui_story_5076_50760600_47_dialog_content = "Selamat kembali bertugas, Adras.",
  ui_story_5076_50760600_48_dialog_content = "Selamat kembali ke perang.",
  ui_story_5076_50760600_49_dialog_content = "Jadi, sebaiknya aku mulai dari mana?",
  ui_story_5076_50760600_50_dialog_content = "Untuk membasmi jurang di utara, istana kerajaan mengusulkan metode baru untuk meningkatkan kekuatan kita.",
  ui_story_5076_50760600_51_dialog_content = "Sebuah proyek yang akan menghabiskan kita, tetapi tidak sebelum kita membersihkan dunia kita dari semua kejahatan.",
  ui_story_5076_50760600_52_dialog_content = "Dan nama proyek itu adalah—",
  ui_story_5076_50760600_53_dialog_content = "<color=#FFB400>The Silent Hunters.</color>",
  ui_story_5076_50760701_1_dialog_content = "<color=#e8d9bb>Setelah meraih kemenangan besar di garis depan utama, pasukan kerajaan menyebar dan memukul mundur, bertujuan untuk merebut kembali kota-kota yang dikuasai oleh Eclipsite.</color>",
  ui_story_5076_50760701_2_dialog_content = "<color=#e8d9bb>Di antara mereka, beberapa telah sepenuhnya berubah menjadi \"sarang\" dari Eclipsite.</color>",
  ui_story_5076_50760701_3_dialog_content = "<color=#e8d9bb>Pada saat itu, \"pahlawan\" dengan wajah baru akan melangkah ke atas panggung.</color>",
  ui_story_5076_50760701_4_dialog_content = "Laporan! Penjaga telah mengkonfirmasi kondisi di dalam kota—sudah sepenuhnya jatuh, dengan Eclipsite yang berlarian kesana-kemari!",
  ui_story_5076_50760701_5_dialog_content = "Dan rakyatnya? Apakah ada tanda-tanda mereka masih bertahan hidup?",
  ui_story_5076_50760701_6_dialog_content = "... Tidak ada yang selamat.",
  ui_story_5076_50760701_7_dialog_content = "Hentikan serangan. Prajuritmu tidak memiliki cara untuk berjuang masuk ke kota.",
  ui_story_5076_50760701_8_dialog_content = "Eclipsite tidak mengenal rasa takut. Kecuali kita menjatuhkan kota ini di kepala mereka, mereka tidak akan mundur.",
  ui_story_5076_50760701_9_dialog_content = "Jenderal... Tidak, Kapten, apa yang harus kita lakukan sekarang?",
  ui_story_5076_50760701_10_dialog_content = "Salah satu anggota skuadku sudah dalam perjalanan. Letakkan sisanya dari pasukanmu siaga di belakang.",
  ui_story_5076_50760701_11_dialog_content = "Maksudmu... Ah!",
  ui_story_5076_50760701_12_dialog_content = "Kamu di sana, prajurit. Kau menghalangi jalanku, jadi tolong ambil langkah ke kanan.",
  ui_story_5076_50760701_13_dialog_content = "<color=#e8d9bb>Mengikuti perintah dari komandan yang tidak dikenal, prajurit itu sedikit bergeser ke samping, dan kilatan petir meletus dari ujung jarinya, menghancurkan gerbang kota yang telah menahan serangan mereka yang berkepanjangan.</color>",
  ui_story_5076_50760701_14_dialog_content = "Gerbang mungkin terbuka, tetapi masih banyak Eclipsite yang licik bersembunyi di balik tembok kota. Aku akan meninggalkan mereka untukmu... Cynthia.",
  ui_story_5076_50760701_15_dialog_content = "<color=#e8d9bb>Dengan busur panjang yang tegang seperti bulan sabit, pahlawan berwarna hijau melepaskan hujan panah dengan anggun. Setiap kali dia mencabut dawai busur, Eclipsite yang mahir dalam serangan jarak jauh jatuh satu per satu.</color>",
  ui_story_5076_50760701_16_dialog_content = "Tembakan bagus! Serangan terakhirmu pasti benar-benar membuat mereka marah, karena mereka mulai berbondong-bondong keluar dari gerbang.",
  ui_story_5076_50760701_17_dialog_content = "Bersamaku, ksatria! Kita akan menyerbu pertempuran!",
  ui_story_5076_50760701_18_dialog_content = "Para ksatria tidak memiliki kesempatan melawan Eclipsites raksasa itu, Freya.",
  ui_story_5076_50760701_19_dialog_content = "Mereka akan baik-baik saja! Friegson—Gelombang pertama adalah milikmu!",
  ui_story_5076_50760701_20_dialog_content = "<color=#e8d9bb>Dengan kata-katanya yang bergema, sebuah kobaran api menyala di kejauhan. Api yang menderu tanpa ampun menelan monster-monster besar itu.</color>",
  ui_story_5076_50760701_21_dialog_content = "<color=#e8d9bb>Kota yang biasanya membutuhkan hari bagi pasukan biasa untuk ditaklukkan, dengan mudah dapat ditaklukkan oleh mereka.</color>",
  ui_story_5076_50760701_22_dialog_content = "<color=#e8d9bb>Kavaleri yang dipimpin oleh Silent Saintess Freya dengan mudah menginjak-injak Eclipsites, tombaknya melibas dengan dominasi yang tak tertandingi. Eclipsites yang jatuh cepat terbelit dalam lidah api, meronta dalam penderitaan.</color>",
  ui_story_5076_50760701_23_dialog_content = "Betapa kejamnya... Tidak perlu mempermainkan mereka seperti ini, Friegson.",
  ui_story_5076_50760701_24_dialog_content = "Eclipsite tidak pantas mendapatkan simpati.",
  ui_story_5076_50760701_25_dialog_content = "Di mana Vice Kapten?",
  ui_story_5076_50760701_26_dialog_content = "Eclipsite mundur ke dalam kota. Sepertinya mereka bisa merasakan semacam rasa takut setelah semua... Tapi aku yakin dia sudah menunggu mereka di sana.",
  ui_story_5076_50760701_27_dialog_content = "Jika mereka tidak melarikan diri, setidaknya mereka akan diberi kematian yang baik... Itu lebih dari yang mereka layak.",
  ui_story_5076_50760701_28_dialog_content = "<color=#e8d9bb>... Ketika para Eclipsite, didorong oleh rasa takut insting, melarikan diri menuju gerbang belakang, ada satu sosok yang berdiri sendiri untuk menghalangi jalan mereka.</color>",
  ui_story_5076_50760701_29_dialog_content = "<color=#e8d9bb>Magi air yang tak kenal ampun, ditambah dengan pedang kolosal yang dingin itu, dengan mudah menghancurkan mereka yang berani maju, meninggalkan Eclipsite tanpa jalan untuk melarikan diri.</color>",
  ui_story_5076_50760701_30_dialog_content = "Kematian untuk semua musuh... Kematian untuk semua musuh... Kematian untuk semua musuh...",
  ui_story_5076_50760701_31_dialog_content = "Eclipsites! <size=45>Mati!!!</size>",
  ui_story_5076_50760702_1_dialog_content = "Eclipsite—Mati—",
  ui_story_5076_50760702_2_dialog_content = "Kalian semua harus mati!",
  ui_story_5076_50760702_3_dialog_content = "Tenang, Adras... Kamu menakut-nakuti prajurit.",
  ui_story_5076_50760702_4_dialog_content = "M-Marcela? Jangan mendekat, di sini berbahaya!",
  ui_story_5076_50760702_5_dialog_content = "Apakah itu... Silent Hunter?",
  ui_story_5076_50760702_6_dialog_content = "Sangat menakutkan. Sulit membayangkan dia adalah pahlawan legendaris. Lihat dia! Dia benar-benar...",
  ui_story_5076_50760702_7_dialog_content = "Jangan keras-keras; dia mungkin bisa mendengar kita.",
  ui_story_5076_50760702_8_dialog_content = "Apa pertempuran sudah selesai? Apakah semua orang aman sekarang?",
  ui_story_5076_50760702_9_dialog_content = "Kamu melakukannya dengan baik, Adras.",
  ui_story_5076_50760702_10_dialog_content = "Tapi... Tidak ada satu pun yang selamat di kota ini... Eclipsite yang busuk itu.",
  ui_story_5076_50760702_11_dialog_content = "Itu bukan salahmu. Sisa tim sedang datang, ayo kita pergi sekarang.",
  ui_story_5076_50760702_12_dialog_content = "...",
  ui_story_5076_50760702_13_dialog_content = "Perayaan unggun api lainnya untuk Silent Hunters!",
  ui_story_5076_50760702_14_dialog_content = "Apakah begitu? Saya tidak ingat pernah menjadi bagian dari tim, atau Anthony sekalipun.",
  ui_story_5076_50760702_15_dialog_content = "Kamu harus kembali, Anthony. Terus berada di sekitar kami, dan orang-orang akan mulai takut padamu juga.",
  ui_story_5076_50760702_16_dialog_content = "Maaf, Jenderal Achilles, kau memang seorang pahlawan tetapi...",
  ui_story_5076_50760702_17_dialog_content = "Aku bukan lagi seorang jenderal, Anthony. Kamu tidak perlu memanggilku seperti itu.",
  ui_story_5076_50760702_18_dialog_content = "Namun…",
  ui_story_5076_50760702_19_dialog_content = "Di sini tidak ada jenderal atau komandan. Hanya Silent Hunters.",
  ui_story_5076_50760702_20_dialog_content = "Jangan berbelit-belit, Anthony. Jika kamu ingin makan bersama kami, katakan saja.",
  ui_story_5076_50760702_21_dialog_content = "Oh, begitu…",
  ui_story_5076_50760702_22_dialog_content = "Hei Ludweiss, jangan makan semua daging yang sudah dimasak untuk diri sendiri!",
  ui_story_5076_50760702_23_dialog_content = "Apa masalahnya? Cukup minta Friegson untuk membuatkan lebih banyak untukmu.",
  ui_story_5076_50760702_24_dialog_content = "Dia hanya akan membakar semuanya menjadi abu, kamu idiot. Lagipula, aku tidak mau makanan yang dia masak.",
  ui_story_5076_50760702_25_dialog_content = "Ada yang ingin kamu katakan padaku?",
  ui_story_5076_50760702_26_dialog_content = "Yang dia maksud adalah dia tidak ingin makan apa pun yang dimasak oleh api pembunuh Eclipsite milikmu.",
  ui_story_5076_50760702_27_dialog_content = "Benar sekali!",
  ui_story_5076_50760702_28_dialog_content = "Aku akan pergi ke tempat lain untuk makan.",
  ui_story_5076_50760702_29_dialog_content = "Tidak, tunggu! Aku hanya bercanda... Ugh, ini semua salahmu, Cynthia.",
  ui_story_5076_50760702_30_dialog_content = "Aku hanya membantumu mengungkapkan pendapatmu.",
  ui_story_5076_50760702_31_dialog_content = "Kita tidak seharusnya bertengkar saat kita makan—Nah, ambil lagi.",
  ui_story_5076_50760702_32_dialog_content = "Wow, aku sangat terharu! Kamu adalah alasan utama aku memilih untuk bergabung dengan Silent Hunters.",
  ui_story_5076_50760702_33_dialog_content = "Kupikir kamu bilang itu untuk melindungi kerajaan dan rakyatnya...",
  ui_story_5076_50760702_34_dialog_content = "\"Sang Santa yang Pendiam,\" huh... Saya tidak bisa memikirkan nama yang kurang cocok untuk seseorang sepertimu.",
  ui_story_5076_50760702_35_dialog_content = "Ah, aku kenyang! Mungkin sebaiknya aku mulai mengerjakan tugas hari ini...",
  ui_story_5076_50760702_36_dialog_content = "Apa, kamu masih menulis jurnal itu?",
  ui_story_5076_50760702_37_dialog_content = "Hari saya meninggalkan rumah, saya memutuskan untuk mencatat segala hal tentang perjalanan saya. Saya tidak akan menyerah begitu saja pada hal seperti itu.",
  ui_story_5076_50760702_38_dialog_content = "Tapi sejak Adras menyelamatkanku dari Eclipsites, aku belum pernah bepergian keluar kerajaan.",
  ui_story_5076_50760702_39_dialog_content = "Masih banyak tempat yang ingin saya kunjungi, tapi saya bertemu dengan Eclipsite saat saya mulai bepergian lagi. Itulah saat kamu menyelamatkanku, Freya—",
  ui_story_5076_50760702_40_dialog_content = "Dan setelah terjebak di sini begitu lama, catatanku sekarang tentang kamu dan rekan-rekan skuadmu.",
  ui_story_5076_50760702_41_dialog_content = "Apakah kamu sudah pastikan menulis tentang betapa heroiknya aku hari ini?",
  ui_story_5076_50760702_42_dialog_content = "Aku baru saja akan melakukannya, jadi bisakah kamu memberiku sedikit ruang? Kau akan menumpahkan tintaku ke mana-mana—",
  ui_story_5076_50760702_43_dialog_content = "Saya terkejut kamu masih bisa begitu ceria setelah melihat kekacauan di luar sana hari ini.",
  ui_story_5076_50760702_44_dialog_content = "Nah, mengingat kaulah yang paling bertanggung jawab atas kehancuran ini...",
  ui_story_5076_50760702_45_dialog_content = "Cukup, Freya. Saya juga harus disalahkan untuk pertempuran hari ini.",
  ui_story_5076_50760702_46_dialog_content = "Dia memang mengemukakan poin yang bagus, Friegson.",
  ui_story_5076_50760702_47_dialog_content = "Kamu tidak seharusnya terlalu tegang dalam pertempuran. Bahkan tali busur terkuat pun akan putus di bawah tekanan yang cukup.",
  ui_story_5076_50760702_48_dialog_content = "Friegson telah berada di sisiku untuk waktu yang lama sekarang... Sebelum saya ditugaskan di utara, kami berdua bertugas sebagai pengawal istana.",
  ui_story_5076_50760702_49_dialog_content = "Dibandingkan dengan kalian yang sudah terbiasa melihat pertempuran seperti ini, dia masih perlu melakukan beberapa penyesuaian.",
  ui_story_5076_50760702_50_dialog_content = "Sebagai seorang bangsawan sejak lahir, saya yakin kamu selalu melihat medan tempur sebagai tempat kehormatan dan kemuliaan, Freya. Tapi kamu harus mengerti bahwa untuk merenggut nyawa, kamu harus siap untuk menyerahkan nyawamu sendiri.",
  ui_story_5076_50760702_51_dialog_content = "Hal yang sama berlaku untukmu, Friegson. Kita semua sekarang bagian dari Silent Hunters, jadi perlakukan mereka seperti kamu memperlakukan kawan-kawanmu di masa lalu.",
  ui_story_5076_50760702_52_dialog_content = "Maafkan saya, Kapten...",
  ui_story_5076_50760702_53_dialog_content = "Benarkan saya jika saya salah, kapten, tapi bukankah Anda pernah menjadi bagian dari Dewan Tetua sebelumnya? Itu akan membuat Anda lebih mulia daripada kami semua.",
  ui_story_5076_50760702_54_dialog_content = "Jenderal Achilles tumbuh bersama Raja di masa lalu.",
  ui_story_5076_50760702_55_dialog_content = "Itu menjelaskan bagaimana seseorang yang begitu muda bisa menjadi kapten pengawal istana...",
  ui_story_5076_50760702_56_dialog_content = "Tapi pada akhirnya, kamu memilih untuk menjadi \"prajurit super,\" sama seperti kami.",
  ui_story_5076_50760702_57_dialog_content = "Aku lebih suka menghadapi musuh di medan perang daripada terlibat dalam permainan politik mereka.",
  ui_story_5076_50760702_58_dialog_content = "Tapi, meskipun bukan niatmu, Raja saat ini fokus pada penindasan Dewan Penatua. Saya ragu dia akan mempercayaimu seperti dulu.",
  ui_story_5076_50760702_59_dialog_content = "Kalau tidak, dia tidak akan membiarkan kamu menjadi...",
  ui_story_5076_50760702_60_dialog_content = "Cukup sudah! Kamu juga pernah menjadi penjaga istana, bukan Cynthia? Saya jarang sekali mendengar kamu berbicara tentang dirimu sendiri, dan Kapten Achilles juga tidak memberi tahu kami apa-apa.",
  ui_story_5076_50760702_61_dialog_content = "Saya dengar kamu mendekati kapten dan secara sukarela mendaftar untuk proyek ini, sedangkan dia yang memilih kami yang lain.",
  ui_story_5076_50760702_62_dialog_content = "Aku... Aku tumbuh besar di hutan, jadi tidak banyak yang bisa aku ceritakan.",
  ui_story_5076_50760702_63_dialog_content = "Jika busurku dibutuhkan di garis depan, maka itulah tempat aku akan pergi.",
  ui_story_5076_50760702_64_dialog_content = "Jika mereka membutuhkan saya untuk proyek tersebut, maka saya akan membiarkan mereka memperkuat saya sesuai yang mereka anggap cocok.",
  ui_story_5076_50760702_65_dialog_content = "\"Augmentasi\"?",
  ui_story_5076_50760702_66_dialog_content = "Ah! I-Ini tidak apa-apa, Adras... Hei, kamu tidak akan makan?",
  ui_story_5076_50760702_67_dialog_content = "Baru saja mau mulai…",
  ui_story_5076_50760702_68_dialog_content = "Semua ini gara-gara itu, ya? Baik manusia maupun monster, dan kami terpaksa makan di sudut sendirian.",
  ui_story_5076_50760702_69_dialog_content = "Kami memiliki misi khusus. Tugas kami adalah melawan Eclipsite yang lebih kuat.",
  ui_story_5076_50760702_70_dialog_content = "Mengambil langkah pertama ke dalam neraka... Lebih baik jika kita bisa menjauhkan orang lain dari hal semacam ini.",
  ui_story_5076_50760702_71_dialog_content = "Meski kita harus membayar harganya, itu lebih baik daripada membiarkan mereka mengorbankan nyawa mereka sendiri.",
  ui_story_5076_50760702_72_dialog_content = "Tapi Vice Kapten... Anda menyerahkan status Anda sebagai komandan untuk bergabung dengan Silent Hunters, sama seperti kapten menyerahkan statusnya sebagai jenderal...",
  ui_story_5076_50760702_73_dialog_content = "Setelah membayar harga tersebut dan terus menerus menempatkan hidupmu dalam bahaya, hanya untuk orang-orang yang takut padamu... Bukankah itu tidak adil?",
  ui_story_5076_50760702_74_dialog_content = "Silent Hunters adalah monster yang diciptakan untuk melawan Eclipsite yang kuat. Tujuan kami adalah untuk memastikan kehancuran mereka; tidak ada lagi yang penting bagi kami.",
  ui_story_5076_50760702_75_dialog_content = "Hanya dengan tetap netral dan menunjukkan sikap menahan diri, kita dapat melanjutkan perjuangan kita melawan kegelapan.",
  ui_story_5076_50760702_76_dialog_content = "Apa kau merasa telah diperlakukan tidak adil, Freya?",
  ui_story_5076_50760702_77_dialog_content = "Mungkin hanya sedikit... Tapi tak masalah!",
  ui_story_5076_50760702_78_dialog_content = "Aku adalah orang yang membuat keputusan untuk melindungi orang lain. Aku tidak peduli apa yang dipikirkan orang lain, selama aku bisa berpegang pada keputusanku.",
  ui_story_5076_50760702_79_dialog_content = "Aku yakin itu berlaku untuk kita semua.",
  ui_story_5076_50760702_80_dialog_content = "Bagaimana perasaanmu tentang perubahan pada tubuhmu, Vice Kapten? Apakah tatapan orang-orang mengganggumu saat kamu sedang bertarung?",
  ui_story_5076_50760702_81_dialog_content = "... Bolehkah saya bertanya seperti itu, Kapten?",
  ui_story_5076_50760702_82_dialog_content = "Anda sudah melakukannya.",
  ui_story_5076_50760702_83_dialog_content = "Seperti yang pernah dikatakan Kapten Achilles, melawan monster-monster itu akan merusak kita seiring waktu. Aku sudah sepenuhnya siap menerima konsekuensinya.",
  ui_story_5076_50760702_84_dialog_content = "Selama tidak ada orang lain yang harus menderita seperti ini, saya bisa menerima konsekuensinya.",
  ui_story_5076_50760702_85_dialog_content = "Bagaimana... Bagaimana kamu melakukannya?",
  ui_story_5076_50760702_86_dialog_content = "Kamu seperti orang yang benar-benar berbeda di luar medan perang! Tolong tunjukkan padaku bagaimana kamu melakukannya!",
  ui_story_5076_50760702_87_dialog_content = "Aku juga! Ajari kami cara menekan emosi seperti kamu!",
  ui_story_5076_50760702_88_dialog_content = "Boleh saja, sih…",
  ui_story_5076_50760702_89_dialog_content = "Semuanya dimulai... Dengan cinta.",
  ui_story_5076_50760702_90_dialog_content = "Sungguh?",
  ui_story_5076_50760702_91_dialog_content = "Menurut Ludweiss, cinta dan kerinduan saya pada istri saya tersegel dalam pedang ini.",
  ui_story_5076_50760702_92_dialog_content = "Selama aku memegangnya di tangan, hati kita akan selalu terhubung, tidak peduli sejauh apa jaraknya.",
  ui_story_5076_50760702_93_dialog_content = "Untuk melindunginya, dan menjaga kejahatan ini agar tidak mencapai rumah bahagia kita... Itulah yang saya pedulikan.",
  ui_story_5076_50760702_94_dialog_content = "Tiba-tiba aku merasa... sangat dingin.",
  ui_story_5076_50760702_95_dialog_content = "Setiap kali Vice Kapten berbicara tentang istrinya, semua ototku mulai terasa pegal...",
  ui_story_5076_50760702_96_dialog_content = "Aku masih ingat dia...",
  ui_story_5076_50760702_97_dialog_content = "Dia tetap tinggal untuk membantu membangun kembali kota mereka.",
  ui_story_5076_50760702_98_dialog_content = "Tidak heran Vice Kapten menolak untuk bertemu siapa pun saat dia tidak sedang menjalankan misi—",
  ui_story_5076_50760702_99_dialog_content = "... Apakah kamu juga berteman dengan istrinya, Ludweiss?",
  ui_story_5076_50760702_100_dialog_content = "Y-Ya! Ini mengingatkanku bahwa aku berjanji untuk membawakan dia beberapa materi pengajaran baru saat aku kembali nanti.",
  ui_story_5076_50760702_101_dialog_content = "Jadi mengapa Anda terus ikut bersama kami?",
  ui_story_5076_50760702_102_dialog_content = "Er—Untuk membuat lebih banyak rekor, tentu saja!",
  ui_story_5076_50760702_103_dialog_content = "Saya rasa tidak ada kekurangan orang aneh di medan perang saat ini.",
  ui_story_5076_50760702_104_dialog_content = "Cukup tentang itu. Ini, minumlah secangkir anggur ini. Adras membuatnya sendiri—Ini adalah favorit kami saat masih di hari-hari militer!",
  ui_story_5076_50760702_105_dialog_content = "Tepuk tangan, semuanya!",
  ui_story_5076_50760800_1_dialog_content = "Salam, Adras! Kamu mau ke mana?",
  ui_story_5076_50760800_2_dialog_content = "Istri saya dan saya menunjukkan beberapa lokasi untuk panti asuhan baru kepada anak-anak.",
  ui_story_5076_50760800_3_dialog_content = "Istrimu? Saya tidak tahu tentang... Anyway, selamat atas pernikahan barumu!",
  ui_story_5076_50760800_4_dialog_content = "Hah? Marcela dan aku sudah lama menikah, tapi terima kasih juga. Ayo, sayangku.",
  ui_story_5076_50760800_5_dialog_content = "Tidak... Aku tidak mau mendekati kuil itu...",
  ui_story_5076_50760800_6_dialog_content = "Tidak ada di sana juga? Kalau begitu, mari kita pilih tempat lain.",
  ui_story_5076_50760800_7_dialog_content = "Ohh... Saya benar-benar minta maaf, Adras! Itu... kelalaian saya. Anda sangat menjulang; saya tidak melihat Lady Marcela pada pandangan pertama.",
  ui_story_5076_50760800_8_dialog_content = "... Tolong hati-hati di jalanmu.",
  ui_story_5076_50760800_9_dialog_content = "Terima kasih.",
  ui_story_5076_50760800_10_dialog_content = "Apakah kamu kembali menurunkan berat badan, Marcela? Orang-orang hampir tidak bisa melihatmu berdiri di belakangku; mereka mungkin mulai berpikir kamu adalah orang lain.",
  ui_story_5076_50760800_11_dialog_content = "Hmph... Pernahkah kamu berpikir bahwa kamu lah yang menambah berat badan?",
  ui_story_5076_50760800_12_dialog_content = "Rekonstruksi tampaknya berjalan dengan baik, Adras. Anda telah bekerja keras, bukan?",
  ui_story_5076_50760800_13_dialog_content = "Ludweiss! Lama tak jumpa, teman saya!",
  ui_story_5076_50760800_14_dialog_content = "Saya senang melihat bahwa Anda telah melakukannya dengan baik akhir-akhir ini.",
  ui_story_5076_50760800_15_dialog_content = "Apakah, uh... Marcela juga baik-baik saja?",
  ui_story_5076_50760800_16_dialog_content = "Kamu berbicara padaku seolah-olah dia tidak berada tepat di depanmu! Hmm? Kemana kamu melihat, Ludweiss? Tidakkah kamu melihat Marcela berdiri di belakangku?",
  ui_story_5076_50760800_17_dialog_content = "... Apakah Adras telah mendengarkanmu seperti suami yang baik, Marcela?",
  ui_story_5076_50760800_18_dialog_content = "Jangan terlalu menggoda dia, Ludweiss. Tidak mudah baginya untuk meninggalkan garis depan, dan dia baru saja kembali.",
  ui_story_5076_50760800_19_dialog_content = "Itu mengingatkanku... Bukankah kamu akan pergi ke suatu tempat dengan Freya dan yang lainnya? Maaf, mungkin karena aku sangat sibuk, aku tidak bisa mengingatnya.",
  ui_story_5076_50760800_20_dialog_content = "Sangat bisa dimengerti! Bagaimanapun, kamu sedang mengawasi rekonstruksi seluruh kota. Aku hanya datang untuk mengantarkan surat dari Achilles.",
  ui_story_5076_50760800_21_dialog_content = "Surat?",
  ui_story_5076_50760800_22_dialog_content = "Adras, Marcela, halo!",
  ui_story_5076_50760800_23_dialog_content = "Hai, Adras!",
  ui_story_5076_50760800_24_dialog_content = "Bodoh, kenapa hanya menyapa Adras? Bukankah aku sudah mengajarmu—",
  ui_story_5076_50760800_25_dialog_content = "Sekarang, sekarang, jangan ganggu adikmu yang kecil.",
  ui_story_5076_50760800_26_dialog_content = "Kamu tidak keberatan, kan, Marcela?",
  ui_story_5076_50760800_27_dialog_content = "Mmm.",
  ui_story_5076_50760800_28_dialog_content = "Maaf, Adras, dan... Mar-Marcela.",
  ui_story_5076_50760800_29_dialog_content = "Adras, baru saja kembali dari pinggiran kota hari ini?",
  ui_story_5076_50760800_30_dialog_content = "Adras, anggur ini berasal dari kebun anggur kami sendiri. Ambillah; mereka rasanya enak dan bagus untuk membuat anggur.",
  ui_story_5076_50760800_31_dialog_content = "Teman-teman, beri jalan! Adras, lihat kain ini; ini sangat cocok untuk membuat pakaian baru untuk Marcela.",
  ui_story_5076_50760800_32_dialog_content = "Anda benar-benar tidak perlu melakukan ini. Marcela tidak akan berhenti membicarakannya jika Anda melakukannya.",
  ui_story_5076_50760800_33_dialog_content = "Ah—Marcela?",
  ui_story_5076_50760800_34_dialog_content = "Kemana kamu pergi, Sayangku?",
  ui_story_5076_50760800_35_dialog_content = "...Aku melihat dia berlari kembali!",
  ui_story_5076_50760800_36_dialog_content = "Ya, dia pasti pemalu, haha!",
  ui_story_5076_50760800_37_dialog_content = "Atau mungkin dia marah, ini semua salahmu.",
  ui_story_5076_50760800_38_dialog_content = "Ayo pergi; beri sedikit ruang pribadi untuk pahlawan hebat kita, oke?",
  ui_story_5076_50760800_39_dialog_content = "Maaf Ludweiss, orang-orang di sini bisa sedikit berlebihan kadang-kadang. Apa yang tadi kamu katakan tentang—",
  ui_story_5076_50760800_40_dialog_content = "Ludweiss? Ke-Kenapa kamu menangis...? Apakah kamu baik-baik saja?",
  ui_story_5076_50760800_41_dialog_content = "A... A... Aku baik-baik saja, hanya saja... Itu sangat menyentuh tadi.",
  ui_story_5076_50760800_42_dialog_content = "Semua orang memperlakukan kalian berdua dengan baik... Aku sangat bahagia untuk kalian.",
  ui_story_5076_50760800_43_dialog_content = "Itu karena mereka semua adalah orang-orang baik.",
  ui_story_5076_50760800_44_dialog_content = "Aku tahu... Mereka benar-benar orang baik...",
  ui_story_5076_50760800_45_dialog_content = "Ini saputangan. Ambillah.",
  ui_story_5076_50760800_46_dialog_content = "Merasa lebih baik sekarang?",
  ui_story_5076_50760800_47_dialog_content = "Ya. Terima kasih, Adras—",
  ui_story_5076_50760800_48_dialog_content = "Kamu menyebutkan sesuatu tentang sebuah surat. Apakah kapten memiliki perintah baru untukku?",
  ui_story_5076_50760800_49_dialog_content = "... Raja sedang mempersiapkan ekspedisi baru. Dia ingin memusnahkan kejahatan dari sumbernya.",
  ui_story_5076_50760800_50_dialog_content = "Kali ini, dia mengirim Anda dan Silent Hunters untuk menangani abyss yang pertama kali ditemukan di utara.",
  ui_story_5076_50760800_51_dialog_content = "Jadi, dunia ini masih belum damai.",
  ui_story_5076_50760800_52_dialog_content = "Aku terima.",
  ui_story_5076_50760800_53_dialog_content = "Apakah ada pasukan lain yang akan bergabung dengan Silent Hunters dalam kampanye ini?",
  ui_story_5076_50760800_54_dialog_content = "Dari yang saya tahu, dua legiun juga telah ditugaskan untuk itu.",
  ui_story_5076_50760800_55_dialog_content = "Siapa yang akan memimpin mereka?",
  ui_story_5076_50760800_56_dialog_content = "Ini adalah Imam Besar Lucius... Dia telah dipulihkan oleh raja. Tidak hanya itu, dia akan mengambil alih komando penuh dari seluruh ekspedisi.",
  ui_story_5076_50760800_57_dialog_content = "Apa? Dasar pengkhianat tengik itu?!",
  ui_story_5076_50760800_58_dialog_content = "Tapi dia memobilisasi pasukan pribadinya sendiri selama perang terakhir! Tak terhitung banyaknya orang yang tewas karena dia!",
  ui_story_5076_50760800_59_dialog_content = "Semua kota itu di mana tidak ada yang selamat adalah hasil dari kejahatannya! Kamu berarti mengatakan bahwa tiba-tiba pria ini bertanggung jawab atas operasi kita?!",
  ui_story_5076_50760800_60_dialog_content = "Ini salahnya begitu banyak orang tak bersalah yang mati! Marcela hampir kehilangan hidupnya karena dia juga!",
  ui_story_5076_50760800_61_dialog_content = "Tidak! Dia tidak pantas mendapatkan belas kasihan! Aku tidak akan memaafkannya karena—",
  ui_story_5076_50760800_62_dialog_content = "Harap tenang saja, Adras. Ini adalah perintah raja.",
  ui_story_5076_50760800_63_dialog_content = "Meski begitu, aku menolak untuk bekerja untuk orang seperti Lucius!",
  ui_story_5076_50760800_64_dialog_content = "Terkutuklah dia—",
  ui_story_5076_50760800_65_dialog_content = "Jangan salurkan frustrasimu pada Ludweiss, Adras.",
  ui_story_5076_50760800_66_dialog_content = "Marcela? Kamu kembali...",
  ui_story_5076_50760800_67_dialog_content = "Raja mungkin dikelilingi oleh pendusta dan penjilat sekarang... Tapi mereka bukanlah orang-orang yang telah kamu lindungi, bukan?",
  ui_story_5076_50760800_68_dialog_content = "Atau apakah kamu ingin melihat kota kita hancur untuk kedua kalinya?",
  ui_story_5076_50760800_69_dialog_content = "Untuk raja menelan harga dirinya dan membiarkan Lucius mendapatkan penghargaan atas kampanye ini hanya akan semakin mendorong tujuan jahatnya.",
  ui_story_5076_50760800_70_dialog_content = "Namun sebesar apapun rasa sakitku, aku tidak memiliki cara untuk menolaknya.",
  ui_story_5076_50760800_71_dialog_content = "Kapten membutuhkan saya, sekutu saya membutuhkan saya... Dan orang-orang tak bersalah di kerajaan kita membutuhkan saya...",
  ui_story_5076_50760800_72_dialog_content = "... Saya menerima perintah saya, Ludweiss.",
  ui_story_5076_50760800_73_dialog_content = "Setelah anak-anak dan saya menentukan lokasi baru untuk panti asuhan, saya akan mengumpulkan peralatan saya dan segera berangkat.",
  ui_story_5076_50760800_74_dialog_content = "Dipahami... Terima kasih, Adras.",
  ui_story_5076_50760800_75_dialog_content = "Terima kasih... Karena terus berjuang untuk dunia ini.",
  ui_story_5076_50760800_76_dialog_content = "Bagaimana dengan kamu? Apa tindakanmu selanjutnya?",
  ui_story_5076_50760800_77_dialog_content = "Saya...? Yah, sebenarnya saya ingin melihat aurora dengan mata kepala sendiri—",
  ui_story_5076_50760800_78_dialog_content = "Ekspedisi ini akan sangat berbahaya. Lebih baik jika kamu tidak ikut kali ini.",
  ui_story_5076_50760800_79_dialog_content = "Anda harus meninggalkan tempat ini, Ludweiss.",
  ui_story_5076_50760800_80_dialog_content = "Dunia ini adalah tempat yang luas dan luar biasa. Saya yakin kamu akan menemukan tempat yang jauh lebih menarik untuk ditulis di jurnalmu.",
  ui_story_5076_50760800_81_dialog_content = "... Maaf, tapi saya belum bisa pergi. Saya masih memiliki beberapa urusan yang harus diselesaikan di sini.",
  ui_story_5076_50760800_82_dialog_content = "Lagipula, saya tidak keberatan tinggal dan menemani Marcela. Benar, Marcela?",
  ui_story_5076_50760800_83_dialog_content = "Lalu, aku akan meninggalkannya di tanganmu, Ludweiss.",
  ui_story_5076_50760800_84_dialog_content = "Hanya kembalilah secepat mungkin. Tidak ada yang tahu kapan aku mungkin berubah pikiran, kamu tahu!",
  ui_story_5076_50760800_85_dialog_content = "Maka aku akan membuatmu janji yang sama seperti yang aku buat padanya—",
  ui_story_5076_50760800_86_dialog_content = "Bahwa aku akan kembali tidak peduli apa yang terjadi.",
  ui_story_5076_50760800_87_dialog_content = "Dan jika kebetulan saya menemui aurora selama perjalanan saya—",
  ui_story_5076_50760800_88_dialog_content = "Saya pasti akan memberi tahu kamu semua tentang keindahannya, teman saya.",
  ui_story_5076_50760800_89_dialog_content = "Sepertinya kesepakatan... Aku tak sabar mendengar ceritamu, wahai pahlawan perkasa.",
  ui_story_5076_50760900_1_dialog_content = "\"Waktu selalu terasa berlalu ketika kita paling tidak menyadarinya... Dan sebelum kita sadari—\"",
  ui_story_5076_50760900_2_dialog_content = "Guru Ludweiss, keluarlah ke sini cepat!",
  ui_story_5076_50760900_3_dialog_content = "Apa yang menyebabkan keributan ini? Saya hampir tidak punya kesempatan untuk menulis di jurnal saya akhir-akhir ini, tahu...",
  ui_story_5076_50760900_4_dialog_content = "Lama tak jumpa, Ludweiss.",
  ui_story_5076_50760900_5_dialog_content = "Adras? Kamu...",
  ui_story_5076_50760900_6_dialog_content = "Heh... Selamat datang di rumah, Adras.",
  ui_story_5076_50760900_7_dialog_content = "Cepat tutup pintunya, anak-anak! Jika ada yang melihat bahwa pahlawan perkasa kita telah kembali, seluruh kota akan menginjak-injak tempat ini hingga hancur!",
  ui_story_5076_50760900_8_dialog_content = "Anak-anak memberitahu saya bahwa Anda telah mengelola panti asuhan selama beberapa waktu. Saya tidak bisa cukup berterima kasih atas bantuan Anda, teman saya.",
  ui_story_5076_50760900_9_dialog_content = "Aku tidak pernah berpikir bahwa membesarkan sekelompok anak bisa begitu sulit. Bagaimana mungkin Marcela bisa—Batuk, batuk, batuk!",
  ui_story_5076_50760900_10_dialog_content = "Itu mengingatkan saya, di mana dia? Anak-anak bilang saya mungkin bisa menemukannya di sini bersama kamu.",
  ui_story_5076_50760900_11_dialog_content = "Hah? Dengan saya?",
  ui_story_5076_50760900_12_dialog_content = "Ah! Dia melihat saya menulis di jurnal saya, jadi dia baru saja pergi.",
  ui_story_5076_50760900_13_dialog_content = "Aku sangat minta maaf, aku tahu kau pasti sangat ingin menemuinya...",
  ui_story_5076_50760900_14_dialog_content = "Tidak apa-apa, Ludweiss. Selama aku memegang pedang ini di tangan, dia tidak akan pernah jauh dari sisiku.",
  ui_story_5076_50760900_15_dialog_content = "Ekspedisi ke utara itu panjang, tetapi tidak cukup panjang untuk memisahkan hati kami.",
  ui_story_5076_50760900_16_dialog_content = "Meski begitu, rasanya sedikit tidak nyaman tidak mendengar suaranya setelah perjalanan yang begitu panjang... Apakah kamu tahu kapan dia akan kembali?",
  ui_story_5076_50760900_17_dialog_content = "Saya tidak yakin—Itu mengingatkan saya, kami mendengar tentang kembalimu yang penuh kemenangan beberapa hari yang lalu! Saya dengar raja memuji kalian semua atas kesuksesan kalian.",
  ui_story_5076_50760900_18_dialog_content = "Benar. Kami semua juga diberikan gelar baru.",
  ui_story_5076_50760900_19_dialog_content = "Aku ingat membaca tentang itu juga di surat Freya!",
  ui_story_5076_50760900_20_dialog_content = "Gelar Anda sekarang adalah \"Regal\", benar? Dan Freya adalah \"Requiem,\" Friegson adalah \"Frostfire,\" dan Cynthia adalah \"Mythos.\"",
  ui_story_5076_50760900_21_dialog_content = "Namun, dia lupa memberitahuku gelar Achilles.",
  ui_story_5076_50760900_22_dialog_content = "\"Claymore.\" Itu adalah gelar baru Kapten Achilles.",
  ui_story_5076_50760900_23_dialog_content = "Terdengar mengesankan... Freya mengatakan mereka juga memberinya mahkota daun laurel. Mana mahkotamu?",
  ui_story_5076_50760900_24_dialog_content = "Aku menolaknya.",
  ui_story_5076_50760900_25_dialog_content = "Hah? Kenapa?",
  ui_story_5076_50760900_26_dialog_content = "Mahkota daun laurel yang saya kenakan ke medan perang diberikan kepada saya bertahun-tahun yang lalu, ketika saya mengakhiri perang melawan para pemberontak. Saat itu, saya diberi penghargaan baik dalam bentuk cinta maupun kehormatan.",
  ui_story_5076_50760900_27_dialog_content = "Itu sebabnya... Aku tidak membutuhkan yang lain.",
  ui_story_5076_50760900_28_dialog_content = "Ah, sayang sekali. Saya pasti senang melihat semua orang mendapatkan penghargaan atas usaha mereka.",
  ui_story_5076_50760900_29_dialog_content = "Meskipun saya menolak mahkota lain, saya masih meminta hadiah kepada raja berupa tanah dan uang.",
  ui_story_5076_50760900_30_dialog_content = "Betapa praktisnya kamu!",
  ui_story_5076_50760900_31_dialog_content = "Ini untuk warga kotaku—Mereka kehilangan begitu banyak karena perang. Aku tahu ini tidak akan pernah cukup untuk menggantikan apa yang telah hilang, tapi...",
  ui_story_5076_50760900_32_dialog_content = "Saya hanya berharap ini akan membuat hidup mereka sedikit lebih mudah.",
  ui_story_5076_50760900_33_dialog_content = "Adras...",
  ui_story_5076_50760900_34_dialog_content = "Aku melihat aurora saat aku berada di utara, Ludweiss.",
  ui_story_5076_50760900_35_dialog_content = "Sejujurnya, saya telah melihat aurora berkali-kali selama saya berada di utara, tetapi saya tidak pernah melihatnya sebagai sesuatu yang spesial. Saya tidak tahu mengapa, tetapi rasanya berbeda selama ekspedisi terakhir ini untuk beberapa alasan.",
  ui_story_5076_50760900_36_dialog_content = "Ketika aku melihat aurora menembus kegelapan dan menerangi langit, yang bisa kupikirkan hanyalah berharap Marcela ada di sana untuk melihatnya.",
  ui_story_5076_50760900_37_dialog_content = "Jika tidak ada begitu banyak bahaya tersembunyi di dunia ini, mungkin semua orang bisa melihat sesuatu yang seindah itu.",
  ui_story_5076_50760900_38_dialog_content = "Untuk alasan itu, aku tidak ingin memberi tahu lebih banyak tentang hal itu... Aku ingin kamu melihatnya sendiri suatu hari nanti, Ludweiss.",
  ui_story_5076_50760900_39_dialog_content = "Sepertinya kamu telah berubah, Adras... Tapi... Tidak apa-apa. Karena kamu tampak sangat bersemangat, itu berarti kampanye berjalan dengan sangat baik, bukan?",
  ui_story_5076_50760900_40_dialog_content = "Benar. Kami berhasil menghancurkan jurang maut, tapi dengan harga yang harus dibayar. Untungnya, sepertinya tidak ada prajurit biasa yang hilang.",
  ui_story_5076_50760900_41_dialog_content = "Kami bahkan melihat hujan meteor yang spektakuler sebelum kami pergi.",
  ui_story_5076_50760900_42_dialog_content = "Freya terharu hingga tak bisa berkata-kata. Cynthia dan yang lainnya tampaknya juga menikmatinya.",
  ui_story_5076_50760900_43_dialog_content = "Tak lama kemudian, kapten membuat Star Crest ini untuk kita.",
  ui_story_5076_50760900_44_dialog_content = "Ini dibuat dengan sangat baik! Saya tidak tahu bahwa Achilles memiliki bakat untuk hal semacam ini.",
  ui_story_5076_50760900_45_dialog_content = "Tidak peduli kemana kita pergi, kita akan selalu menjadi Pemburu yang Sunyi yang menyaksikan bintang-bintang pada hari itu.",
  ui_story_5076_50760900_46_dialog_content = "Ingatan seperti ini jauh lebih berharga daripada mahkota daun laurel mana pun.",
  ui_story_5076_50760900_47_dialog_content = "Hampir terdengar seperti kau sedang mengucapkan selamat tinggal...",
  ui_story_5076_50760900_48_dialog_content = "Itu karena memang begitu. Saya telah memutuskan untuk pensiun dari dinas dan menghabiskan sisa hari-hari saya di sini, dalam damai dan dengan Marcela di samping saya.",
  ui_story_5076_50760900_49_dialog_content = "Freya tidak menyebutkan apa pun tentang itu dalam suratnya. Apa yang akan terjadi pada Silent Hunters?",
  ui_story_5076_50760900_50_dialog_content = "Kami... Belum dibubarkan. Tapi sebagai bawahan langsung dari mahkota, kami akhirnya akan dikenakan kontrol Lucius.",
  ui_story_5076_50760900_51_dialog_content = "Aku menolak untuk mematuhinya. Hal yang sama berlaku untuk sisanya dari Silent Hunters.",
  ui_story_5076_50760900_52_dialog_content = "Lagipula, dengan ancaman Eclipsite yang sudah hilang, kerajaan tidak memerlukan kita lagi. Itu mungkin alasan mengapa tidak ada yang mencoba menghentikanku untuk pergi.",
  ui_story_5076_50760900_53_dialog_content = "Saya sangat setuju. Anda pasti lelah setelah bertahun-tahun berjuang, Adras; jika ada yang pantas beristirahat, itu adalah Anda.",
  ui_story_5076_50760900_54_dialog_content = "Heheh, aku belum bisa santai dulu. Aku masih perlu menemukan Marcela dan mengejutkannya.",
  ui_story_5076_50760900_55_dialog_content = "Sudah larut. Saya yakin dia akan segera kembali, jadi jangan pergi sendirian.",
  ui_story_5076_50760900_56_dialog_content = "Dia serius? Dia tidak melihat Marcela di sini, jadi di mana lagi dia bisa berada? Hmm...",
  ui_story_5076_50760900_57_dialog_content = "Bisakah jadi hatinya akhirnya mulai sembuh? Itu hal yang baik... Benar?",
  ui_story_5076_50760900_58_dialog_content = "<color=#e8d9bb>Pahlawan kembali setelah kemenangan, dan kota merayakannya dengan upacara besar-besaran.</color>",
  ui_story_5076_50760900_59_dialog_content = "<color=#e8d9bb><color=#FFB400>Temple</color>, tempat cinta bagi pahlawan, khusus direnovasi dan dengan khidmat dipersembahkan kepadanya.</color>",
  ui_story_5076_50760900_60_dialog_content = "<color=#e8d9bb>Tidak ada yang mengantisipasi bahwa akan segera menyaksikan masa kerusuhan besar.</color>",
  ui_story_5076_50760900_61_dialog_content = "Bagaimana ini bisa terjadi? Kuil yang telah kita renovasi dengan susah payah...",
  ui_story_5076_50760900_62_dialog_content = "Apa yang sebenarnya terjadi di sini?",
  ui_story_5076_50760900_63_dialog_content = "Adras? Kamu...",
  ui_story_5076_50760900_64_dialog_content = "Mengapa kuil ini menjadi reruntuhan?",
  ui_story_5076_50760900_65_dialog_content = "Mungkin... itu Eclipsites?",
  ui_story_5076_50760900_66_dialog_content = "Eclipsites yang terkutuk—Beraninya mereka menginjak tempat ini, terutama ketika tempat ini sangat berarti bagi Marcela dan saya!!!",
  ui_story_5076_50760900_67_dialog_content = "Tolong jangan marah. Setidaknya tidak ada yang terluka sekarang. Tenang saja.",
  ui_story_5076_50760900_68_dialog_content = "... Saya lega mendengar bahwa tidak ada yang terluka. Biarkan perbaikan kuil menjadi tanggung jawab saya.",
  ui_story_5076_50760900_69_dialog_content = "Kami juga akan membantu.",
  ui_story_5076_50760900_70_dialog_content = "Baiklah, tetapi tetap waspada. Mungkin masih ada Eclipsite yang bersembunyi di area ini.",
  ui_story_5076_50760900_71_dialog_content = "Kamu juga harus hati-hati!",
  ui_story_5076_50760900_72_dialog_content = "Aku akan membawa pedangku dan menjaga tempat ini ketika malam tiba. Kita tidak bisa membiarkan tragedi lain terjadi di tempat ini, dan aku tidak akan membiarkan para Eclipsite berbuat sesuka hati lagi...",
  ui_story_5076_50760900_73_dialog_content = "<color=#e8d9bb>Berkat usaha bersama pahlawan dan para pembantunya yang rajin, kuil tersebut cepat diperbaiki. Namun—</color>",
  ui_story_5076_50760900_74_dialog_content = "Ada apa ini?",
  ui_story_5076_50760900_75_dialog_content = "Aku tidak pernah meninggalkan kota sama sekali... Eclipsite jenis apa yang mampu menghindari deteksiku seperti ini?",
  ui_story_5076_50760900_76_dialog_content = "Terus menyusup ke kota tepat di depan hidungku... Penduduk kota dalam bahaya...",
  ui_story_5076_50760900_77_dialog_content = "Aku tidak terlalu khawatir tentang itu. Mungkin Eclipsite itu terlalu lemah untuk menarik perhatianmu. Di sini, aku akan mencoba merasakannya.",
  ui_story_5076_50760900_78_dialog_content = "Hah? Ada sesuatu yang aneh tentang reruntuhan ini...",
  ui_story_5076_50760900_79_dialog_content = "Hei Adras? Kamu bilang Marcela terlalu takut pada kuil sampai-sampai tidak berani mendekatinya, bukan?",
  ui_story_5076_50760900_80_dialog_content = "Ya, sepertinya begitu. Setiap kali saya datang ke kuil, dia menolak untuk ikut.",
  ui_story_5076_50760900_81_dialog_content = "Jadi itu alasannya...",
  ui_story_5076_50760900_82_dialog_content = "Guru Ludweiss, lihat!",
  ui_story_5076_50760900_83_dialog_content = "Ini sepertinya seperti bekas yang ditinggalkan oleh pedang...",
  ui_story_5076_50760900_84_dialog_content = "Sst—!!!",
  ui_story_5076_50760900_85_dialog_content = "Ada apa?",
  ui_story_5076_50760900_86_dialog_content = "I-Ini bukan apa-apa! Anak ini hanya ingin membantu Anda membangun kembali kuil, tapi dia masih terlalu muda.",
  ui_story_5076_50760900_87_dialog_content = "Terima kasih atas tawarannya, si kecil, tetapi kamu perlu kembali. Tempat ini tidak aman.",
  ui_story_5076_50760900_88_dialog_content = "Ayo, cepat pulang!",
  ui_story_5076_50760900_89_dialog_content = "Jadi, apakah kamu berhasil merasakan sesuatu, Ludweiss?",
  ui_story_5076_50760900_90_dialog_content = "Saya memang... Tapi itu sesuatu yang sangat kecil, seperti Eclipsite kecil yang nakal. Saya tidak berpikir itu menimbulkan ancaman yang besar.",
  ui_story_5076_50760900_91_dialog_content = "Meski begitu, kita tidak boleh mengambil risiko. Sepertinya aku akan membutuhkan bantuanmu untuk mempertahankan kuil ini, Ludweiss.",
  ui_story_5076_50760900_92_dialog_content = "Saya? Lalu... Saya akan mulai dengan mengambil shift malam ini. Jangan khawatir, milisi akan siaga jika terjadi apa-apa. Untuk saat ini... Pulanglah dan istirahatlah sebelum Marcela mulai khawatir...",
  ui_story_5076_50760900_93_dialog_content = "Ugh, malam yang... Lantai kuil bukanlah tempat yang paling empuk untuk tidur.",
  ui_story_5076_50760900_94_dialog_content = "Guru Ludweiss, Kakak Adras bilang dia akan mampir malam ini untuk menjaga. Oh, ngomong-ngomong, dia tampak cukup ceria.",
  ui_story_5076_50760900_95_dialog_content = "Sepertinya dia sudah cukup beristirahat, yang berarti kuil seharusnya tidak...",
  ui_story_5076_50760900_96_dialog_content = "Kenapa... Kenapa dia tiba-tiba begitu stabil? Apakah mungkin... Dia melihat Marcela lagi?",
  ui_story_5076_50760900_97_dialog_content = "Ludweiss, kamu pasti lelah setelah berjaga semalaman. Kamu bisa pulang sekarang.",
  ui_story_5076_50760900_98_dialog_content = "Jika aku pergi dan Adras mendekati kuil lagi...",
  ui_story_5076_50760900_99_dialog_content = "Jangan khawatir, Ludweiss. Kami percaya pada Adras.",
  ui_story_5076_50760900_100_dialog_content = "Kami tidak bisa membiarkan kamu tinggal di sini sepanjang waktu. Tidak apa-apa; kami berhutang terlalu banyak pada Adras, jadi kita semua akan bekerja sama dengan kamu...",
  ui_story_5076_50760900_101_dialog_content = "... Saya punya ide. Jika kuil ini berantakan lagi besok, saya butuh semua orang untuk ikut bermain dalam ini—",
  ui_story_5076_50760900_102_dialog_content = "Seperti yang diperkirakan, kuil itu rusak lagi.",
  ui_story_5076_50760900_103_dialog_content = "Ada apa dengan dunia...",
  ui_story_5076_50760900_104_dialog_content = "... Apakah kamu tidur dengan nyenyak di rumah, Adras?",
  ui_story_5076_50760900_105_dialog_content = "Tentu saja. Lagipula, Marcela kembali bersamaku... Tapi kenapa kau bertanya?",
  ui_story_5076_50760900_106_dialog_content = "Huh... Sepertinya kita kembali lagi ke titik awal...",
  ui_story_5076_50760900_107_dialog_content = "Namun, aku senang melihat bahwa pikiranmu kembali tenang.",
  ui_story_5076_50760900_108_dialog_content = "Apa maksudmu?",
  ui_story_5076_50760900_109_dialog_content = "Sebagai seorang Caelestite, aku hanya... Merasa sedikit tidak berdaya. Bagaimanapun, ini adalah pertama kalinya aku berharap sebuah <color=#FFB400>penyakit</color> tetap tidak disembuhkan...",
  ui_story_5076_50760900_110_dialog_content = "Adras, kita berhasil menangkap Eclipsite itu!",
  ui_story_5076_50760900_111_dialog_content = "Benarkah? Bagaimana kamu melakukannya?",
  ui_story_5076_50760900_112_dialog_content = "Itu adalah Eclipsite kecil, gesit dan cepat, hanya membuat masalah di jam-jam awal. Tapi jangan khawatir, dia terjebak dan tertangkap dalam perangkap kami!",
  ui_story_5076_50760900_113_dialog_content = "Kami sudah membasmi Eclipsite itu. Kamu bisa tenang sekarang.",
  ui_story_5076_50760900_114_dialog_content = "Ya, Kakak Adras, aku melihat Eclipsite kecil itu dihancurkan dengan mata kepala sendiri.",
  ui_story_5076_50760900_115_dialog_content = "Ehem—",
  ui_story_5076_50760900_116_dialog_content = "Oh! Ngomong-ngomong, kami baru saja lewat di tempatmu dan mendengar Marcela mungkin membutuhkanmu untuk sesuatu. Lebih baik kamu segera kembali.",
  ui_story_5076_50760900_117_dialog_content = "Mengerti. Saya akan kembali besok untuk membantu perbaikan.",
  ui_story_5076_50760900_118_dialog_content = "Tidak, serahkan saja pada kami! Kamu sudah melakukan banyak hal untuk kami, dan kami tidak ingin merepotkanmu lagi. Kembali dan habiskan lebih banyak waktu dengan Marcela.",
  ui_story_5076_50760900_119_dialog_content = "Sangat memalukan jika kita tidak bisa menyelesaikan hal sekecil ini dengan benar.",
  ui_story_5076_50760900_120_dialog_content = "Lakukan saja seperti kata mereka, Adras. Setelah beberapa hari—",
  ui_story_5076_50760900_121_dialog_content = "Guru Ludweiss! Ahem!",
  ui_story_5076_50760900_122_dialog_content = "—Lanjutkan saja menjaga jarakmu! Semuanya baik-baik saja sekarang, jadi cukup awasi saja dari jauh, oke?",
  ui_story_5076_50760900_123_dialog_content = "Kalian semua bertingkah aneh.",
  ui_story_5076_50760900_124_dialog_content = "Tapi jika Marcela membutuhkanku sekarang... Aku seharusnya pulang saja...",
  ui_story_5076_50760900_125_dialog_content = "Aku akan meninggalkan sisanya padamu, Ludweiss.",
  ui_story_5076_50760900_126_dialog_content = "Hah? Eh... Tentu! Serahkan saja semuanya padaku.",
  ui_story_5076_50761000_1_dialog_content = "Mereka sebenarnya berhasil membangun kembali kota ini.",
  ui_story_5076_50761000_2_dialog_content = "Melihat? Aku bilang Ludweiss tidak berlebihan dalam suratnya!",
  ui_story_5076_50761000_3_dialog_content = "Terakhir kali kita berkumpul di sini, kota ini hampir tidak berbeda dengan tumpukan puing.",
  ui_story_5076_50761000_4_dialog_content = "Apa yang mungkin telah mendorong orang-orang ini untuk membuat keajaiban seperti itu terjadi?",
  ui_story_5076_50761000_5_dialog_content = "Saya yakin itu adalah kepercayaan mereka pada pahlawan mereka.",
  ui_story_5076_50761000_6_dialog_content = "Mereka menatap kita lagi... Sembunyikan wajahku, Freya.",
  ui_story_5076_50761000_7_dialog_content = "Hai! Disini!",
  ui_story_5076_50761000_8_dialog_content = "Nona Ludweiss, siapa mereka? Bisakah Anda memperkenalkan mereka?",
  ui_story_5076_50761000_9_dialog_content = "Ini adalah teman-teman Adras, Prajurit Bintang legendaris kerajaan! Mereka datang untuk mengunjunginya.",
  ui_story_5076_50761000_10_dialog_content = "Wow, kami sangat terhormat memiliki mereka di sini! Adras dan Marcela pasti akan sangat gembira.",
  ui_story_5076_50761000_11_dialog_content = "Marcela? Tapi Kapten, bukankah kamu bilang dia... Saya mengerti. Kalian semua telah merawat Vice Kapten, bukan?",
  ui_story_5076_50761000_12_dialog_content = "Terima kasih.",
  ui_story_5076_50761000_13_dialog_content = "Hehe, tamu terhormat, apakah Anda ingin mencoba makanan khas setempat kami?",
  ui_story_5076_50761000_14_dialog_content = "Bisakah kamu juga membawa beberapa ke Adras? Dia... baiklah, dia dan Marcela juga perlu perawatan.",
  ui_story_5076_50761000_15_dialog_content = "Kalian semua…",
  ui_story_5076_50761000_16_dialog_content = "Hehe, tolong sampaikan salam kami kepadanya dan \"Marcela\".",
  ui_story_5076_50761000_17_dialog_content = "Senang bertemu dengan kalian semua lagi. Saya ingin menyambut kalian secara pribadi, tetapi Marcela menawarkan diri untuk melakukannya.",
  ui_story_5076_50761000_18_dialog_content = "Bagaimanapun, dia dan Ludweiss sudah berada di kota. Mereka berdua sekarang bekerja di panti asuhan.",
  ui_story_5076_50761000_19_dialog_content = "Jangan khawatir tentang itu. Marcela baru saja menunjukkan ladang kepada kami. Mereka sangat luas! Kamu pasti sangat sibuk mempersiapkan panen, bukan?",
  ui_story_5076_50761000_20_dialog_content = "Ya, tapi juga sangat damai... Saya tidak bisa meminta kehidupan yang lebih baik.",
  ui_story_5076_50761000_21_dialog_content = "Baiklah kalau begitu... Adras.",
  ui_story_5076_50761000_22_dialog_content = "Bagaimana kabar kalian semua?",
  ui_story_5076_50761000_23_dialog_content = "Baiklah, saya kira. Saya kembali menjadi pengawal istana, jadi saya bisa terus membela kerajaan.",
  ui_story_5076_50761000_24_dialog_content = "Karena kami tidak lagi dibutuhkan, saya telah berkelana di seluruh kerajaan... Tatapan dingin tak pernah berhenti, tapi saya baik-baik saja.",
  ui_story_5076_50761000_25_dialog_content = "Hutan ini jauh lebih damai, Friegson. Kenapa tidak bergabung denganku saja?",
  ui_story_5076_50761000_26_dialog_content = "... Aku tidak ingin api saya menghancurkan surga Anda.",
  ui_story_5076_50761000_27_dialog_content = "Kamu selalu bisa tinggal di sini, Friegson. Orang-orang di kota ini baik hati, dan mereka tidak akan menolakmu karena bekas lukamu.",
  ui_story_5076_50761000_28_dialog_content = "Terima kasih atas tawarannya, Vice Kapten. Saya bisa melihat bahwa mereka adalah orang-orang baik, tapi... Lebih baik jika saya tidak tinggal.",
  ui_story_5076_50761000_29_dialog_content = "Pertemuan seperti ini sulit ditemui, jadi mengapa tidak tinggal lebih lama dan ceritakan tentang hidupmu pada Adras? Kita bahkan bisa membuat api unggun, seperti dulu.",
  ui_story_5076_50761000_30_dialog_content = "Marcela benar. Kita harus membuat api unggun malam ini, seperti zaman dulu. Aku juga ingin duduk dan berbicara sedikit lebih banyak dengan semua orang.",
  ui_story_5076_50761000_31_dialog_content = "... Saya tidak melihat alasan mengapa tidak.",
  ui_story_5076_50761000_32_dialog_content = "Tidak masalah bagiku! Sudah terlalu lama sejak aku mencicipi masakan rumahan Vice Kapten! Aku yakin di sini juga banyak gudang anggur—",
  ui_story_5076_50761000_33_dialog_content = "Ayo Friegson, mari kita ambil satu barel minuman enak!",
  ui_story_5076_50761000_34_dialog_content = "Apakah itu baik-baik saja, Vice Kapten?",
  ui_story_5076_50761000_35_dialog_content = "Tentu saja. Marcela bisa menunjukkan di mana tempatnya.",
  ui_story_5076_50761000_36_dialog_content = "Namun…",
  ui_story_5076_50761000_37_dialog_content = "Ruang penyimpanan anggur cukup mudah ditemukan. Pintu masuknya ada di gudang di belakang rumah.",
  ui_story_5076_50761000_38_dialog_content = "Ayo ambil beberapa tong lagi dan buat pesta ini semakin meriah! Sekarang berhenti bermalas-malasan dan bantu kami, Cynthia!",
  ui_story_5076_50761000_39_dialog_content = "Tapi, aku harus mematuhi etika yang benar saat...",
  ui_story_5076_50761000_40_dialog_content = "Oh, lewati saja dan bantu kami!",
  ui_story_5076_50761000_41_dialog_content = "Kamu baik-baik saja akhir-akhir ini, Kapten?",
  ui_story_5076_50761000_42_dialog_content = "Otoritas Lucius melampaui statusnya sebagai Imam Besar. Dia cukup kuat untuk melawan Elder Council sekarang... Dan keluargaku menginginkan aku berdiri di sisi mereka.",
  ui_story_5076_50761000_43_dialog_content = "Tapi, Silent Hunters bukanlah pembunuh bayaran. Sekarang bahwa kerajaan sudah aman dari Eclipsite, kita tidak memiliki alasan untuk terlibat dalam urusan ini.",
  ui_story_5076_50761000_44_dialog_content = "Aku hanya ingin menghabiskan waktu bersama semua orang, Adras. Persis seperti ini.",
  ui_story_5076_50761000_45_dialog_content = "... Aku mengerti. Semoga kamu menemukan ketenangan di sini, meski hanya untuk sementara waktu.",
  ui_story_5076_50761000_46_dialog_content = "Ayo kita siapkan makan malam untuk malam ini, Marcela.",
  ui_story_5076_50761000_47_dialog_content = "Menurutmu, apakah dia bahagia, Ludweiss?",
  ui_story_5076_50761000_48_dialog_content = "Sejauh yang bisa saya katakan, dia pasti bahagia sekarang...",
  ui_story_5076_50761000_49_dialog_content = "Kami telah melanjutkan dengan kebohongan ini, tetapi jika—",
  ui_story_5076_50761000_50_dialog_content = "Marcela pernah mengatakan bahwa Adras bersedia berjuang untuk rakyatnya seumur hidupnya.",
  ui_story_5076_50761000_51_dialog_content = "Dan orang-orang di sini melakukan segala yang mereka bisa untuk melindungi sedikit kedamaian dan kebahagiaan terakhir pahlawan mereka.",
  ui_story_5076_50761000_52_dialog_content = "Ini bukan hanya bohong, Kapten Achilles. Setidaknya bukan dari cara pandang saya.",
  ui_story_5076_50761000_53_dialog_content = "Mereka yang bersembunyi dari rasa sakit mereka akhirnya akan terbangun dari mimpi yang paling hati-hati dibuat. Ketika itu terjadi... Akankah dia menderita lebih banyak lagi? Atau akankah dia bahagia dengan rasa kebahagiaan yang sebentar itu?",
  ui_story_5076_50761000_54_dialog_content = "Dia makin baik.",
  ui_story_5076_50761000_55_dialog_content = "Aku tidak merasakan penyebaran korupsi dalam dirinya lagi. Jika ada, dia malah menjadi lebih berenergi.",
  ui_story_5076_50761000_56_dialog_content = "Jadi jika suatu hari dia bangun dari mimpinya... Aku akan ada di sana untuk menanggung segala kemarahan yang mungkin dia miliki.",
  ui_story_5076_50761000_57_dialog_content = "Aku adalah kapten mereka, Ludweiss. Jika hari itu tiba, aku yang akan menanggung tanggung jawab atas segalanya.",
  ui_story_5076_50761000_58_dialog_content = "Ini mengingatkanku; saya dengar bahwa panti asuhan sekarang sepenuhnya mampu menjalankan dirinya sendiri. Apakah Anda berencana untuk kembali berkelana segera?",
  ui_story_5076_50761000_59_dialog_content = "Nah, saya selalu ingin melihat bintang jatuh di utara!",
  ui_story_5076_50761000_60_dialog_content = "Bintang jatuh? Bukan aurora?",
  ui_story_5076_50761000_61_dialog_content = "Lagi pula, kamu bebas melakukan apa yang kamu inginkan. Setidaknya, kamu bisa melarikan diri dari perangkapmu... Dan melihat dunia di tempat kami.",
  ui_story_5076_50761000_62_dialog_content = "Aku akan, dan kau akan menjadi orang pertama yang membaca tentang semua yang kulihat di sana.",
  ui_story_5076_50761000_63_dialog_content = "Glek, glek, glek! Ayo, kamu pasti bisa!",
  ui_story_5076_50761000_64_dialog_content = "Gluk, gluk, gluk—",
  ui_story_5076_50761000_65_dialog_content = "A-Aku menyerah... Aku tidak bisa minum lagi.",
  ui_story_5076_50761000_66_dialog_content = "Bangun, Friegson! Bagaimana bisa kau kalah lagi dari Cynthia?!",
  ui_story_5076_50761000_67_dialog_content = "Satu kapten... Dua kapten...",
  ui_story_5076_50761000_68_dialog_content = "Oh, dia benar-benar mabuk berat sekarang.",
  ui_story_5076_50761000_69_dialog_content = "Apakah kamu berikutnya, Freya?",
  ui_story_5076_50761000_70_dialog_content = "A-Ahem, saya ingin Anda tahu bahwa saya adalah seorang wanita bangsawan yang sangat berbudaya! Bagaimana mungkin saya bisa terlibat dalam perilaku seperti ini?",
  ui_story_5076_50761000_71_dialog_content = "... Pengecut.",
  ui_story_5076_50761000_72_dialog_content = "Bisakah kamu membantu Friegson ke kamarnya, Marcela?",
  ui_story_5076_50761000_73_dialog_content = "... Aku ikut senang, Kapten Vice.",
  ui_story_5076_50761000_74_dialog_content = "Kamu melakukannya jauh lebih baik daripada kami semua... Tidak ada yang memperlakukanmu seperti monster, atau memaksa kamu melakukan pekerjaan kotor mereka.",
  ui_story_5076_50761000_75_dialog_content = "Kamu mabuk, Friegson. Kamu harus pergi berbaring.",
  ui_story_5076_50761000_76_dialog_content = "Mengapa semua orang di kerajaan menatapku seperti itu? Bukan seolah-olah aku ingin berakhir seperti ini!",
  ui_story_5076_50761000_77_dialog_content = "Aku tidak melakukan apa-apa yang salah! Aku hanya ingin melindungi mereka...",
  ui_story_5076_50761000_78_dialog_content = "Bawa dia kembali ke tempat tidur, Freya.",
  ui_story_5076_50761000_79_dialog_content = "Tapi Kapten... Dia menangis.",
  ui_story_5076_50761000_80_dialog_content = "Dia lelah. Saya pikir dia perlu melepaskan ini.",
  ui_story_5076_50761000_81_dialog_content = "Aku tidak melakukan apa-apa! Aku pembunuh monster, bukan monster!",
  ui_story_5076_50761000_82_dialog_content = "Aku hanya ingin membantu pria tua itu menemukan jalan! Kenapa dia langsung mencacimaki aku begitu melihatku?!",
  ui_story_5076_50761000_83_dialog_content = "Dia jelas takut padaku, tapi itu tidak menghentikannya! Kenapa? Apakah karena dia tahu aku tidak akan menyakitinya? Siapa yang tidak masuk akal di sini—",
  ui_story_5076_50761000_84_dialog_content = "...",
  ui_story_5076_50761000_85_dialog_content = "Jangan menangis, Friegson. Itu sangat tidak cocok untukmu.",
  ui_story_5076_50761000_86_dialog_content = "Vice Kapten? Aku... Aku benar-benar senang untukmu. Setidaknya kamu bisa menjadi pahlawan. Tapi mengapa kerajaan melihat kita yang lain sebagai monster...?",
  ui_story_5076_50761000_87_dialog_content = "Mengapa, Vice Kapten...? Apa yang harus kita lakukan...?",
  ui_story_5076_50761000_88_dialog_content = "Cinta di hatiku hampir hilang sekarang... Apa yang harus aku lakukan...?",
  ui_story_5076_50761000_89_dialog_content = "Orang-orang di sini masih bisa melihatmu sebagai pahlawan yang selalu kamu jadi... Jadi, mengapa semua orang lain begitu bodoh?",
  ui_story_5076_50761000_90_dialog_content = "Friegson...",
  ui_story_5076_50761000_91_dialog_content = "Jangan terlalu khawatir tentang dia, Adras. Dia telah menyimpan perasaan ini sendirian terlalu lama, dan akhirnya dia menemukan seseorang untuk berbagi perasaan tersebut.",
  ui_story_5076_50761000_92_dialog_content = "... Minumlah, Vice Kapten! Mari... Mabuk bersama...!",
  ui_story_5076_50761000_93_dialog_content = "Selamat, Friegson. Cangkir ini untukmu.",
  ui_story_5076_50761000_94_dialog_content = "Ayo, Cynthia! Kapten Vice sepertinya butuh tantangan yang seru!",
  ui_story_5076_50761000_95_dialog_content = "Kamu harus tahu bahwa saya sangat percaya diri.",
  ui_story_5076_50761000_96_dialog_content = "Yah, aku bukan, jadi sepertinya aku pasti akan kalah.",
  ui_story_5076_50761000_97_dialog_content = "Gluk, gluk, gluk—",
  ui_story_5076_50761000_98_dialog_content = "Teruskan mereka datang! Aku akan tunjukkan keberanian Legion Northwind!",
  ui_story_5076_50761000_99_dialog_content = "Marcela... Di mana kamu... Aku tidak bisa mengejarmu.",
  ui_story_5076_50761000_100_dialog_content = "Lagu? Tapi kita tidak sedang bekerja... Ah, sepertinya satu lagu tidak akan merugikan.",
  ui_story_5076_50761000_101_dialog_content = "\"Pegang tanganku—\"",
  ui_story_5076_50761000_102_dialog_content = "Kapten Vice pasti benar-benar mabuk... Saya rasa saya belum pernah mendengar lagu yang begitu unik sebelumnya...",
  ui_story_5076_50761000_103_dialog_content = "Jangan khawatir, nyanyiannya tidak jauh lebih baik saat dia sadar.",
  ui_story_5076_50761000_104_dialog_content = "\"Bawalah aku pulang—\"",
  ui_story_5076_50761000_105_dialog_content = "Apakah itu lagu Legiun Northwind? Itu sangat... penuh emosi.",
  ui_story_5076_50761000_106_dialog_content = "Terima kasih…",
  ui_story_5076_50761000_107_dialog_content = "Aku bertanya-tanya apakah kita akan pernah memiliki rumah?",
  ui_story_5076_50761000_108_dialog_content = "Itulah caranya, Vice Kapten. Masalah kita tidak bisa mengganggu kita jika kita terlalu mabuk untuk mengingatnya, bukan?",
  ui_story_5076_50761000_109_dialog_content = "Ini bagus...",
  ui_story_5076_50761000_110_dialog_content = "Aku rasa aku belum pernah melihat Adras sebahagia ini.",
  ui_story_5076_50761000_111_dialog_content = "Ini benar-benar baik-baik saja, Kapten?",
  ui_story_5076_50761000_112_dialog_content = "Sepertinya Friegson hampir mencapai batasnya, dan meskipun Freya tampak optimis, saya yakin dia juga...",
  ui_story_5076_50761000_113_dialog_content = "Dunia ini tidak memerlukan kita lagi. Jika ada, keberadaan kita justru terlalu mengancam perdamaian.",
  ui_story_5076_50761000_114_dialog_content = "Saya sudah bilang sebelumnya, bukan? Kami tidak lebih dari senjata yang bisa digunakan kerajaan. Lebih cepat atau lambat, mereka akan menggunakan kita lagi.",
  ui_story_5076_50761000_115_dialog_content = "Bahkan sekarang, rasanya seperti hati nuraniku sedang terkikis.",
  ui_story_5076_50761000_116_dialog_content = "Berapa lama lagi sebelum salah satu dari kita membuat kesalahan?",
  ui_story_5076_50761000_117_dialog_content = "Cukup, Cynthia. Tidak ada yang lebih berharga bagi kita daripada rasionalitas, tapi itu tidak membuat kita menjadi tidak berperasaan.",
  ui_story_5076_50761000_118_dialog_content = "Tapi jika kita tidak segera ditangani, suatu hari nanti, kita akan—",
  ui_story_5076_50761000_119_dialog_content = "Ini bukan jenis hal yang seharusnya kamu pikirkan! Kami bukan seperti monster dalam dongeng!",
  ui_story_5076_50761000_120_dialog_content = "Berhenti bertengkar, kalian berdua! Jarang bagi kita semua untuk menghabiskan waktu bersama seperti ini...",
  ui_story_5076_50761000_121_dialog_content = "Aku menolak untuk menyakiti teman-temanku dengan cara apapun.",
  ui_story_5076_50761000_122_dialog_content = "Mudah saja mengatakan itu ketika kita masih punya pilihan... Tapi apa yang terjadi ketika kita tidak punya pilihan?",
  ui_story_5076_50761000_123_dialog_content = "Kau yakin tidak akan menyesalinya?",
  ui_story_5076_50761000_124_dialog_content = "Selama aku tetap menjadi Achilles, aku bersumpah atas namaku bahwa aku tidak akan pernah mengangkat pedangku terhadap rekan-rekanku.",
  ui_story_5076_50761000_125_dialog_content = "Saya hanya bergabung dengan militer untuk mencegah api perang mencapai hutan...",
  ui_story_5076_50761000_126_dialog_content = "Saat saya menginjakkan kaki di luar rumah, saya menyadari bahwa dunia ini hanyalah hutan yang lebih besar.",
  ui_story_5076_50761000_127_dialog_content = "Aku berharap bisa meminta maaf padamu dengan sepenuh jiwa...",
  ui_story_5076_50761000_128_dialog_content = "Tapi sayangnya, saya tidak yakin apakah tubuh ini masih memiliki jiwa atau tidak.",
  ui_story_5076_50761000_129_dialog_content = "Bagaimanapun, aku minta maaf.",
  ui_story_5076_50761101_1_dialog_content = "Regal, ada perintah baru untukmu.",
  ui_story_5076_50761101_2_dialog_content = "Frostfire, rekan Silent Huntermu, telah menjadi gila di kota lain.",
  ui_story_5076_50761101_3_dialog_content = "Apa?!",
  ui_story_5076_50761101_4_dialog_content = "Gunakan sihir airmu untuk menghentikannya.",
  ui_story_5076_50761101_5_dialog_content = "Jika perlu... tanpa belas kasihan, kalahkan dia.",
  ui_story_5076_50761101_6_dialog_content = "Friegson... Kenapa...",
  ui_story_5076_50761101_7_dialog_content = "Ini adalah-",
  ui_story_5076_50761101_8_dialog_content = "Seluruh kota... Apakah sudah terbakar hingga rata dengan tanah?",
  ui_story_5076_50761101_9_dialog_content = "Penjaga, laporkan situasinya! Ada yang selamat di kota?",
  ui_story_5076_50761101_10_dialog_content = "Laporkan! Tak ada yang selamat di kota, dan dia masih kehilangan kendali!",
  ui_story_5076_50761101_11_dialog_content = "Cepat! Kerahkan \"monster\" baru dan biarkan mereka bertarung, atau tempat lain mungkin dalam bahaya!",
  ui_story_5076_50761101_12_dialog_content = "Friegson... Friegson...",
  ui_story_5076_50761101_13_dialog_content = "Vice Kapten...? Tolong... Bantu aku...",
  ui_story_5076_50761101_14_dialog_content = "Tidak... Kamu—Seorang Eclipsite!",
  ui_story_5076_50761101_15_dialog_content = "<size=45>Eclipsite!!!</size>",
  ui_story_5076_50761101_16_dialog_content = "<size=45>Mati!!!</size>",
  ui_story_5076_50761102_1_dialog_content = "Aaaaaaah—Matilah, Eclipsite!!!",
  ui_story_5076_50761102_2_dialog_content = "Berhenti, kalian berdua!",
  ui_story_5076_50761102_3_dialog_content = "Aku tidak bisa—aku harus membakar semuanya—",
  ui_story_5076_50761102_4_dialog_content = "Sadarkan diri kalian berdua! Ludweiss, gunakan kekuatanmu untuk membuat mereka sadar!",
  ui_story_5076_50761102_5_dialog_content = "Tolong bangun—",
  ui_story_5076_50761102_6_dialog_content = "C... Kapten?",
  ui_story_5076_50761102_7_dialog_content = "Ludweiss?",
  ui_story_5076_50761102_8_dialog_content = "Akhirnya kalian kembali seperti semula... Kenapa kalian bertarung seperti ini?!",
  ui_story_5076_50761102_9_dialog_content = "Kapten, aku...",
  ui_story_5076_50761102_10_dialog_content = "Belenggu? Kenapa ini ada padaku...?",
  ui_story_5076_50761102_11_dialog_content = "Lihat sekeliling, Friegson. Rantai ini ada untuk melindungimu.",
  ui_story_5076_50761102_12_dialog_content = "Monster... Kenapa masih membiarkan makhluk berbahaya ini berkeliaran...",
  ui_story_5076_50761102_13_dialog_content = "Kamu bersumpah untuk melindungi tempat ini, tetapi kamu membakarnya bersama dengan Eclipsite yang menyerangnya.",
  ui_story_5076_50761102_14_dialog_content = "Bagaimana ini terjadi?",
  ui_story_5076_50761102_15_dialog_content = "Seseorang... Seseorang memindahkan para penjaga ke pos lain, dan membiarkan segerombolan Eclipsite menyusup ke kota dan membunuh tak terhitung jumlah orang yang tidak bersalah...",
  ui_story_5076_50761102_16_dialog_content = "Aku tak bisa percaya ada orang yang bisa melakukan sesuatu yang begitu mengerikan.",
  ui_story_5076_50761102_17_dialog_content = "Jadi, kamu tahu bahwa kamu dijebak sejak awal?",
  ui_story_5076_50761102_18_dialog_content = "Ya, tapi... Aku tidak bisa mengendalikan diri lagi.",
  ui_story_5076_50761102_19_dialog_content = "Seseorang mengorbankan semua nyawa yang tak bersalah itu hanya untuk menghancurkan hatiku menjadi berkeping-keping...",
  ui_story_5076_50761102_20_dialog_content = "Saat aku menyadari hal itu, kegelapan menyelimuti penglihatanku. Aku kalah... Dan sebelum aku menyadarinya, aku kehilangan semua jejak dari siapa diriku dulu.",
  ui_story_5076_50761102_21_dialog_content = "Aku bukan pahlawan. Tidak lagi.",
  ui_story_5076_50761102_22_dialog_content = "Friegson...",
  ui_story_5076_50761102_23_dialog_content = "Kamu harus tegakkan kepala, Friegson. Jangan menyerah.",
  ui_story_5076_50761102_24_dialog_content = "Kami akan selalu di sisi Anda.",
  ui_story_5076_50761102_25_dialog_content = "Tapi apa yang harus saya lakukan sekarang, Kapten? Apakah saya...",
  ui_story_5076_50761102_26_dialog_content = "Aku akan mengawalmu ke ibu kota kerajaan dan menceritakan kepada raja kebenaran tentang apa yang terjadi di sini. Kami akan meminta pengadilan yang adil untukmu.",
  ui_story_5076_50761102_27_dialog_content = "Apa? Kamu tidak bisa melakukan itu, Kapten!",
  ui_story_5076_50761102_28_dialog_content = "Kamu sendiri yang mendengarnya: Friegson telah difitnah, dan kemungkinan besar orang yang bertanggung jawab adalah bagian dari pengadilan kerajaan! Mengirimnya ke sana sama saja dengan mengirimnya ke ajalnya!",
  ui_story_5076_50761102_29_dialog_content = "Benar, pasti itu Lucius! Dia selalu melawan kita, dan sekarang dia sedang menghabisi kita satu per satu...",
  ui_story_5076_50761102_30_dialog_content = "Tidak masalah lagi, Vice Kapten. Toh, bukan seperti aku punya rumah untuk kembali, anyway...",
  ui_story_5076_50761102_31_dialog_content = "Tidak, ini tidak adil bagi kamu! Tangan Lucius sudah di leher teman kita, Kapten; berapa lama lagi Anda akan membiarkan ini berlanjut?",
  ui_story_5076_50761102_32_dialog_content = "Kita harus... menghentikan pria itu...",
  ui_story_5076_50761102_33_dialog_content = "Tenang, Adras! Freya dan Cynthia masih dalam pengawasan!",
  ui_story_5076_50761102_34_dialog_content = "Kamu juga harus memikirkan seluruh kota dan penduduknya... Sekarang bukan saatnya untuk membuat keputusan sembrono.",
  ui_story_5076_50761102_35_dialog_content = "Kita harus bekerja sama dan menemukan cara untuk membuktikan bahwa Friegson tidak bersalah, mengerti?",
  ui_story_5076_50761102_36_dialog_content = "Kapten... Kenapa kamu tidak mengatakan apa-apa? Dulu kamu melindungi bahkan bawahan terendahmu, tapi sekarang kamu bahkan tidak mau mengangkat jari untuk membela salah satu teman terdekatmu?",
  ui_story_5076_50761102_37_dialog_content = "Kapten... Kenapa...",
  ui_story_5076_50761102_38_dialog_content = "Adras, Friegson... Maafkan aku.",
  ui_story_5076_50761102_39_dialog_content = "Biaya untuk memulihkan kedamaian di kerajaan kita terlalu mahal. Saya tidak bisa membiarkannya jatuh ke dalam kekacauan sekali lagi.",
  ui_story_5076_50761102_40_dialog_content = "Jika aku memilih untuk bertahan, Dewan Penatua dan Lucius akan memulai perang lainnya. Kamu tidak ingin melihat pemberontakan berdarah lainnya terjadi, bukan?",
  ui_story_5076_50761102_41_dialog_content = "Jadi tolong... Maafkan aku.",
  ui_story_5076_50761102_42_dialog_content = "Seberat apapun rasanya untuk berkompromi, yang bisa kita lakukan sekarang hanyalah menahannya—",
  ui_story_5076_50761200_1_dialog_content = "<color=#e8d9bb>Kehilangan kendali sang pahlawan dengan cepat menimbulkan ketakutan di seluruh kerajaan, dengan keluhan membanjiri ibu kota dari semua penjuru.</color>",
  ui_story_5076_50761200_2_dialog_content = "<color=#e8d9bb>Frostfire, orang yang memicu semuanya, kini dibelenggu dan dipaksa untuk \"terus bertarung\" di bawah pengawasan kerajaan.</color>",
  ui_story_5076_50761200_3_dialog_content = "<color=#e8d9bb>Sisanya dari Silent Hunters dibagi dan ditempatkan untuk menjaga kota-kota perbatasan. Bahkan Caelestites terdekat pun berada dalam tahanan rumah.</color>",
  ui_story_5076_50761200_4_dialog_content = "Pergilah! Jauhkan barang-barang menyeramkan itu dari tempat kami.",
  ui_story_5076_50761200_5_dialog_content = "Aku hanya seorang prajurit dan ini adalah senjataku. Jika kamu menolak berbisnis denganku, setidaknya biarkan istriku masuk.",
  ui_story_5076_50761200_6_dialog_content = "Istri...? Dasar gila. Pergi sana!",
  ui_story_5076_50761200_7_dialog_content = "Anda akan lebih bijaksana jika mengubah nada bicara dan menarik kembali komentar kasar Anda.",
  ui_story_5076_50761200_8_dialog_content = "Biarkan saja, Adras... Kamu masih pelindung mereka, jadi bertengkar dengan mereka tentang hal-hal ini tidak ada gunanya.",
  ui_story_5076_50761200_9_dialog_content = "... Bagus.",
  ui_story_5076_50761200_10_dialog_content = "Ternyata rumor itu benar. Silent Hunters memang semua gila...",
  ui_story_5076_50761200_11_dialog_content = "Aku tidak suka di sini, Marcela.",
  ui_story_5076_50761200_12_dialog_content = "Tidak apa-apa, Adras. Mereka hanya tidak mengerti kamu, itu saja.",
  ui_story_5076_50761200_13_dialog_content = "Aku yakin mereka akan memperlakukanmu lebih baik jika mereka hanya memiliki kesempatan untuk mengenal kamu—",
  ui_story_5076_50761200_14_dialog_content = "Lihat, pria itu ada lagi...",
  ui_story_5076_50761200_15_dialog_content = "Ih, sepertinya dia bisa kehilangan kendali kapan saja. Siapa tahu kapan dia mungkin...",
  ui_story_5076_50761200_16_dialog_content = "Bagaimana keadaan semua orang hari ini?",
  ui_story_5076_50761200_17_dialog_content = "Enyah! Bergerak!",
  ui_story_5076_50761200_18_dialog_content = "...",
  ui_story_5076_50761200_19_dialog_content = "Jangan merasa putus asa. Mungkin kamu akan bertemu dengan orang yang lebih baik lain kali?",
  ui_story_5076_50761200_20_dialog_content = "<color=#e8d9bb>Megang erat harapan yang samar, pahlawan itu mendambakan orang lain datang untuk menyelamatkan.</color>",
  ui_story_5076_50761200_21_dialog_content = "Lihat, ini datang \"Eclipsite.\"",
  ui_story_5076_50761200_22_dialog_content = "Sebuah Eclipsite? Di mana?",
  ui_story_5076_50761200_23_dialog_content = "Berlindunglah di belakangku, anak-anak! Kamu juga, Marcela!",
  ui_story_5076_50761200_24_dialog_content = "Aku akan mengurus Eclipsite—",
  ui_story_5076_50761200_25_dialog_content = "Ha! Bodoh!",
  ui_story_5076_50761200_26_dialog_content = "Seorang bodoh seperti Eclipsite! Hahaha!",
  ui_story_5076_50761200_27_dialog_content = "Anak-anak itu... Apakah mereka mulai berpikir seperti orang dewasa?",
  ui_story_5076_50761200_28_dialog_content = "Apa yang telah aku lakukan salah?",
  ui_story_5076_50761200_29_dialog_content = "<color=#e8d9bb>Situasi berlanjut hari demi hari...</color>",
  ui_story_5076_50761200_30_dialog_content = "Mengapa semua orang di sini takut padaku...?",
  ui_story_5076_50761200_31_dialog_content = "Apakah itu karena bekas luka terkutuk ini...?",
  ui_story_5076_50761200_32_dialog_content = "Aku bukan Eclipsite! Aku tahu aku bukan—",
  ui_story_5076_50761200_33_dialog_content = "Lihat itu? Orang itu bisa menjadi gila tanpa alasan.",
  ui_story_5076_50761200_34_dialog_content = "Mendengar tentang Silent Hunter yang seperti itu, membakar seluruh kota di akhir cerita.",
  ui_story_5076_50761200_35_dialog_content = "Tidak tahu mengapa Yang Mulia Raja masih menyimpan mereka; dia terlalu baik hati.",
  ui_story_5076_50761200_36_dialog_content = "<color=#e8d9bb>Dia terus menerima serangan dari belakang, di mana dia sama sekali tidak bisa bertahan.</color>",
  ui_story_5076_50761200_37_dialog_content = "Kalau menurutku, mereka semua harus dieksekusi. Siapa tahu apa yang mereka pernah lakukan?",
  ui_story_5076_50761200_38_dialog_content = "Siapa \"Marcela\"? Ketika pria itu memanggil nama itu, dia tampak sangat sedih...",
  ui_story_5076_50761200_39_dialog_content = "Mungkin itu seseorang yang pernah dibunuhnya, jiwa yang malang. Mendengar beberapa Eclipsite mengerti bahasa Universese, dan mereka menggunakan kebohongan untuk menipu orang lain agar bisa mendekati mereka.",
  ui_story_5076_50761200_40_dialog_content = "Benarkah itu? Terlalu menakutkan, bukan?",
  ui_story_5076_50761200_41_dialog_content = "<color=#e8d9bb>Bintang-bintang yang dulu terang kini cepat meredup.</color>",
  ui_story_5076_50761200_42_dialog_content = "Marcela... Apakah ini yang terjadi pada Friegson dan yang lainnya? Apakah ini jenis kehidupan yang mereka jalani?",
  ui_story_5076_50761200_43_dialog_content = "Dulu, aku tidak tahu bagaimana perasaannya.",
  ui_story_5076_50761200_44_dialog_content = "Jika saat itu aku mengerti, aku bisa ada untuknya. Apakah segalanya akan berakhir berbeda untuknya?",
  ui_story_5076_50761200_45_dialog_content = "<color=#e8d9bb>Kemudian, hati dari bintang-bintang itu dirampas dan ditarik ke dalam jurang.</color>",
  ui_story_5076_50761200_46_dialog_content = "Oh, Marcela? Akhirnya saya mendapatkan surat dari Ludweiss hari ini.",
  ui_story_5076_50761200_47_dialog_content = "Sepertinya akhirnya dia mendapatkan kesempatan untuk melepaskan diri, dan dia akan datang mengunjungi kita sebentar lagi. Meski begitu, saya ingin dia mengunjungi tetangga lama-nya terlebih dahulu—",
  ui_story_5076_50761200_48_dialog_content = "Hmm? Kamu lagi apa?",
  ui_story_5076_50761200_49_dialog_content = "\"Mar—ce—la—\"",
  ui_story_5076_50761200_50_dialog_content = "Ada respon! Oh, tidak, dia melihat ke sini! LARI!",
  ui_story_5076_50761200_51_dialog_content = "Apa... Apa sebenarnya aku bagi mereka?",
  ui_story_5076_50761200_52_dialog_content = "Dan kenapa kamu berhenti berbisik di telingaku? Marcela...",
  ui_story_5076_50761200_53_dialog_content = "<color=#e8d9bb>Ketika bintang-bintang melintas di langit dan jatuh ke bumi, akankah mereka akhirnya kembali ke kedamaian yang mereka layak? Atau ini hanya jatuh dari surga yang jauh?</color>",
  ui_story_5076_50761200_54_dialog_content = "<color=#e8d9bb>Bintang-bintang yang pernah bersinar pada khalayak ramai, apakah mereka akan pernah menemukan tempat mereka?</color>",
  ui_story_5076_50761200_55_dialog_content = "<color=#e8d9bb>Jika masa depan hanya tersisa keputusasaan ketika mimpi indah hancur... apakah pertarungan masih memiliki arti pada titik itu?</color>",
  ui_story_5076_50761200_56_dialog_content = "Menjauhlah dariku, anak nakal! Berhenti mengikutiku!",
  ui_story_5076_50761200_57_dialog_content = "\"Marcela—Marcela—\"",
  ui_story_5076_50761200_58_dialog_content = "Sepertinya dia akan menangis.",
  ui_story_5076_50761200_59_dialog_content = "Cepat, ayo pergi! \"Eclipsite\" itu akan kehilangan kesabarannya.",
  ui_story_5076_50761200_60_dialog_content = "Mampus... Mampus... Mampus... Mampus—",
  ui_story_5076_50761200_61_dialog_content = "<size=45>Eclipsite!!!</size>",
  ui_story_5076_50761200_62_dialog_content = "Saya tidak melihatnya... Di mana Eclipsite-nya?",
  ui_story_5076_50761200_63_dialog_content = "Dan di mana kamu, Marcela?",
  ui_story_5076_50761200_64_dialog_content = "Tolong, panggil saja aku seperti dulu...",
  ui_story_5076_50761300_1_dialog_content = "<color=#e8d9bb>Kekuatan kerajaan seharusnya seimbang dengan halus, tetapi sikap gigih Raja akhirnya menghancurkan Dewan Tua yang dia benci.</color>",
  ui_story_5076_50761300_2_dialog_content = "<color=#e8d9bb>Sejak penggulingan Prime Elder, High Priest Lucius telah memulai pembersihannya.</color>",
  ui_story_5076_50761300_3_dialog_content = "<color=#e8d9bb>Apakah tindakan Imam Besar benar-benar didorong oleh motif egoisnya? Atau apakah dia selalu menjadi juru bicara untuk orang lain?</color>",
  ui_story_5076_50761300_4_dialog_content = "Bukalah, Adras.",
  ui_story_5076_50761300_5_dialog_content = "Siapa kalian? Tunggu... Kapten?",
  ui_story_5076_50761300_6_dialog_content = "Ada apa? Apakah kamu sudah lupa wajah kami?",
  ui_story_5076_50761300_7_dialog_content = "Itu keras, Vice Kapten. Terlebih karena kami datang untuk mencari perlindungan di sini bersamamu.",
  ui_story_5076_50761300_8_dialog_content = "Apa yang terjadi?",
  ui_story_5076_50761300_9_dialog_content = "Sebuah konspirasi pemberontak terungkap di dalam Dewan Tua. Di bawah perintah rahasia dari raja, Lucius ingin menggunakan Silent Hunters untuk menekannya.",
  ui_story_5076_50761300_10_dialog_content = "Tapi Friegson dan Freya menolak untuk patuh, dan akibatnya... Mereka ditangkap dan dipenjara.",
  ui_story_5076_50761300_11_dialog_content = "Saya menolak untuk melepaskan api saya pada orang-orang, meskipun itu berarti saya harus mati.",
  ui_story_5076_50761300_12_dialog_content = "Itulah saat Achilles melakukan penyelamatan berbahaya, dan membebaskan saya dari tahanan rumah.",
  ui_story_5076_50761300_13_dialog_content = "Tapi semua ini berkat Cynthia dan Ludweiss yang membuat kita bisa melarikan diri dari ibukota dengan selamat.",
  ui_story_5076_50761300_14_dialog_content = "Seruan untuk penangkapan mereka segera akan dilakukan. Aku ingin kamu mengawal mereka keluar dari kerajaan sebelum itu terjadi.",
  ui_story_5076_50761300_15_dialog_content = "Bagaimana denganmu?",
  ui_story_5076_50761300_16_dialog_content = "Aku bertanggung jawab penuh atas semua ini, itulah sebabnya aku akan kembali ke ibu kota dan menerima hukuman dari raja.",
  ui_story_5076_50761300_17_dialog_content = "Dia berpikir bahwa dengan menyerahkan diri, dia dapat mengamankan kebebasan kita.",
  ui_story_5076_50761300_18_dialog_content = "Apa? Apakah kamu kehilangan akal, Achilles?! Kita harus tetap bersama!",
  ui_story_5076_50761300_19_dialog_content = "Pria yang duduk di atas takhta itu dulunya adalah saudara seperjuanganku. Sebagai dua sisi dari formasi phalanx, dia telah menyelamatkan hidupku berkali-kali.",
  ui_story_5076_50761300_20_dialog_content = "Aku tidak pernah bisa membelakanginya.",
  ui_story_5076_50761300_21_dialog_content = "Yakinlah, aku akan menemukan cara untuk berbicara dengan raja. Masih ada harapan untuk hasil yang lebih baik.",
  ui_story_5076_50761300_22_dialog_content = "Tidak ada yang bisa mengubah pikiran Kapten setelah dia memutuskan untuk melakukan sesuatu. Berhenti saja, Vice Komandan.",
  ui_story_5076_50761300_23_dialog_content = "Setidaknya biarkan kita menghabiskan waktu bersama sebelum berpisah lagi.",
  ui_story_5076_50761300_24_dialog_content = "Dengan keadaan seperti sekarang ini, apakah itu masih penting?",
  ui_story_5076_50761300_25_dialog_content = "Tidak ada yang baik akan datang dari kita berkumpul seperti ini.",
  ui_story_5076_50761300_26_dialog_content = "Jangan bicara seperti itu, Friegson. Achilles berjuang keras untuk menyelamatkan semua orang dan membawa kita ke sini.",
  ui_story_5076_50761300_27_dialog_content = "Maaf.",
  ui_story_5076_50761300_28_dialog_content = "Saya pikir itu ide yang bagus! Sudah terlalu lama sejak saya minum Vice wine Kapten, dan hanya memikirkannya saja benar-benar membawa saya kembali.",
  ui_story_5076_50761300_29_dialog_content = "Lalu tunggu saja aku di sini. Aku akan kembali dalam sebentar.",
  ui_story_5076_50761300_30_dialog_content = "Kita tidak seharusnya hanya duduk-duduk dan menunggu minuman keras. Mari kita siapkan sesuatu untuk dimakan sementara waktu!",
  ui_story_5076_50761300_31_dialog_content = "Tempat ini pernah lebih baik. Apakah Vice Kapten selalu berantakan seperti ini?",
  ui_story_5076_50761300_32_dialog_content = "...Apakah ada yang memperhatikan sesuatu yang berbeda tentang kondisi pikiran Vice Kapten?",
  ui_story_5076_50761300_33_dialog_content = "Apa yang kamu bicarakan? Selain Kapten, dia selalu lebih baik daripada kita semua.",
  ui_story_5076_50761300_34_dialog_content = "Cinta yang murni dan kuat di hatinya telah menahan kerusakan di dirinya selama bertahun-tahun sekarang.",
  ui_story_5076_50761300_35_dialog_content = "Tapi Freya, aku bisa mencium sesuatu darinya... Bau putus asa.",
  ui_story_5076_50761300_36_dialog_content = "Dia adalah salah satu dari kita, bagaimanapun.",
  ui_story_5076_50761300_37_dialog_content = "Tidak mungkin! Saya tidak bisa membayangkan sesuatu yang lebih penuh harapan—",
  ui_story_5076_50761300_38_dialog_content = "<size=50>Aaaaahhhh!!!!</size>",
  ui_story_5076_50761300_39_dialog_content = "Apa itu? Ayo pergi, Achilles!",
  ui_story_5076_50761300_40_dialog_content = "Apakah itu... suara Vice Kapten?",
  ui_story_5076_50761300_41_dialog_content = "Bagaimana jika aku katakan bahwa orang yang paling parah lukanya di grup kita adalah \"perisai\" kita sendiri?",
  ui_story_5076_50761300_42_dialog_content = "Apakah kamu masih berpikir ada harapan, Freya?",
  ui_story_5076_50761300_43_dialog_content = "<size=45>Aahhhh!!!</size>",
  ui_story_5076_50761300_44_dialog_content = "<size=45>Eclipsite! Eclipsite!!!</size>",
  ui_story_5076_50761300_45_dialog_content = "Ada apa ini?",
  ui_story_5076_50761300_46_dialog_content = "Begitu banyak kehancuran... Seolah tidak ada sejengkal pun tempat ini yang luput...",
  ui_story_5076_50761300_47_dialog_content = "Mengapa?! Apa yang dilakukan Eclipsites di ruang bawah tanah rumahku?!",
  ui_story_5076_50761300_48_dialog_content = "Mengapa aku tidak menyadari mereka lebih awal?!",
  ui_story_5076_50761300_49_dialog_content = "Tanda-tanda goresan ini dibuat oleh sebuah pedang, Ludweiss...",
  ui_story_5076_50761300_50_dialog_content = "<size=45>Mengapa? Mengapa?!?</size>",
  ui_story_5076_50761300_51_dialog_content = "Tenanglah, Adras. Kita semua di sini sekarang, dan tidak ada Eclipsites di sekitar.",
  ui_story_5076_50761300_52_dialog_content = "Tidak! Mereka berbohong! Mereka semua berbohong padaku!",
  ui_story_5076_50761300_53_dialog_content = "Mereka tidak pernah bisa mengusir Eclipsite yang menghancurkan kuil itu, dan sekarang dia mengikutiku pulang!",
  ui_story_5076_50761300_54_dialog_content = "Mereka semua terlalu takut untuk membunuhnya, tetapi saya sendiri tidak dapat menemukannya...",
  ui_story_5076_50761300_55_dialog_content = "Bagaimana bisa ada Eclipsite sekuat ini? Aku tidak memiliki cara untuk mengalahkannya, dan Marcela tidak mau keluar dari persembunyiannya karena itu...",
  ui_story_5076_50761300_56_dialog_content = "Bisakah kamu merasakan lokasinya, Ludweiss? Aku tidak bisa membiarkannya menyakiti orang lain!",
  ui_story_5076_50761300_57_dialog_content = "Aku tak akan membiarkan orang lain jatuh di tangan para Eclipsite. Tidak lagi...",
  ui_story_5076_50761300_58_dialog_content = "Kapten... Saya pikir dia akhirnya...",
  ui_story_5076_50761300_59_dialog_content = "Jadi, bahkan cinta yang sebersih miliknya pun tidak bisa menghentikan penyebaran korupsi yang mengerikan ini?",
  ui_story_5076_50761300_60_dialog_content = "Ternyata memang tidak ada masa depan untuk kita.",
  ui_story_5076_50761300_61_dialog_content = "Tidakkah kamu bisa menggunakan kekuatan Caelestite-mu untuk menstabilkan pikirannya, Ludweiss?",
  ui_story_5076_50761300_62_dialog_content = "Maaf Achilles, tapi seandainya itu mungkin, aku sudah melakukannya sejak lama...",
  ui_story_5076_50761300_63_dialog_content = "Berlindung di belakangku, semuanya! Tidak ada yang tahu kapan Eclipsite itu akan menyerang, jadi tetap waspada!",
  ui_story_5076_50761300_64_dialog_content = "Ini terlalu kuat untuk...",
  ui_story_5076_50761300_65_dialog_content = "Ke...",
  ui_story_5076_50761300_66_dialog_content = "Apa yang kaulakukan?",
  ui_story_5076_50761300_67_dialog_content = "Aku baru saja membuatnya tidur sebentar...",
  ui_story_5076_50761300_68_dialog_content = "Kamu melakukannya dengan sangat mudah, seolah-olah dia benar-benar tak berdaya.",
  ui_story_5076_50761300_69_dialog_content = "Dia pasti sangat lelah. Selama ini, dia adalah yang paling kesepian di antara kita semua.",
  ui_story_5076_50761300_70_dialog_content = "Apakah kamu pikir dia masih bisa memiliki mimpi yang baik?",
  ui_story_5076_50761300_71_dialog_content = "Saya tentu berharap demikian.",
  ui_story_5076_50761300_72_dialog_content = "Kamu benar, Cynthia: Aku merasa sangat menyesal sekarang. Apakah aku terlalu sombong?",
  ui_story_5076_50761300_73_dialog_content = "Saya pikir saya bisa menanggung segalanya, tapi saya belum membantu satu orang pun.",
  ui_story_5076_50761300_74_dialog_content = "Seandainya waktu itu aku telah membuat keputusan dan membebaskan kalian semua dari rasa sakit—",
  ui_story_5076_50761300_75_dialog_content = "Anda berencana untuk menghabisi kami di gua itu selama misi terakhir kami, bukan? Tapi pada akhirnya, Anda tidak bisa melakukannya.",
  ui_story_5076_50761300_76_dialog_content = "Ini semua salahku.",
  ui_story_5076_50761300_77_dialog_content = "Ini bukan salahmu bahwa segalanya berakhir seperti ini, atau salah siapa pun.",
  ui_story_5076_50761300_78_dialog_content = "Membunuh dengan senjata di masa perang bukanlah dosa, tetapi di masa damai... Keberadaan senjata itu sendiri adalah dosa.",
  ui_story_5076_50761300_79_dialog_content = "Apakah orang-orang biasa yang menolak kita benar-benar membenci kita dari lubuk hati mereka? Tidak—Saya pikir mereka hanya belum memiliki kesempatan untuk memahami kita.",
  ui_story_5076_50761300_80_dialog_content = "Yang dibutuhkan hanyalah kesempatan yang tepat... Sama seperti bagaimana Vice Kapten dan istrinya melindungi orang-orang ini, dan mereka membalasnya dengan merawatnya...",
  ui_story_5076_50761300_81_dialog_content = "Sayangnya, kita tidak memiliki cara untuk membuat semua orang di dunia memahami kita.",
  ui_story_5076_50761300_82_dialog_content = "Jika ada seseorang atau sesuatu yang harus disalahkan untuk semua ini, itu adalah takdir.",
  ui_story_5076_50761300_83_dialog_content = "Meski begitu, aku tidak menyesal.",
  ui_story_5076_50761300_84_dialog_content = "Setuju. Saya dengan sukarela menerima hasil ini sebagai ganti menyelamatkan tanah kita dari Eclipsites. Jika saya harus terbakar untuk tujuan itu, maka biarlah begitu.",
  ui_story_5076_50761300_85_dialog_content = "Itu tidak membuatku menjadi pengecut, bukan?",
  ui_story_5076_50761300_86_dialog_content = "Friegson, semua orang... Jika suatu hari nanti aku benar-benar berubah menjadi Eclipsite, jangan berani-berani menunjukkan belas kasihan padaku.",
  ui_story_5076_50761300_87_dialog_content = "Aku rasa aku akan pergi sebelum kamu... Jadi sampai saat itu, pertahankan petirmu tetap akurat seperti hari ini.",
  ui_story_5076_50761300_88_dialog_content = "... Apakah ini benar-benar satu-satunya hasil untuk semua orang?",
  ui_story_5076_50761300_89_dialog_content = "Setidaknya, saya menolak untuk menerimanya.",
  ui_story_5076_50761300_90_dialog_content = "Masih menulis di jurnalmu, huh?",
  ui_story_5076_50761300_91_dialog_content = "Membuat catatan tentang ini tidak akan mengubah apapun.",
  ui_story_5076_50761300_92_dialog_content = "Bahkan monster abadi seperti kita sendiri tidak bisa melihat masa depan kita dengan jelas.",
  ui_story_5076_50761300_93_dialog_content = "Saya hampir tidak bisa memegang kenangan masa lalu saya. Semua hari-hari bahagia itu perlahan-lahan terkikis oleh kegelapan...",
  ui_story_5076_50761300_94_dialog_content = "Mungkin segalanya akan lebih baik jika kita semua dilupakan—",
  ui_story_5076_50761300_95_dialog_content = "Tentu saja itu membuat perbedaan!",
  ui_story_5076_50761300_96_dialog_content = "Ingat, aku ini Caelestite! Tidak ada yang lebih memahami perasaan dan kenangan selain orang-orangku!",
  ui_story_5076_50761300_97_dialog_content = "Jika suatu saat ada yang membaca jurnal ini... Setidaknya mereka akan tahu tentang bintang-bintang yang telah membimbing orang-orang di zaman kita.",
  ui_story_5076_50761300_98_dialog_content = "Dan jika orang tersebut kebetulan adalah Caelestite lain, mereka akan mewarisi kenangan dan kehendakku, dan tahu persis bagaimana perasaanku tentang kalian semua...",
  ui_story_5076_50761300_99_dialog_content = "Bahkan bintang jatuh pun memiliki tempat di hati mereka yang melihat keindahannya.",
  ui_story_5076_50761300_100_dialog_content = "Ini pasti berarti sesuatu, jadi tolong... Biarkan saya terus menulis.",
  ui_story_5076_50761300_101_dialog_content = "Baiklah, tapi kamu akan merusak semua halamanmu jika tidak berhenti menangis.",
  ui_story_5076_50761300_102_dialog_content = "Kamu bisa sangat keras kepala kadang-kadang, Ludweiss... Jadi, ayo kita lakukan bersama.",
  ui_story_5076_50761300_103_dialog_content = "Bagaimanapun... Satu orang tidak mungkin bisa menulis semua kenangan kita bersama, bukan?",
  ui_story_5076_50761300_104_dialog_content = "Mari kita bantu Anda untuk tetap menjaga harapan hidup!",
  ui_story_5076_50761300_105_dialog_content = "Setidaknya salah satu dari kita pasti akan berhasil mencapai masa depan yang jauh. Saat itu terjadi, tidak peduli siapa dia—",
  ui_story_5076_50761300_106_dialog_content = "Tolong, jangan lupakan kami.",
  ui_story_5076_50761400_1_dialog_content = "<color=#e8d9bb>Saat para pelancong menyeberangi perbatasan, kapten berbalik sesuai rencana.</color>",
  ui_story_5076_50761400_2_dialog_content = "<color=#e8d9bb>Dia akan bertindak sebagai \"pengorbanan,\" menyerahkan dirinya kepada pengejar untuk menjamin kebebasan lima orang lainnya.</color>",
  ui_story_5076_50761400_3_dialog_content = "<color=#e8d9bb>Tapi, apakah para Star Warriors ini benar-benar akan menerima perdagangan seperti ini?</color>",
  ui_story_5076_50761400_4_dialog_content = "Mereka sekarang ada di tanganmu, Ludweiss. Jika ada yang bangun, buat mereka tidur lagi segera.",
  ui_story_5076_50761400_5_dialog_content = "Apakah kamu benar-benar berniat menyelamatkan Achilles sendirian, Adras?",
  ui_story_5076_50761400_6_dialog_content = "Apakah kamu lupa siapa aku? Aku Adras, orang yang mengakhiri perang! Aku lebih dari cukup untuk mereka.",
  ui_story_5076_50761400_7_dialog_content = "Kembali dulu. Kapten dan aku akan menyusulmu segera.",
  ui_story_5076_50761400_8_dialog_content = "Adras...",
  ui_story_5076_50761400_9_dialog_content = "Apakah Vice Kapten sudah pergi?",
  ui_story_5076_50761400_10_dialog_content = "Saya masih bisa mendengar langkah kakinya samar-samar. Biarkan dia pergi sedikit lebih jauh dulu.",
  ui_story_5076_50761400_11_dialog_content = "H-Hah?",
  ui_story_5076_50761400_12_dialog_content = "Kami adalah Silent Hunters. Tidak ada lagi yang seperti kami di dunia ini.",
  ui_story_5076_50761400_13_dialog_content = "Kita mungkin tidak memiliki rumah, tetapi selama kita tetap bersama, itu lebih dari cukup bagi kita.",
  ui_story_5076_50761400_14_dialog_content = "Berkelana di negeri ini sebagai kelompok buangan yang dibenci... Itu terdengar bagus bagiku.",
  ui_story_5076_50761400_15_dialog_content = "Bahkan jika seluruh dunia menyangkal masa depan kita, kami masih menolak untuk menyerah.",
  ui_story_5076_50761400_16_dialog_content = "Masihkah kamu berencana untuk menghentikan kami, Ludweiss?",
  ui_story_5076_50761400_17_dialog_content = "Aku merasa sedang diikuti, dan tepat seperti yang kukira...",
  ui_story_5076_50761400_18_dialog_content = "Kita bertemu lagi, pahlawan. Pasti ini adalah takdir, bukan?",
  ui_story_5076_50761400_19_dialog_content = "Lucius, kau penjahat! Demi masa depan kerajaan, aku bersumpah akan—",
  ui_story_5076_50761400_20_dialog_content = "Kamu dan Hunter lainnya telah memilih untuk mengkhianati kami. Hak apakah yang kamu miliki untuk berbicara tentang masa depan kerajaan?",
  ui_story_5076_50761400_21_dialog_content = "Penjaga! Tangkap pahlawan palsu ini!",
  ui_story_5076_50761400_22_dialog_content = "Minggir! Jangan kira kau bisa menghentikanku!",
  ui_story_5076_50761400_23_dialog_content = "Aku menolak untuk mengangkat pedangku terhadap orang-orang yang tidak bersalah!",
  ui_story_5076_50761400_24_dialog_content = "Sebuah perasaan yang menyentuh, tetapi sama sekali tidak ada gunanya. Lihatlah prajurit-prajurit ini, Adras; mereka tidak berbeda dengan kamu!",
  ui_story_5076_50761400_25_dialog_content = "Apa?",
  ui_story_5076_50761400_26_dialog_content = "Rarrr! Grrrr!",
  ui_story_5076_50761400_27_dialog_content = "Mereka semua Eclipsite?!",
  ui_story_5076_50761400_28_dialog_content = "Tapi mereka memakai seragam tentara! Ini tidak mungkin benar!",
  ui_story_5076_50761400_29_dialog_content = "Sama seperti kamu, mereka sekarang tidak lebih dari monster hasil modifikasi. Memang, mereka tidak setara kuatnya dengan kamu, tetapi mereka jauh lebih patuh.",
  ui_story_5076_50761400_30_dialog_content = "Apa maksudmu dengan \"dimodifikasi\"? Apa yang telah kamu lakukan terhadap prajurit yang bangga dari kerajaan kita?!",
  ui_story_5076_50761400_31_dialog_content = "Apakah kamu sudah lupa, Adras? Mungkin korupsi akhirnya telah merasuki pikiranmu?",
  ui_story_5076_50761400_32_dialog_content = "Jika begitu, itu hanya akan semakin lucu.",
  ui_story_5076_50761400_33_dialog_content = "Jangan dengarkan dia, Adras! Begitu aku bebas, aku akan—",
  ui_story_5076_50761400_34_dialog_content = "Pengawal, kendalikan kapten!",
  ui_story_5076_50761400_35_dialog_content = "Achilles! Monster, Lucius! Bagaimana kau bisa melakukan hal yang begitu mengerikan kepada para prajurit setia ini? Aku—",
  ui_story_5076_50761400_36_dialog_content = "Heheh, mereka sedikit lebih kuat dari yang kamu perkirakan, bukan?",
  ui_story_5076_50761400_37_dialog_content = "Itu karena mereka adalah kelompok terbaru dari prajurit yang ditingkatkan dari proyek Silent Hunters.",
  ui_story_5076_50761400_38_dialog_content = "Luar biasa, bukan? Mereka bahkan lebih dekat menjadi Eclipsites daripada versi sebelumnya!",
  ui_story_5076_50761400_39_dialog_content = "Mereka lebih aman, lebih mudah dikendalikan, dan sama sekali tidak memiliki alasan. Lagipula, itu hanya akan menghalangi mereka.",
  ui_story_5076_50761400_40_dialog_content = "Berhenti bicara, Lucius, atau aku tak akan bisa menahan diri lagi.",
  ui_story_5076_50761400_41_dialog_content = "Oh tidak, kau tidak mungkin bisa membunuhku. Aku adalah penasihat paling dipercaya raja, ingat? Jika kau berani menyentuhku, aku akan menghancurkan segala yang telah kau perjuangkan untuk melindunginya.",
  ui_story_5076_50761400_42_dialog_content = "Lagi pula, kamu sudah tahan begitu banyak. Kenapa berhenti sekarang?",
  ui_story_5076_50761400_43_dialog_content = "Sehebat apapun Silent Hunters, mereka semua telah dirusak oleh Darkflow. Kondisi psikologis kalian yang cepat memburuk adalah alasan mengapa saya percaya kalian semua harus dihapuskan.",
  ui_story_5076_50761400_44_dialog_content = "Katakan padaku, pahlawan perkasa: berapa banyak kenangan berharga yang telah ditelan oleh kegelapan di hatimu? Atau apakah kamu telah hidup dalam keadaan delirium selama ini?",
  ui_story_5076_50761400_45_dialog_content = "Matilah, monster!",
  ui_story_5076_50761400_46_dialog_content = "Lepaskan aku!",
  ui_story_5076_50761400_47_dialog_content = "Lucius! Karena bermain-main dengan nyawa orang dan menginjak-injak kesetiaan kami, kau pantas mendapatkan kematian yang paling buruk!",
  ui_story_5076_50761400_48_dialog_content = "Jika itu yang pantas aku terima, lalu bagaimana dengan makhluk abominasi setengah-Eclipsite sepertimu?",
  ui_story_5076_50761400_49_dialog_content = "Lihatlah pantulan pada pedangmu, Adras. Apakah kamu sekarang melihat dirimu dengan jelas?",
  ui_story_5076_50761400_50_dialog_content = "Sepertinya kau benar-benar telah melupakan kebenaran. Monster yang selama ini kau teriakkan...",
  ui_story_5076_50761400_51_dialog_content = "Tidak lain adalah kamu!",
  ui_story_5076_50761400_52_dialog_content = "Jangan dengarkan dia, Adras!",
  ui_story_5076_50761400_53_dialog_content = "Dia benar, Adras! Kamu bukan monster!",
  ui_story_5076_50761400_54_dialog_content = "Marcela? Kapan kamu sampai di sini?",
  ui_story_5076_50761400_55_dialog_content = "Tidak tahukah kamu betapa berbahayanya di sini? Berdirilah di belakangku, cepat!",
  ui_story_5076_50761400_56_dialog_content = "Apakah ini benar-benar orang yang telah kamu pertaruhkan nyawa dan anggota tubuh untuk melindungi, Achilles? Seorang gila total?",
  ui_story_5076_50761400_57_dialog_content = "Mundur! Aku tidak akan membiarkanmu menyakitinya!",
  ui_story_5076_50761400_58_dialog_content = "Urgh—",
  ui_story_5076_50761400_59_dialog_content = "Kamu sudah kehilangan terlalu banyak darah, Adras! Berhenti mencoba melindungiku!",
  ui_story_5076_50761400_60_dialog_content = "Ini tidak apa-apa, Marcela. Cukup tinggal di belakang dan serahkan semuanya padaku...",
  ui_story_5076_50761400_61_dialog_content = "Tidak! Aku tidak ingin melihatmu terluka karena aku!",
  ui_story_5076_50761400_62_dialog_content = "Berhenti, semua kalian! Dia adalah pahlawan terhebat di kerajaan kita—",
  ui_story_5076_50761400_63_dialog_content = "Jangan sakiti Adras yang malang ini lagi!",
  ui_story_5076_50761400_64_dialog_content = "<size=45>Marcela!!!</size>",
  ui_story_5076_50761400_65_dialog_content = "Tidak apa-apa, Adras... Aku akan selalu bersamamu...",
  ui_story_5076_50761400_66_dialog_content = "Mengapa... Ini tidak mungkin...",
  ui_story_5076_50761400_67_dialog_content = "Kamu telah meneriakkan nama itu seperti orang gila selama ini. Marcela...",
  ui_story_5076_50761400_68_dialog_content = "Itu adalah nama istrimu yang sudah meninggal, 'kan?",
  ui_story_5076_50761400_69_dialog_content = "Mati? Tidak—Dia tidak mati! Aku menyelamatkannya!",
  ui_story_5076_50761400_70_dialog_content = "Aku berhasil sampai padanya tepat waktu...",
  ui_story_5076_50761400_71_dialog_content = "Akhirnya, kamu kembali, Adras.",
  ui_story_5076_50761400_72_dialog_content = "Aku menunggu begitu lama... Untukmu.",
  ui_story_5076_50761400_73_dialog_content = "Benarkah?",
  ui_story_5076_50761400_74_dialog_content = "Saya percaya Anda sekarang ingat kebenarannya, Adras. Istri Anda sudah lama...",
  ui_story_5076_50761400_75_dialog_content = "<size=45>Lucius!</size>",
  ui_story_5076_50761400_76_dialog_content = "Tidak... Itu tidak mungkin... Katakan itu tidak benar, Marcela...",
  ui_story_5076_50761400_77_dialog_content = "Semua hari bahagia yang kita habiskan bersama setelah itu... Semua saat-saat kamu menyambutku kembali dari garis depan... Katakan padaku itu bukan bohong, Marcela...",
  ui_story_5076_50761400_78_dialog_content = "Hari itu...",
  ui_story_5076_50761400_79_dialog_content = "Argh... Kepalaku... Tidak...",
  ui_story_5076_50761400_80_dialog_content = "Tidaaak!!!",
  ui_story_5076_50761400_81_dialog_content = "Jangan buat aku melihatnya lagi!!!",
  ui_story_5076_50761400_82_dialog_content = "Dengan bergabung dengan Silent Hunters, kamu harus menerima bahwa modifikasi akan memberimu sebagian dari kekuatan Eclipsite.",
  ui_story_5076_50761400_83_dialog_content = "Ketika modifikasi selesai, kamu akan menjadi lebih kuat dari sebelumnya, tetapi kamu juga harus selalu menangkis korupsi dari Darkflow.",
  ui_story_5076_50761400_84_dialog_content = "Ini mungkin dapat mengganggu kewarasan Anda, atau bahkan merampas ingatan Anda.",
  ui_story_5076_50761400_85_dialog_content = "Aku... Aku tidak peduli lagi.",
  ui_story_5076_50761400_86_dialog_content = "Untuk mencegah kenanganmu tentang Marcela dihancurkan, saya meminta Ludweiss untuk mengekstrak cinta Anda padanya dan menyegelnya dalam pedang Anda.",
  ui_story_5076_50761400_87_dialog_content = "Kamu tidak seharusnya lagi diganggu oleh halusinasi... Lihatlah aku, Adras. Apakah kamu ingat sesuatu yang lain?",
  ui_story_5076_50761400_88_dialog_content = "Marcela... Saat itu, dia...",
  ui_story_5076_50761400_89_dialog_content = "Tidak, tidak, tidak—",
  ui_story_5076_50761400_90_dialog_content = "Tidak lagi!",
  ui_story_5076_50761400_91_dialog_content = "... Aku gagal menepati janjiku. Aku mengecewakannya.",
  ui_story_5076_50761400_92_dialog_content = "Aku meninggalkannya, dan dia <size=45>meninggal dalam kegelapan dan putus asa</size>.",
  ui_story_5076_50761400_93_dialog_content = "Aku tidak ingin memikirkan apapun lagi, jadi ubahlah aku sebanyak mungkin... Lagipula, aku sudah kehilangan semuanya.",
  ui_story_5076_50761400_94_dialog_content = "Aku akan melakukan apa saja asalkan bisa terus membunuh Eclipsite.",
  ui_story_5076_50761400_95_dialog_content = "Saat Marcela meninggal, dia mulai mengalami halusinasi... Tidak seharusnya ada yang harus hidup seperti ini.",
  ui_story_5076_50761400_96_dialog_content = "Apakah kamu yakin tidak ada cara untuk menghilangkan ingatannya tentang kematian wanita itu, Ludweiss?",
  ui_story_5076_50761400_97_dialog_content = "Ingatan bukan seperti tali, Achilles. Saya tidak bisa begitu saja memotong sebagian dan mengikat sisanya bersama-sama.",
  ui_story_5076_50761400_98_dialog_content = "Jika saya mencoba menghapus kenangan sepedih itu, itu juga akan mempengaruhi kenangan lainnya tentang Marcela.",
  ui_story_5076_50761400_99_dialog_content = "Atau apakah kamu meminta saya untuk menghapusnya sepenuhnya dari pikirannya? Karena itu akan jauh lebih kejam daripada hal lainnya.",
  ui_story_5076_50761400_100_dialog_content = "Biarkan saja dia seperti ini. Setidaknya, cinta dalam pedangnya aman dari kerusakan di tubuhnya. Dia akan berhasil, aku yakin akan hal itu...",
  ui_story_5076_50761400_101_dialog_content = "Meskipun kamu tidak setuju dengan penggunaan kebencianku untuk mendorongnya bertempur, aku ingin melindunginya seperti halnya kamu.",
  ui_story_5076_50761400_102_dialog_content = "Apakah kamu benar-benar berpikir ini adalah yang terbaik? Meninggalkannya terjebak dalam ilusi, terus mencari <color=#FFB400>kenyamanan palsu</color>? Jika ada sesuatu yang membangunkannya dari <color=#FFB400>khayalan manis</color> ini...",
  ui_story_5076_50761400_103_dialog_content = "Selama <color=#FFB400>pedangnya ada di sisinya</color>, ilusi akan terus mempertahankan rasa dirinya, serta kenangannya tentang Marcela.",
  ui_story_5076_50761400_104_dialog_content = "Percayalah padaku, ini lebih baik daripada membiarkannya menghadapi kenyataan kejam tentang kematian dia dan membiarkan kebencian merusak hatinya...",
  ui_story_5076_50761400_105_dialog_content = "M-Marcela? Jangan mendekat, di sini berbahaya!",
  ui_story_5076_50761400_106_dialog_content = "Apakah itu... Silent Hunter?",
  ui_story_5076_50761400_107_dialog_content = "Sangat menakutkan. Sulit membayangkan dia adalah pahlawan legendaris. Lihat dia! Dia benar-benar... <color=#FFB400>GILA</color>!",
  ui_story_5076_50761400_108_dialog_content = "Jika kamu menolak untuk berbisnis denganku, setidaknya biarkan istriku masuk.",
  ui_story_5076_50761400_109_dialog_content = "<color=#FFB400>Istri? Kapan kamu punya istri? Pergi sana, kau gila!</color>",
  ui_story_5076_50761400_110_dialog_content = "Sepertinya kau benar-benar telah melupakan kebenaran. Monster yang selama ini kau teriakkan...",
  ui_story_5076_50761400_111_dialog_content = "Tidak lain adalah kamu!",
  ui_story_5076_50761400_112_dialog_content = "Kuil—",
  ui_story_5076_50761400_113_dialog_content = "Marcela takut pada kuil—",
  ui_story_5076_50761400_114_dialog_content = "Tidak, bukan itu. Aku lah yang takut... Karena tumpukan reruntuhan itu adalah tempat Marcela <color=#FFB400>meninggal</color>.",
  ui_story_5076_50761400_115_dialog_content = "Itulah sebabnya aku harus menghancurkannya—",
  ui_story_5076_50761400_116_dialog_content = "<color=#FFB400>Aku harus menghancurkan semuanya!</color>",
  ui_story_5076_50761400_117_dialog_content = "<size=45>Aaaaaah!!!</size>",
  ui_story_5076_50761400_118_dialog_content = "<size=45>Matilah, Eclipsites!!!</size>",
  ui_story_5076_50761400_119_dialog_content = "<size=50>Kalian semua harus mati!!!</size>",
  ui_story_5076_50761500_1_dialog_content = "Apa yang terjadi di sini? Tanahnya... Ini tertutup oleh sisa-sisa Eclipsite!",
  ui_story_5076_50761500_2_dialog_content = "Ini Vice Kapten. Dia pasti kembali mengamuk.",
  ui_story_5076_50761500_3_dialog_content = "Kita harus menghentikannya sebelum dia melukai Ludweiss!",
  ui_story_5076_50761500_4_dialog_content = "Aku melihat ada orang yang berusaha kabur dari sana...",
  ui_story_5076_50761500_5_dialog_content = "Kemari, Cynthia! Kita... Kita tidak bisa menahan Vice Kapten lagi!",
  ui_story_5076_50761500_6_dialog_content = "Marcela—Marcela—!",
  ui_story_5076_50761500_7_dialog_content = "Kenapa... Kenapa tidak bisa aku saja...",
  ui_story_5076_50761500_8_dialog_content = "Eclipsites! Matilah, kalian monster!!!",
  ui_story_5076_50761500_9_dialog_content = "Apa yang terjadi padanya?",
  ui_story_5076_50761500_10_dialog_content = "Dia baru saja dipaksa terlalu jauh, dan ingatannya hancur melalui ilusi yang melindunginya.",
  ui_story_5076_50761500_11_dialog_content = "Jadi apa yang harus kita lakukan?",
  ui_story_5076_50761500_12_dialog_content = "Kita masih memiliki satu pilihan terakhir! Ingat, Ludweiss?",
  ui_story_5076_50761500_13_dialog_content = "Tapi, jika kita melakukan itu...",
  ui_story_5076_50761500_14_dialog_content = "Apakah kamu bilang kamu ingin meninggalkannya dalam keadaan seperti ini?",
  ui_story_5076_50761500_15_dialog_content = "Kamu masih ingat apa yang kita bicarakan hari itu, Kapten?",
  ui_story_5076_50761500_16_dialog_content = "Saya tidak pikir Vice Kapten akan keberatan jika kamu yang melakukannya—",
  ui_story_5076_50761500_17_dialog_content = "Tidak! Biarkan... Aku yang menanganinya.",
  ui_story_5076_50761500_18_dialog_content = "Kami mengandalkanmu, Ludweiss...",
  ui_story_5076_50761500_19_dialog_content = "Aku sangat minta maaf, Adras... Kali ini, aku akan menghilangkan sumber penderitaanmu!",
  ui_story_5076_50761500_20_dialog_content = "Apa yang sedang kamu lakukan, Ludweiss?!",
  ui_story_5076_50761500_21_dialog_content = "Saya benar-benar menghapus kenangan tentang Marcela dari pikirannya! Dengan cara itu, dia akhirnya bisa mulai mencari masa depan baru...",
  ui_story_5076_50761500_22_dialog_content = "Tidak...",
  ui_story_5076_50761500_23_dialog_content = "Aku tidak ingin masa depan yang baru, jadi...",
  ui_story_5076_50761500_24_dialog_content = "Jangan berani-berani menyentuh kenangan saya tentang dia! Itu semua yang saya miliki!!!",
  ui_story_5076_50761500_25_dialog_content = "Awas!",
  ui_story_5076_50761500_26_dialog_content = "Ludweiss!",
  ui_story_5076_50761500_27_dialog_content = "(Aku sangat dekat... Tapi aku tidak bisa menyelesaikannya...)",
  ui_story_5076_50761500_28_dialog_content = "Apa yang kau baca?",
  ui_story_5076_50761500_29_dialog_content = "Oh, ini hanya buku harian tua dan terfragmentasi yang Nyonya Sheol jual kepadaku dengan harga murah. Meskipun banyak halaman yang hilang, tulisan di sini sangat menarik!",
  ui_story_5076_50761500_30_dialog_content = "(Apakah ini... Kenangan? Tapi perasaan ini... Begitu jauh... Aku tidak bisa melihatnya dengan jelas...)",
  ui_story_5076_50761500_31_dialog_content = "... Entah kenapa, rasanya aneh tapi familiar.",
  ui_story_5076_50761500_32_dialog_content = "Aku tahu maksudmu! Begitu aku mengambilnya, rasanya seperti aku kembali ke Eraveil.",
  ui_story_5076_50761500_33_dialog_content = "Eraveil?",
  ui_story_5076_50761500_34_dialog_content = "Hah? Apakah kamu mengatakan sesuatu?",
  ui_story_5076_50761500_35_dialog_content = "Aku tidak mendengar siapa-siapa berbicara.",
  ui_story_5076_50761500_36_dialog_content = "Itu aneh... Bagaimanapun, jurnal ini adalah catatan perjalanan seorang Caelestite! Meskipun aku tidak bisa membaca tulisan mereka, aku bisa melihat kenangan Caelestite hanya dengan memegangnya di tangan.",
  ui_story_5076_50761500_37_dialog_content = "Bisakah kamu menunjukkanku juga?",
  ui_story_5076_50761500_38_dialog_content = "Benarkah? Ini pertama kalinya aku melihat kamu begitu tertarik dengan sesuatu.",
  ui_story_5076_50761500_39_dialog_content = "Tentu, mari kita lihat bersama! Saya harus bisa menggunakan kemampuan psikis saya pada kamu dan jurnal secara bersamaan...",
  ui_story_5076_50761500_40_dialog_content = "Beritahu saya jika ada yang tidak beres—",
  ui_story_5076_50761500_41_dialog_content = "<color=#FFB400>Regal.</color>",
  ui_story_5076_50761500_42_dialog_content = "Apakah kamu bermimpi tentang masa depan yang jauh, Adras? Atau apakah kamu memimpikan aku setelah semua tahun itu?",
  ui_story_5076_50761500_43_dialog_content = "Bisakah itu... Saat itu...",
  ui_story_5076_50761500_44_dialog_content = "Akhirnya bangun juga, ya?",
  ui_story_5076_50761500_45_dialog_content = "Kapten...? Apa yang terjadi? Di mana kita?",
  ui_story_5076_50761500_46_dialog_content = "Apa kamu ingat apa-apa?",
  ui_story_5076_50761500_47_dialog_content = "Saya... Saya Regal, dan saya...",
  ui_story_5076_50761500_48_dialog_content = "Seharusnya aku melakukan sesuatu... Tapi aku tidak bisa mengingat apa itu.",
  ui_story_5076_50761500_49_dialog_content = "Kapten, dia...",
  ui_story_5076_50761500_50_dialog_content = "Kerajaan ini aman dari Eclipsite, yang berarti aku akhirnya bisa pulang dan menikmati kehidupan yang damai... Tapi, di mana rumahku?",
  ui_story_5076_50761500_51_dialog_content = "Ada kehangatan ini di dada saya... Saya tidak bisa menjelaskannya dengan baik, tapi saya merasa jauh lebih ringan sekarang.",
  ui_story_5076_50761500_52_dialog_content = "Rasanya seakan-akan aku merindukan seseorang. Entah kenapa, aku tidak bisa mengingat wajah mereka, tapi aku masih merasa puas.",
  ui_story_5076_50761500_53_dialog_content = "Apakah ini kebahagiaan yang pernah Anda ceritakan padaku, Kapten?",
  ui_story_5076_50761500_54_dialog_content = "Kapten? Ada apa?",
  ui_story_5076_50761500_55_dialog_content = "... Tinggalkan.",
  ui_story_5076_50761500_56_dialog_content = "Pergi? Tapi harus ke mana aku?",
  ui_story_5076_50761500_57_dialog_content = "Aku... Aku tidak tahu. Tapi jika hatimu menyuruhmu pergi ke suatu tempat, ikuti saja.",
  ui_story_5076_50761500_58_dialog_content = "Pergi dan jangan pernah kembali, Adras.",
  ui_story_5076_50761500_59_dialog_content = "Hatiku...?",
  ui_story_5076_50761500_60_dialog_content = "Benar... Aku ingin menjalani hidup yang tenang dan damai... Tapi di mana aku harus pergi untuk melakukan itu?",
  ui_story_5076_50761500_61_dialog_content = "Aku sangat minta maaf, semua orang. Ini semua salahku... Aku tidak bisa membawa diriku untuk melakukannya.",
  ui_story_5076_50761500_62_dialog_content = "Aku ingin mimpi-mimpimu berakhir pada saat yang sempurna, tapi aku tidak bisa melakukannya... Aku tidak bisa mengarahkan pedangku padamu.",
  ui_story_5076_50761500_63_dialog_content = "Jadi tolong, tetap menjauh. Jangan pernah menunjukkan wajah kalian di kerajaan lagi.",
  ui_story_5076_50761500_64_dialog_content = "Kamu yakin tidak bisa ikut dengan kami, Kapten?",
  ui_story_5076_50761500_65_dialog_content = "Kerajaan ini kembali jatuh ke dalam kekacauan. Aku tidak bisa membiarkannya seperti ini.",
  ui_story_5076_50761500_66_dialog_content = "Imam tinggi yang pengecut itu berhasil melarikan diri... Sepertinya semuanya erat kaitannya dengan raja. Apakah benar-benar tidak ada yang bisa kita lakukan?",
  ui_story_5076_50761500_67_dialog_content = "Aku... Aku telah bersumpah untuk tidak menyerang warga sipil, jadi hitung aku keluar.",
  ui_story_5076_50761500_68_dialog_content = "Lupakan saja, Cynthia. Menghadapi raja tidak akan mengubah apa pun, meskipun kita berhasil membalas dendam padanya. Itu hanya akan menciptakan lebih banyak kekacauan untuk kerajaan.",
  ui_story_5076_50761500_69_dialog_content = "Kenyataannya, sang raja hanya berusaha mempertahankan kekuasaannya. Selain itu, dia pasti layak untuk memimpin rakyatnya.",
  ui_story_5076_50761500_70_dialog_content = "Tapi, bukankah rakyatnya juga berhak mendapatkan keadilan? Jika tidak ada yang dilakukan, bagaimana mereka bisa mencegah lebih banyak orang yang terluka?",
  ui_story_5076_50761500_71_dialog_content = "Kerajaan ini hancur, dan kami dilihat sebagai monster. Tidak ada alasan bagi kami untuk memicu api.",
  ui_story_5076_50761500_72_dialog_content = "Aku mengerti... Dari tinggal bersama hingga berpisah, semua itu hanya membutuhkan satu langkah.",
  ui_story_5076_50761500_73_dialog_content = "Cynthia?",
  ui_story_5076_50761500_74_dialog_content = "Sepertinya jalan kita memang berbeda. Dalam hal ini, saya pergi sekarang.",
  ui_story_5076_50761500_75_dialog_content = "Aku akan menghormati keputusan semua orang dan menahan diri untuk tidak melakukan apapun.",
  ui_story_5076_50761500_76_dialog_content = "... Semoga suatu hari nanti kamu menemukan kedamaian, Cynthia. Selamat tinggal.",
  ui_story_5076_50761500_77_dialog_content = "Apa pendapatmu, Friegson?",
  ui_story_5076_50761500_78_dialog_content = "Tidak peduli kemana aku pergi, aku selalu dilihat sebagai seorang kriminal. Itulah sebabnya... Aku ingin pergi bersamamu dan menyerahkan diri, Kapten.",
  ui_story_5076_50761500_79_dialog_content = "Freya dan Adras, jaga dirimu baik-baik.",
  ui_story_5076_50761500_80_dialog_content = "Berapa lama lagi kamu akan bekerja untuk pria itu?",
  ui_story_5076_50761500_81_dialog_content = "Saya tidak akan bekerja untuknya, Freya. Setelah semua ini, saya tidak memiliki harapan untuk hal seperti itu.",
  ui_story_5076_50761500_82_dialog_content = "Namun, kerajaan membutuhkan Claymore jika ingin memadamkan pemberontakan yang akan datang.",
  ui_story_5076_50761500_83_dialog_content = "Sama seperti kamu, saya juga memiliki tugas yang tidak bisa saya tinggalkan begitu saja.",
  ui_story_5076_50761500_84_dialog_content = "Saran saya hanya satu, bawa Ludweiss dan pergi ke tempat yang jauh dari sini.",
  ui_story_5076_50761500_85_dialog_content = "Jalan kami tidak bisa pernah bersilangan lagi.",
  ui_story_5076_50761500_86_dialog_content = "Saya memiliki tugas untuk mengeliminasi segala ancaman terhadap kerajaan kita. Ketika kita bertemu lagi, saya tidak akan punya pilihan selain...",
  ui_story_5076_50761601_1_dialog_content = "Adras!",
  ui_story_5076_50761601_2_dialog_content = "Akhirnya kamu bangun? Kamu sudah tidur begitu lama.",
  ui_story_5076_50761601_3_dialog_content = "Mengapa Vice Kapten tiba-tiba menyerangmu seperti itu? Untungnya, lukanya tidak terlalu serius. Saya sudah merawatnya untukmu.",
  ui_story_5076_50761601_4_dialog_content = "Tapi melihat dari luka-luka lama kamu, sepertinya masih ada risiko korupsi... Bagaimana kamu bisa menahannya selama ini? Apakah ini juga salah satu kekuatan Caelestite-mu?",
  ui_story_5076_50761601_X4_dialog_content = "... Mana sisanya?",
  ui_story_5076_50761601_5_dialog_content = "Mereka semua pergi sekarang, bahkan Kapten Vice kita yang amnesia. Dia juga tidak tahu kemana dia pergi.",
  ui_story_5076_50761601_6_dialog_content = "Tapi adil saja, aku juga tidak. Untungnya kamu masih di sini... Setidaknya kita bisa terus berkelana bersama.",
  ui_story_5076_50761601_7_dialog_content = "Aku tidak bisa menghapus sepenuhnya kenangan-kenangan tentang Marcela... Jika dia mengingatnya lagi...",
  ui_story_5076_50761601_8_dialog_content = "Tapi sepertinya Vice Kapten sudah kehilangan sebagian besar ingatannya... Aku penasaran, kemana dia akan pergi sekarang?",
  ui_story_5076_50761601_9_dialog_content = "Benar... Dengan umur panjangmu, menjadi pengembara sangat masuk akal...",
  ui_story_5076_50761601_10_dialog_content = "Ludweiss?",
  ui_story_5076_50761601_11_dialog_content = "Kamu percaya padaku, Freya?",
  ui_story_5076_50761601_12_dialog_content = "Jika kamu mau, bantu aku mencari semua orang lagi.",
  ui_story_5076_50761601_13_dialog_content = "Dengan cara itu, mungkin ada kesempatan untuk mengubah hal-hal bagi kita.",
  ui_story_5076_50761601_14_dialog_content = "Reruntuhan ini... Tempat apa ini? Mengapa aku datang ke sini tanpa sadar?",
  ui_story_5076_50761601_15_dialog_content = "Rasanya sangat familiar... Apakah aku pernah ke sini sebelumnya?",
  ui_story_5076_50761601_16_dialog_content = "Mungkin.",
  ui_story_5076_50761601_17_dialog_content = "Hah? Freya... Apakah itu kamu?",
  ui_story_5076_50761601_18_dialog_content = "Jangan pedulikan aku, teruslah mencari. Aku yakin ada sesuatu yang familiar untukmu yang tersembunyi di sini.",
  ui_story_5076_50761601_19_dialog_content = "Jejak-jejak api dan kehancuran ini... Apakah Eclipsites yang bertanggung jawab atas ini?",
  ui_story_5076_50761601_20_dialog_content = "Ada makam di sini juga... Tapi siapa yang akan menaruh ini di dalam rumah?",
  ui_story_5076_50761601_21_dialog_content = "Tempat ini dipenuhi rumput liar, ya?",
  ui_story_5076_50761601_22_dialog_content = "Apa ini—",
  ui_story_5076_50761601_23_dialog_content = "Sebuah mural yang terbakar...?",
  ui_story_5076_50761601_24_dialog_content = "Apa kamu masih ingat itu?",
  ui_story_5076_50761601_25_dialog_content = "Apa? Saya tidak ingat apa-apa... Tapi mural ini sepertinya menggambarkan sebuah upacara.",
  ui_story_5076_50761601_26_dialog_content = "Apa mungkin itu...?",
  ui_story_5076_50761601_27_dialog_content = "\"Mereka bilang orang pertama yang melukis mural seperti ini adalah orang gila.\"",
  ui_story_5076_50761601_28_dialog_content = "\"Dan untuk melarikan diri dari penderitaan dalam hidupnya, dia menciptakan kenyataan baru yang sepenuhnya.\"",
  ui_story_5076_50761601_29_dialog_content = "\"Apakah ini mengakhiri penderitaannya?\"",
  ui_story_5076_50761601_30_dialog_content = "\"Tidak. Dia hanya menyegelnya saja.\"",
  ui_story_5076_50761601_31_dialog_content = "\"Baiklah...\"",
  ui_story_5076_50761601_32_dialog_content = "M... Marcela?",
  ui_story_5076_50761601_33_dialog_content = "Saat kita bekerja menuju impian kita, mari terus membuat kenangan indah bersama.",
  ui_story_5076_50761601_34_dialog_content = "Saya berjanji untuk menghargai setiap momen indah dalam hidup kita—",
  ui_story_5076_50761601_35_dialog_content = "Ah... Ahhh...",
  ui_story_5076_50761601_36_dialog_content = "Marcela... Marcela-ku yang manis...",
  ui_story_5076_50761601_37_dialog_content = "Akhirnya... Aku kembali di sisimu lagi...",
  ui_story_5076_50761601_38_dialog_content = "Dan begitulah akhir cerita dari pahlawan besar Adras. Katakan padaku, Freya; mengapa kita terus berusaha untuk hidup?",
  ui_story_5076_50761601_39_dialog_content = "Apa gunanya bertahan hidup di dunia yang terbalik ini jika itu berarti kehilangan segala hal yang kita pedulikan?",
  ui_story_5076_50761601_40_dialog_content = "Dunia ini tidak membutuhkan kita lagi.",
  ui_story_5076_50761601_41_dialog_content = "Mungkin ini saatnya untuk membebaskan Adras dari kesengsaraannya... Dan diri kita sendiri.",
  ui_story_5076_50761601_42_dialog_content = "Ludweiss mengatakan bahwa dia telah menemukan jalan menuju masa depan baru bagi kita, meskipun dengan biaya.",
  ui_story_5076_50761601_43_dialog_content = "Kamu masih bersedia mempercayai orang lain?",
  ui_story_5076_50761601_44_dialog_content = "Benar. Aku akan selalu menaruh keyakinanku pada harapan.",
  ui_story_5076_50761601_45_dialog_content = "Ayo pergi, Cynthia. Sudah waktunya untuk Silent Hunters mengadakan reuni terakhir.",
  ui_story_5076_50761601_X45_dialog_content = "<color=#e8d9bb>Jadi, bintang-bintang berangkat sekali lagi, menolak untuk tunduk. Setelah semua pertempuran yang dijalani untuk God of Light yang mundur, kali ini, pertempuran mereka akhirnya untuk diri mereka sendiri.</color>",
  ui_story_5076_50761601_46_dialog_content = "Mereka di sini, Achilles.",
  ui_story_5076_50761601_47_dialog_content = "Adras, Freya, Friegson, dan bahkan Cynthia... Mereka semua ada di sini sekarang.",
  ui_story_5076_50761601_48_dialog_content = "Dan kamu yakin ini akan berhasil, Ludweiss?",
  ui_story_5076_50761601_49_dialog_content = "Tidak sepenuhnya, tapi... Hatiku memberitahu saya untuk mempercayai apa yang saya lihat ketika saya tidak sadar.",
  ui_story_5076_50761601_50_dialog_content = "Dalam seribu tahun, mereka masih akan menunggu tempat yang bisa disebut rumah. Saat waktu itu tiba... Mereka akhirnya akan bebas.",
  ui_story_5076_50761601_51_dialog_content = "Saya yakin mereka akan menemukan kebahagiaan mereka nanti.",
  ui_story_5076_50761601_52_dialog_content = "Aku percaya padamu, Ludweiss. Tapi berapa harga yang harus kamu bayar untuk menyegel mereka seperti ini?",
  ui_story_5076_50761601_53_dialog_content = "Sudah kukatakan jangan meremehkan kami Caelestites, bukan? Tidak ada yang lebih mengerti kekuatan jiwa daripada kami!",
  ui_story_5076_50761601_54_dialog_content = "The Silent Hunters diberikan tubuh yang abadi sebagai hasil dari modifikasi mereka.",
  ui_story_5076_50761601_55_dialog_content = "Dan dengan menangkap emosi kuat mereka dan mengubahnya menjadi \"batu penjuru,\" jiwa mereka dapat disegel dalam keadaan dormant.",
  ui_story_5076_50761601_56_dialog_content = "Mereka akan tetap waspada dalam mimpi ribuan tahun mereka, tetapi setelah itu... Mereka harus menggunakan ingatan mereka untuk melawan perjalanan waktu.",
  ui_story_5076_50761601_57_dialog_content = "Namun…",
  ui_story_5076_50761601_58_dialog_content = "Sekarang!",
  ui_story_5076_50761601_59_dialog_content = "Apa ini... Sebuah formasi sihir? Tunggu, apa yang kamu pikir kamu lakukan, Kapten?!",
  ui_story_5076_50761601_60_dialog_content = "Bukankah kau memanggil kami ke arena untuk...",
  ui_story_5076_50761601_61_dialog_content = "Maaf, tapi ini adalah satu-satunya cara saya bisa menjamin kedamaian abadi kamu... Semoga kalian semua mimpi yang paling indah.",
  ui_story_5076_50761601_62_dialog_content = "<color=#e8d9bb>Gairah dalam diri Friegson telah lama terbakar oleh api, meninggalkan hanya segenggam abu.</color>",
  ui_story_5076_50761601_63_dialog_content = "<color=#e8d9bb>Jadi, satu-satunya emosi yang tersisa untuk menyegelnya mungkin hanya kebencian.</color>",
  ui_story_5076_50761601_64_dialog_content = "<color=#e8d9bb>Caelestite biasa tidak bisa melakukan hal semacam itu, apalagi mereka yang dihantui oleh luka lama.</color>",
  ui_story_5076_50761601_65_dialog_content = "<color=#e8d9bb>Namun, jika seorang Caelestite bersedia mengorbankan hidup mereka, membakar diri mereka sendiri untuk melestarikan emosi orang lain...</color>",
  ui_story_5076_50761601_66_dialog_content = "Tidur!",
  ui_story_5076_50761601_67_dialog_content = "Ke... Kenapa...?",
  ui_story_5076_50761601_68_dialog_content = "Kamu bisa tenang sekarang, Friegson. Saya janji impianmu akan bebas dari kesedihan mulai sekarang.",
  ui_story_5076_50761601_69_dialog_content = "Tidak masalah... Selama kalian yang mengkhianati aku... Aku tidak keberatan...",
  ui_story_5076_50761601_70_dialog_content = "Apa yang telah kau lakukan pada Friegson, Kapten? Mengapa kau menyerangnya seperti ini?!",
  ui_story_5076_50761601_71_dialog_content = "Masih dalam kegelapan, bukan? Raja ingin menghilangkan kalian, makhluk berbahaya, dan Achilles memilih untuk berpihak pada rajanya.",
  ui_story_5076_50761601_72_dialog_content = "Lucius? Bagaimana mungkin kamu masih hidup...?",
  ui_story_5076_50761601_73_dialog_content = "Kapten, bukankah kamu akan menyangkal kata-katanya? Cukup katakan dia berbohong, dan aku akan percaya padamu!",
  ui_story_5076_50761601_74_dialog_content = "Pengawal! Tangkap pelarian jahat ini!",
  ui_story_5076_50761601_75_dialog_content = "Aku serahkan sisanya padamu, Kapten. Aku percaya kamu tidak akan mengecewakan Yang Mulia, bukan?",
  ui_story_5076_50761601_76_dialog_content = "Kapten!!!",
  ui_story_5076_50761601_77_dialog_content = "Eclipsite ini tampak lebih kuat dari sebelumnya! Cynthia, tetap pada posisi kamu...",
  ui_story_5076_50761601_78_dialog_content = "Awas!",
  ui_story_5076_50761601_79_dialog_content = "Cynthia? Kamu...",
  ui_story_5076_50761601_80_dialog_content = "Seperti yang sudah aku katakan, Freya... Aku akan pergi sebelum kamu. Jika ada masa depan untuk kita di luar sana, aku harap kamu akan—",
  ui_story_5076_50761601_81_dialog_content = "Cynthia!",
  ui_story_5076_50761601_82_dialog_content = "Seperti yang saya katakan sebelumnya, saya memiliki kewajiban untuk menghancurkan segala ancaman terhadap kerajaan.",
  ui_story_5076_50761601_83_dialog_content = "Aku bukan kaptenmu lagi. Aku seorang algojo yang melayani kerajaan.",
  ui_story_5076_50761601_84_dialog_content = "Ayo, Regal.",
  ui_story_5076_50761601_85_dialog_content = "Sekarang setelah kamu akhirnya ingat, konsentrasikan semua kemarahan dan kebencianmu... Dan lepaskan semuanya padaku.",
  ui_story_5076_50761601_86_dialog_content = "<size=45>Kamu—</size>",
  ui_story_5076_50761601_87_dialog_content = "<size=45>Claymore—!!!</size>",
  ui_story_5076_50761602_1_dialog_content = "<color=#e8d9bb>Meskipun Adras tampaknya rentan dalam emosinya, kekuatan dan kemauan bertarungnya sangat luar biasa.</color>",
  ui_story_5076_50761602_2_dialog_content = "<color=#e8d9bb>Untuk merebut pedang yang memegang memori terakhir Adras, Achilles sengaja menerima pukulan dari pedang tersebut.</color>",
  ui_story_5076_50761602_3_dialog_content = "Maafkan aku... Adras.",
  ui_story_5076_50761602_4_dialog_content = "<color=#e8d9bb>Setelah menusukkan pedang yang baru saja dia rebut kembali ke Adras, dia seketika kehilangan kekuatan, roboh ke tanah.</color>",
  ui_story_5076_50761602_5_dialog_content = "<color=#e8d9bb>Sementara itu, segel yang menargetkan Freya dan Cynthia juga telah selesai.</color>",
  ui_story_5076_50761602_6_dialog_content = "Kamu telah berbuat baik, kapten setia raja. Sekarang musnahkan monster-monster ini sekali dan untuk selamanya!",
  ui_story_5076_50761602_7_dialog_content = "Kapten Achilles... Kenapa...?",
  ui_story_5076_50761602_8_dialog_content = "Ludweiss mengatakan bahwa ini adalah satu-satunya cara untuk mengubah takdir kita, Adras... Tapi jangan khawatir, kita akan bertemu lagi suatu hari nanti.",
  ui_story_5076_50761602_9_dialog_content = "Ketika hari itu tiba, saya harap Anda akan menemukan kebahagiaan Anda sekali lagi.",
  ui_story_5076_50761602_10_dialog_content = "Sudah berakhir sekarang, Ludweiss?",
  ui_story_5076_50761602_11_dialog_content = "Jiwa mereka telah disegel dalam tubuh mereka yang tak bisa mati... Di mana mereka akan beristirahat... sampai...",
  ui_story_5076_50761602_12_dialog_content = "Kamu bilang bahwa tidur lelap ini, ditambah dengan korupsi mereka, memiliki kemungkinan merusak memori mereka, bahkan akal sehat mereka...",
  ui_story_5076_50761602_13_dialog_content = "Tapi meskipun hanya Adras... Dia memiliki sedikit sekali kebahagiaan dalam hidupnya. Setidaknya... Dia harus diizinkan untuk memegang kenangan bahagianya, bukan?",
  ui_story_5076_50761602_14_dialog_content = "Maaf... Tapi Caelestite bukanlah segalanya... Yang bisa kita lakukan sekarang... adalah berharap.",
  ui_story_5076_50761602_15_dialog_content = "Harap kegilaan mereka akan padam setelah seribu tahun... Jika mereka masih bisa mengingat satu kenangan bahagia saat itu... Semua ini akan menjadi berarti.",
  ui_story_5076_50761602_16_dialog_content = "Urgh, aku hampir mencapai batasku... Tapi aku masih belum sampai ke Adras...",
  ui_story_5076_50761602_17_dialog_content = "(Tataplah langit, dan bintang-bintang akan bersinar sebagai balasannya.)",
  ui_story_5076_50761602_18_dialog_content = "(Kehangatan cahaya mereka masih sama, meski setelah seribu tahun.)",
  ui_story_5076_50761602_19_dialog_content = "(Biar aku membantumu kali ini!)",
  ui_story_5076_50761602_20_dialog_content = "Suara ini... Apakah kamu dari masa yang jauh itu?",
  ui_story_5076_50761602_X20_dialog_content = "Bangun, Regal!",
  ui_story_5076_50761602_X21_dialog_content = "Lalu, mari kita lihat mereka bersama... <color=#FFB400>Regal</color>.",
  ui_story_5076_50761602_21_dialog_content = "Begitu... Sepertinya usahaku tidak sia-sia setelah semua...",
  ui_story_5076_50761602_22_dialog_content = "Kenangan berbintang itu bertahan melalui ujian waktu, dan sekarang akhirnya berada di tangan Caelestite lainnya...",
  ui_story_5076_50761602_23_dialog_content = "Selama ini aku merasa rindu, dan suara-suara itu telah berusaha keras untuk mencapai ku.",
  ui_story_5076_50761602_24_dialog_content = "Emosi bersama kita mengikat kita, menciptakan ikatan yang melampaui aliran waktu...",
  ui_story_5076_50761602_25_dialog_content = "Adras! Sekarang aku bisa melihatnya... Masa depan itu nyata.",
  ui_story_5076_50761602_26_dialog_content = "Bertahun-tahun dari sekarang, seseorang akan menunggu kembalinya kemenanganmu.",
  ui_story_5076_50761602_27_dialog_content = "Aku... tak mau...",
  ui_story_5076_50761602_28_dialog_content = "Aku tidak menginginkan kehidupan abadi. Aku tidak memerlukan keabadian...",
  ui_story_5076_50761602_29_dialog_content = "Yang aku inginkan... hanyalah momen yang terlepas dari genggamanku... Itu benar... Yang aku butuhkan hanyalah Marcela.",
  ui_story_5076_50761602_30_dialog_content = "Jadi tolong... Biarkan aku pergi! Aku tidak ingin disegel! Biarkan aku berbaring di sisi Marcela dan tidur selama sisa waktu!",
  ui_story_5076_50761602_31_dialog_content = "Jika itu yang kamu inginkan...",
  ui_story_5076_50761602_32_dialog_content = "Bantu saya, Marcela... Dan kamu juga, teman jauhku—",
  ui_story_5076_50761602_33_dialog_content = "Bantu aku mengubah kerinduannya menjadi kekuatan yang dia butuhkan untuk bertahan hidup!",
  ui_story_5076_50761602_34_dialog_content = "(Biarkan orang dalam ingatannya tetap berada di sisinya—)",
  ui_story_5076_50761602_35_dialog_content = "... Marcela?",
  ui_story_5076_50761602_36_dialog_content = "Jangan menangis, Adras... Aku di sini...",
  ui_story_5076_50761602_37_dialog_content = "Tunggu, Marcela! Jangan pergi!",
  ui_story_5076_50761602_38_dialog_content = "Aku tidak akan pergi kemana pun, manis ku Adras. Aku akan selalu bersamamu, sekarang dan selamanya...",
  ui_story_5076_50761602_39_dialog_content = "Jadi jangan takut... Semua temanmu ingin kamu tidur, sekarang istirahatlah kepala yang lelah...",
  ui_story_5076_50761602_40_dialog_content = "Tidur... Jadi akhirnya kita bisa—",
  ui_story_5076_50761602_41_dialog_content = "Tidak! Tolong!",
  ui_story_5076_50761602_42_dialog_content = "Marcela! Jangan pergi!",
  ui_story_5076_50761602_43_dialog_content = "Jangan menangis, Adras.",
  ui_story_5076_50761602_44_dialog_content = "Kenangan kita, kehendak kita... Bahkan keyakinan kita.",
  ui_story_5076_50761602_45_dialog_content = "Kami meninggalkan semuanya pada Marcela, jadi dia bisa selalu berada di sisi Anda.",
  ui_story_5076_50761602_46_dialog_content = "Selama kamu masih memiliki sedikit keterikatan dengan dunia ini dan bersedia menaruh kepercayaanmu pada harapan.",
  ui_story_5076_50761602_47_dialog_content = "(Impianmu tidak akan pernah merasa kesepian.)",
  ui_story_5076_50761602_48_dialog_content = "Kamu akan selalu bersama.",
  ui_story_5076_50761602_49_dialog_content = "(Ikutlah dengan saya, <color=#FFB400>Adras</color>. Saatnya bangun dari <color=#FFB400>mimpi</color> ribuan tahunmu—)",
  ui_story_5076_50761602_50_dialog_content = "Ketika kamu akhirnya <color=#FFB400>bangun</color>, kamu mungkin tidak ingat apa-apa. Jika itu terjadi, tolong jangan sedih.",
  ui_story_5076_50761602_51_dialog_content = "Kenangan berharga itu akan selalu tertidur dalam hatimu, Adras.",
  ui_story_5076_50761602_52_dialog_content = "Perasaan yang melekat pada mereka akan selalu menjadi bagian dari jiwamu.",
  ui_story_5076_50761602_53_dialog_content = "Kamu tidak akan pernah sendirian lagi.",
  ui_story_5076_50761602_54_dialog_content = "Sekarang, tenangkan pikiranmu dan tidurlah...",
  ui_story_5076_50761602_55_dialog_content = "Suatu hari nanti akan ada <color=#FFB400>rumah</color> untukmu, selama kamu tetap menjaga harapan di hatimu. Ketika kamu menemukannya, kedamaian akan kembali padamu—",
  ui_story_5076_50761602_56_dialog_content = "Marcela... Semuanya...",
  ui_story_5076_50761602_57_dialog_content = "*Batuk* Maaf, Achilles.",
  ui_story_5076_50761602_58_dialog_content = "Tapi sepertinya... Perjalananku akhirnya berakhir.",
  ui_story_5076_50761602_59_dialog_content = "Ludweiss... Jadi ini adalah harga yang harus dibayar? Saya mengerti... Bahkan seorang Caelestite pun tidak bisa menahan tragedi sebesar ini...",
  ui_story_5076_50761602_60_dialog_content = "Itulah sebabnya... Aku menyerahkan masa depan di tanganmu.",
  ui_story_5076_50761602_61_dialog_content = "Apakah kita benar-benar pantas mendapatkan ini?",
  ui_story_5076_50761602_62_dialog_content = "Apakah itu bahkan sebuah pertanyaan? Heheh... Saya sangat berterima kasih telah mengenal kalian semua. Berkat kalian, Caelestite yang terus berkelana ini akhirnya menemukan keberanian untuk menatap bintang.",
  ui_story_5076_50761602_63_dialog_content = "Terima kasih semua... Atas cahaya yang kalian berikan pada <color=#FFB400>dunia ini</color>.",
  ui_story_5076_50761602_64_dialog_content = "Aku mengerti... Tenanglah, Ludweiss.",
  ui_story_5076_50761602_65_dialog_content = "Kenanganmu, kehendakmu, hidupmu...",
  ui_story_5076_50761602_66_dialog_content = "Aku akan membawa mereka semua di pundakku.",
  ui_story_5076_50761602_67_dialog_content = "Mungkin tidak ada tempat untukku di masa depan, tapi itu tidak akan menghentikanku untuk membuka jalan bagi teman-temanku!",
  ui_story_5076_50761602_68_dialog_content = "Apa yang kamu pikir kamu lakukan, Achilles? Kenapa kamu belum menghabisi mereka? Kamu tidak sedang merencanakan sesuatu, kan?!",
  ui_story_5076_50761602_69_dialog_content = "Berhenti! Jangan mendekat padaku!",
  ui_story_5076_50761602_70_dialog_content = "Ada sesuatu yang harus kulakukan... Sesuatu yang seharusnya sudah kulakukan sejak lama.",
  ui_story_5076_50761602_71_dialog_content = "Achilles? Apa artinya ini?!",
  ui_story_5076_50761602_72_dialog_content = "Sekarang aku adalah yang tersisa... Aku harus menemukan cara... Untuk melihat kalian semua lagi...",
  ui_story_5076_50761602_73_dialog_content = "Misi terakhirku... Adalah mengambil <color=#FFB400>kerinduanku</color>... Dan menjadikannya batu penjuru dari segel.",
  ui_story_5076_50761602_74_dialog_content = "...",
  ui_story_5076_50761602_75_dialog_content = "Jangan menangis, Adras... Ada seseorang yang menunggumu di masa depanmu.",
  ui_story_5076_50761602_76_dialog_content = "Hal baik akan selalu terjadi selama kamu tetap menyimpan harapan di hatimu...",
  ui_story_5076_50761602_77_dialog_content = "Jadi, tolong jangan menangis lagi.",
  ui_story_5076_50761602_78_dialog_content = "<color=#e8d9bb>Selama ini, semua orang telah terbiasa dengan kehadiran yang menonjol dari pahlawan besar Adras.</color>",
  ui_story_5076_50761602_79_dialog_content = "<color=#e8d9bb>Sangat menenangkan, namun begitu... kesepian. Jika dia harus dimasukkan ke dalam tidur seribu tahun, setidaknya, dia harus diberi teman.</color>",
  ui_story_5076_50761602_80_dialog_content = "<color=#e8d9bb>Ini adalah pertama kalinya \"aku\" menyentuh pedang. Senjata yang berat, bukan sesuatu yang akan diinginkan oleh seorang Caelestite.</color>",
  ui_story_5076_50761602_81_dialog_content = "<color=#e8d9bb>Tapi ini berbeda.</color>",
  ui_story_5076_50761602_82_dialog_content = "<color=#e8d9bb>Ini bukanlah senjata; ini adalah hati yang hangat, yang menyimpan cinta tulus dari teman terdekatku.</color>",
  ui_story_5076_50761602_83_dialog_content = "<color=#e8d9bb>Ketika saya mengambilnya dan meletakkannya di pelukan Adras, senyum menghiasi wajahnya, seperti anak kecil yang baru saja menemukan barang yang telah lama hilang.</color>",
  ui_story_5076_50761602_84_dialog_content = "<color=#e8d9bb>Harus sangat berat untuk bertahan dalam periode kesepian yang begitu lama.</color>",
  ui_story_5076_50761602_85_dialog_content = "<color=#e8d9bb>Yang bisa kulakukan hanyalah memberikan harapan terbaikku, berharap dia bisa menemukan kenyamanan dengan orang yang ada di hatinya saat dia menutup matanya.</color>",
  ui_story_5076_50761602_86_dialog_content = "<color=#e8d9bb>Jika bintang-bintang yang melintas di langit suatu hari nanti bisa menemukan tempat mereka dalam kelembutan waktu...</color>",
  ui_story_5076_50761602_87_dialog_content = "<color=#e8d9bb>May kamu menerima kebahagiaan yang terlambat.</color>",
  ui_story_5076_50761602_88_dialog_content = "Mimpi indah, Adras."
}
return config
